window.IA = {"lang": "hu", "ui": {"app_title": "ClayArena Tolmácsakadémia", "tagline": "Koronglövészet tolmácsoknak – a nulláról", "hero_p": "Tizenkét küldetés, hogy megtanuld a Parcours de Chasse – Sporting™ és a Compak® Sporting nyelvét: a korongokat és röppályájukat, a sörétes puskát, az elétartást és a lövéstechnikát, a FITASC-szabályokat, a bíró döntéseit és a sport etikettjét. Utána gyakorolj úgy, mint egy igazi lőállásban: fordítsd le az edzőt, ismerd fel a korongot, találd meg az elétartást, és hozd meg a bíró döntését.", "missions": "Küldetések", "practice": "Gyakorlás", "start": "Kezdés", "continue": "Folytatás", "lessons_n": "lecke", "min": "perc", "back": "Vissza", "back_mission": "Vissza a küldetéshez", "home": "Főoldal", "key_points": "A lényeg", "coach_says": "Az edző mondja", "listen": "Meghallgatás", "reveal": "Jelentés mutatása", "meaning": "Jelentés", "say_it": "Így mondd", "terms": "Szakkifejezések", "rules_refs": "A FITASC-szabályokban", "sources": "Források", "quiz": "Ellenőrizd magad", "correct": "Helyes!", "wrong": "Nem egészen.", "next": "Tovább", "next_lesson": "Következő lecke", "finish_lesson": "Lecke teljesítve", "xp": "XP", "level": "Szint", "levels": ["Kezdő", "Hallgató", "Lőtéri tolmács", "Lőállás-tolmács", "Profi tolmács"], "done_of": "kész", "game_coach": "Fordítsd le az edzőt", "game_coach_d": "Hallgass meg egy angol edzői mondatot, és válaszd ki, mit jelent valójában.", "game_flight": "Nevezd meg a röppályát", "game_flight_d": "Nézd meg, hogyan repül a korong, és nevezd meg a bemutatást.", "game_lead": "Elétartás-labor", "game_lead_d": "Nézd meg, hogyan működik az elétartás az egyes módszereknél – aztán süsd el te magad.", "game_call": "A bíró döntése", "game_call_d": "Valós helyzetek a lőállásban: mit dönt a bíró?", "game_terms": "Szókártyák", "game_terms_d": "Párosítsd az angol szakkifejezést azzal a szóval, amelyet a lövészek a te nyelveden használnak.", "game_exam": "Záróvizsga", "game_exam_d": "30 kérdés az összes küldetésből. 80%-kal sikeres, és megkapod a tanúsítványt.", "which_flight": "Melyik bemutatás ez?", "which_meaning": "Mit akar mondani az edző?", "which_term": "Hogyan mondják a lövészek a te nyelveden?", "which_def": "Mit jelent ez a szakkifejezés?", "launch": "Indítás", "again": "Újra", "score": "Pontszám", "play_again": "Új játék", "method": "Módszer", "m_maintained": "Elévezetés (maintained lead)", "m_swing": "Áthúzás (swing-through)", "m_pullaway": "Pull-away", "m_ambush": "Lesből lövés (ambush)", "speed": "Korongsebesség", "distance": "Távolság", "demo": "Nézd meg a módszert", "try": "Te jössz: nyomd meg, amikor lőnél", "shoot": "Lövés", "hit": "Találat! A korong eltörik.", "behind": "Mögötte – a sörét a korong mögött ment el", "ahead": "Előtte – a sörét a korong előtt ment el", "perceived": "A döntéskor látott elétartás", "actual": "Valós elétartás a lövés pillanatában", "lab_note": "Lassítás, a tanításhoz egyszerűsített fizika: kb. 330 m/s átlagos sörétsebesség, 0,15 s a döntéstől a lövésig, a sörétkép sugara kb. 10 cm + távolságméterenként 1,5 cm, a csőtorkolat kb. 1 m-re a szemtől. A valós elétartás a sebességtől, a távolságtól, a szögtől és a tölténytől függ; a látott elétartás a módszertől és a lövésztől is.", "exam_pass": "Sikerült! Most megkaphatod a tanúsítványodat.", "exam_fail": "Még nem – 80% kell. Nézd át a küldetéseket, és próbáld újra.", "cert_name": "A neved a tanúsítványra", "cert_print": "Nyomtatás vagy mentés PDF-ként", "cert_title": "Tanúsítvány", "cert_text": "elvégezte a ClayArena Tolmácsakadémia tanfolyamát a Parcours de Chasse – Sporting™ és a Compak® Sporting szakszókincséről, technikájáról, FITASC-szabályairól és etikettjéről.", "cert_note": "A ClayArena önképzési tanúsítványa; nem FITASC-képesítés.", "question": "Kérdés", "of": "/", "term_all": "A ClayArena összes nyelvén", "term_note_anglicism": "A lövészek gyakran egyszerűen az angol szót használják.", "confidence_low": "megerősítésre vár", "reset": "Előrehaladás törlése", "reset_confirm": "Törlöd az összes előrehaladást és XP-t ezen az eszközön?", "saved_local": "Az előrehaladás ezen az eszközön van mentve.", "disclaimer": "A ClayArena tanfolyama. A FITASC-szabályok saját összefoglalásunkban szerepelnek, a szabálypontokra mutató hivatkozásokkal; csak a FITASC hivatalos szövege kötelező érvényű. A Parcours de Chasse – Sporting™ és a Compak® Sporting a FITASC védjegyei.", "language": "Nyelv", "all_missions_done": "Minden küldetés kész – jöhet a záróvizsga!", "decision": "döntés", "shot_moment": "lövés", "lead_word": "elétartás", "unit_m": "m", "unit_ft": "láb", "unit_ms": "m/s", "glossary_page": "Szójegyzék-oldal", "pair_report": "Vadászdublé (on report): a 2. korong az 1. lövés hangjára indul", "pair_sim": "Szimultán dublé: mindkét korong egyszerre indul", "pair_rafale": "Rafale (egymást követő dublé): a 2. korong ugyanabból a gépből, amint a gép újratöltött", "no_shot": "Nem volt lövés.", "at_muzzle": "a csőtorkolatnál nézve", "compare": "Ugyanaz a korong, négy módszer: a valós elétartás ugyanaz, a látott nem", "how_maintained": "A csövek a korong előtt várnak, a korong közeledik hozzájuk. Nyomd meg a „Lövés” gombot, amikor a távolság jónak látszik: ekkor a puska a korong sebességével halad, és tartja ezt az elétartást.", "how_swing": "A csövek a korong mögül indulnak, és gyorsabbak nála. Nyomd meg a „Lövés” gombot, amikor a csövek elhagyják a korong elejét: a késleltetés alatt a puska tovább előz, ezért a valós elétartás nagyobb.", "how_pullaway": "A csövek előbb a koronggal együtt mennek, aztán előre gyorsulnak. Nyomd meg a „Lövés” gombot, amíg a puska még gyorsul: a látott elétartás kisebb a valósnál.", "how_ambush": "A csövek mozdulatlanul várnak egy ponton a korong előtt. Nyomd meg a „Lövés” gombot, mielőtt a korong odaér: a sörétnek idő kell, így ha akkor lősz, amikor a korong már ott van, a lövés mögé megy.", "stop_gun": "A puska megállítása lövéskor (hiba)", "clay_widths": "korongszélesség", "unit_cm": "cm", "unit_in": "hüvelyk"}, "missions": [{"id": "sport", "icon": "flag", "title": "A sport tíz percben", "intro": "Mielőtt egyetlen edzői tanácsot lefordítanál, szükséged van az összképre: mire lőnek valójában, ki írja a szabályokat, hogyan néz ki egy Parcours de Chasse – Sporting™ pálya és egy Compak® Sporting lőtér, és hogyan zajlik egy versenynap. Öt rövid lecke adja meg a térképet; a későbbi küldetések töltik ki a részleteket.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Korongok, nem madarak: mi ez a sport", "body": ["A koronglövészet olyan sport, amelyben a lövész sörétes puskával kis, repülő korongokat lő szét. A korong angolul target vagy clay; a lövészek gyakran bird-nek (madárnak) hívják, de senki nem lő élő állatra. A FITASC-szabályok egyértelműen kimondják, hogy élő állatra lőni tilos, és a biztonság, valamint a környezet védelme az első.", "Minden korongot egy gép, a dobógép (trap) dob ki. A levegőben (vagy a földön) megtett útja a röppálya. A fegyver sima csövű sörétes puska: olyan töltényt lő ki, amely tele van apró szemekkel, a söréttel, és ezek egy kis felhővé szóródnak szét. Ezért a lövész oda irányítja a fegyvert, ahová a korong tart, nem oda, ahol éppen van.", "Ez a tanfolyam a nemzetközi szövetség, a FITASC két versenyszámáról szól. A Parcours de Chasse – Sporting™ (röviden Sporting™) a vadászatot utánozza: a dobógépek mezőkön és erdőkben vannak elrejtve, a korongok pedig úgy repülnek, mint a fogoly, a réce vagy a fácán, vagy úgy gurulnak, mint a nyúl. A Compak® Sporting a kompakt változat: ugyanolyan változatos korongok, de egyetlen kis lőtéren, öt, egy vonalban álló lőállással és hat dobógéppel.", "Hallani fogsz a trapről és a skeetről is. Ezek más versenyszámok, rögzített, ismétlődő röppályákkal; az olimpiai trap és skeet egy másik szövetséghez tartozik. Ne keverd a szabályaikat a Sporting™ vagy a Compak® Sporting szabályaival.", "A találat azonnal látható: a korong eltörik, vagy legalább egy látható darab leválik róla. Ez az egyértelműség teszi a sportot könnyen nézhetővé, és neked is könnyen követhetővé már az első naptól."], "key_points": ["Dobógépekkel kidobott korongokra lőnek, soha nem élő állatokra.", "A sörétes puska apró szemek (sörét) felhőjét lövi ki, ezért a lövész a korong elé irányít.", "A Sporting™ természetes terepen a vadászatot utánozza; a Compak® Sporting ennek kompakt változata egyetlen lőtéren.", "A trap és a skeet más versenyszámok, saját szabályokkal."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting™ is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak® Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "A „bird” korong, nem igazi madár; a B gép a B betűvel jelölt dobógép.", "say": "Figyeld ezt a korongot a B gépből."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Két különböző versenyszám két különböző napon.", "say": "Ma a Sporting pályát járjuk, holnap Compak lesz."}, {"en": "Point it, don't aim it.", "meaning": "A sörétes puskát lendítik, és két szemmel a korongot nézve irányítják, nem célozzák, mint a golyós puskát.", "say": "Irányítsd, ne célozd."}], "quiz": [{"q": "Az edző azt mondja: „Watch the next bird.” Mit fogsz látni?", "options": ["Egy dobozból elengedett élő galambot", "Egy dobógéppel kidobott korongot", "Egy táblán lévő madár alakú papírcélt", "Egy drónt"], "answer": 1, "why": "A „bird” a lövészek szlengjében korongot jelent; a FITASC-szabályok tiltják az élő állatra való lövést."}, {"q": "Mit lő ki a sörétes puska?", "options": ["Egyetlen golyót", "Egy kis, nyílszerű lövedéket", "Apró szemek (sörét) felhőjét", "Festékkel töltött golyót"], "answer": 2, "why": "A sörét apró szemek kis felhőjeként hagyja el a csőtorkolatot, ezért a lövész a mozgó korong elé irányít."}, {"q": "Melyik állítás igaz a Compak® Sporting versenyszámra?", "options": ["Kompakt változat egyetlen lőtéren, egy vonalban álló lőállásokkal", "A skeet versenyszám olimpiai változata", "Csak élő vadmadarakra lövik a terepen", "Egyetlen dobógépet és egyetlen lőállást használ"], "answer": 0, "why": "A Compak® Sporting a Sporting™-stílusú korongokat egyetlen kis lőtérre hozza, öt lőállással és hat dobógéppel."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "A FITASC, a szövetségek és a ClayArena", "body": ["A FITASC a vadászati jellegű koronglövészet nemzetközi szövetsége. Ő írja és frissíti a Parcours de Chasse – Sporting™ és a Compak® Sporting szabályait; az általunk követett kiadások dátuma 2025. 01. 01. A Compak® Sporting egyben a FITASC által védett védjegy, ezért a nevet mindig ®-jellel írják.", "A sport piramisként épül fel. Alul a klubok és a lőterek vannak, fölöttük a nemzeti szövetségek, a nemzeti szövetségek pedig a FITASC tagjai. A nemzeti versenyek lőpályáit a nemzeti szövetség, a nemzetközi versenyekét a FITASC hagyja jóvá. Egy szövetség átadhatja egy klubnak a verseny rendezését, de a szabályok alkalmazásáért továbbra is ő felel.", "A helyszínen a szabályokat a bírók alkalmazzák. Minden bíró egy nemzeti szövetség minősítésével rendelkezik, a főbírónak pedig nemzetközi FITASC-minősítés kell. A nemzetközi versenyeken a zsűri foglalkozik az óvásokkal, a büntetésekkel és a technikai problémákkal. Mindannyiuknak fordítani fogsz, ezért tanuld meg a címeket: bíró, főbíró, zsűri.", "Más szervezetek is léteznek. Nagy-Britanniában és az USA-ban nemzeti egyesületek működtetik a sport saját változatait, például az English Sportingot, eltérő szabályokkal és szavakkal. Egy brit vagy amerikai edző FITASC-versenyen is használhatja ezeket a szavakat; a későbbi küldetések megmutatják, hogyan kezeld ezt.", "A ClayArena az a platform, amely e tanfolyam mögött áll. Versenynaptárakat, szójegyzéket és a FITASC-szabályok közérthető összefoglalóját teszi közzé, a ClayAway révén pedig edzőtúrákat szervez. Ne feledd: csak a FITASC hivatalos szövege kötelező érvényű; az összefoglaló útmutató, nem maga a szabály."], "key_points": ["A FITASC írja a Sporting™ és a Compak® Sporting szabályait (2025. 01. 01-i kiadások).", "Klub, nemzeti szövetség, FITASC: a nemzeti lőpályákat a szövetség, a nemzetközieket a FITASC hagyja jóvá.", "A bírók nemzeti minősítéssel rendelkeznek; a főbíró nemzetközi FITASC-minősítéssel; a zsűri tárgyalja az óvásokat.", "Csak a FITASC hivatalos szövege kötelező érvényű; a ClayArena összefoglalót kínál."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak® Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "Az edző a brit szókincsről átvált a FITASC-elnevezésre.", "say": "Ez CPSA-kifejezés – a FITASC-nál ez szimultán dublé."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "A kérdés a verseny legmagasabb rangú tisztségviselőjének szól.", "say": "A főbírót kérdezd, ne a lőállás bíróját."}, {"en": "The jury will decide this one.", "meaning": "Az ügy túlmegy a lőállás bíróján, a verseny zsűrije elé kerül.", "say": "Ebben a zsűri fog dönteni."}], "quiz": [{"q": "Ki hagyja jóvá egy nemzetközi Sporting™ verseny lőpályáit?", "options": ["A helyi klub", "A nemzeti szövetség", "Az aznapi bíró", "A FITASC"], "answer": 3, "why": "A nemzeti lőpályákat a nemzeti szövetség, a nemzetközieket a FITASC hagyja jóvá."}, {"q": "Milyen minősítéssel kell rendelkeznie a főbírónak?", "options": ["Nemzetközi FITASC-minősítéssel", "Egy klubtagsági kártyával, semmi mással", "A klubja által kiadott nemzeti edzői engedéllyel", "Semmivel: bármely tapasztalt lövész elláthatja"], "answer": 0, "why": "A lőállások bíróinak nemzeti minősítés kell; a főbírónak nemzetközi minősítés a FITASC-tól."}, {"q": "Egy vita során egy ügyfél megmutatja neked a ClayArena szabályösszefoglalóját. Mi a státusza?", "options": ["Felülírja a FITASC hivatalos szövegét", "Csak útmutató; a FITASC szövege kötelező érvényű", "Kötelező érvényű, de csak a Compak® Sporting versenyszámban", "Helyettesíti a bíró döntését a lőálláson"], "answer": 1, "why": "Az összefoglaló segít megérteni a szabályokat, de a bíró és a zsűri a FITASC hivatalos szövegét alkalmazza."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Egy Sporting™ pálya: lőpályák, lőállások és dobógépek", "body": ["A Parcours de Chasse – Sporting™ versenyszámban a terület lőpályákra (layout) van osztva. A lőpálya lőállások olyan csoportja, amelyek együtt 25 korongot adnak: 15 szóló korongot és 5 dublét. A rendszertől függően egy lőpályán három, négy vagy öt lőállás van, mindegyiknek saját dobógépekkel.", "A lőállás (shooting stand) az a hely, ahol a lövész áll: 1 m-es négyzet vagy 1 m átmérőjű kör, vízszintes és nem csúszós. Vigyázz a „stand” szóval: magyarul a kiállítási standra gondolnánk, ezért a stand szót mindig „lőállás”-nak fordítsd. A rotte többi tagja a közelben vár, elég közel ahhoz, hogy kövesse, de soha nem zavarva a lövészt.", "A dobógépeket a terephez igazítva helyezik el, gyakran bokrok vagy fák mögé részben elrejtve, hogy a korongok valódi vadnak tűnjenek: keresztező, bejövő, elmenő, rézsútos, magas vagy alacsony, nyílt terepen vagy fák között. Egy lőállás dobógépeit A, B, C, D betűkkel jelölik, balról jobbra olvasva, ahogy a lőállásból látszik.", "Minden lőállás előtt kotta (target menu) van: lövési sorrendben felsorolja a dobógépeket, és jelzi a különleges korongokat, például a 90 mm-es, 70 mm-es vagy 60 mm-es korongot, a battue-t vagy a nyulat. A lövész elolvassa, mielőtt a lőállásra lép, és neked is el kell olvasnod.", "A röppályákat nehézség szerint sorolják be. Az A osztályú korongot egy átlagos lövész az esetek több mint 80%-ában eltalálja, a B osztályút 60–80%-ban, a C osztályút 40–60%-ban. A C osztályú korong tehát szándékosan nehéz; egy hiba ott nem katasztrófa."], "key_points": ["Egy lőpálya 25 korongot ad: 15 szóló korongot és 5 dublét.", "A lőállás 1 m-es négyzet vagy 1 m-es kör; a stand szót „lőállás”-nak fordítsd, ne „stand”-nak.", "A dobógépek betűjele A, B, C, D, balról jobbra, ahogy a lőállásból látszik.", "A kotta mutatja a dobógépek sorrendjét és a különleges korongokat.", "Nehézségi osztályok: A 80% fölött, B 60–80%, C 40–60%."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "A harmadik lőpályán sok kis korong repül a fák között.", "say": "Ma a hármas lőpálya a nehéz – sok mini korong a fák között."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Előbb nézd meg a dobógépek sorrendjét és a különleges korongokat.", "say": "Ennél a lőállásnál olvasd el a kottát, mielőtt belépsz."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "A korong nehéznek van besorolva; hiba várható.", "say": "A kettes lőállásnál C osztályú korong van, ne aggódj miatta."}], "quiz": [{"q": "Hány korongot ad egy Sporting™ lőpálya?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Minden lőpályatípus 25 korongot ad: 15 szóló korongot és 5 dublét."}, {"q": "Az edző azt mondja: „Go to stand two.” Hogyan fordítod a „stand” szót?", "options": ["„stand” (kiállítási stand)", "„lőállás”", "„lelátó”", "„fegyvertartó állvány”"], "answer": 1, "why": "A Sporting™ versenyszámban a stand az 1 m-es lőhely, magyarul lőállás; a magyar „stand” szó egészen mást jelent."}, {"q": "Hogyan azonosítják egy Sporting™ lőállás dobógépeit?", "options": ["1-től 6-ig számokkal, jobbról számolva", "Az egyes gépekre festett színekkel", "A, B, C, D betűkkel, balról jobbra", "Az indító személy nevével"], "answer": 2, "why": "Az A, B, C, D betűket balról jobbra olvassák, ahogy a lőállásból látszik, és a kotta és az eredménylap is ezeket használja."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Egy Compak® Sporting lőtér: öt lőállás, hat dobógép", "body": ["A Compak® Sporting egyetlen lőtéren elfér. A lövészek előtt egy kötelező téglalap van, 35–40 m széles és 25 m mély, négy zászlós sarokkaróval jelölve. Szélcsendben minden korongnak valamikor át kell repülnie fölötte.", "Öt lőállás – mindegyik 1 m-es négyzet – áll egy vonalban, a középpontjaik között 2–5 m-rel. Balról jobbra 1-től 5-ig számozzák őket. Minden lőálláson lőszögkorlátozó (Firing Angle Limiter) van: csövekből álló keret, amely megakadályozza, hogy a fegyver túlságosan oldalra vagy felfelé lendüljön, és hogy a lövész előrelépjen.", "Hat dobógép van, balról jobbra A-tól F-ig, mindegyiken a betűjelét viselő táblával. Lehetnek elöl, oldalt, a lövészek mögött vagy toronyban; a vonal mögötti dobógépnek legalább 4 m-rel fölötte kell lennie. Minden Compak pályán három kötelező korong van: egy balról jobbra keresztező, egy jobbról balra keresztező és egy elmenő korong.", "Egy kör 25 korong, lőállásonként öt. Amikor egy hatfős rotte lő, öt lövész áll a lőállásokon, a hatodik pedig az 1-es lőállás mögött vár. Minden lövész sorban leadja a lőállás kottájának öt korongját, az 1-es lőállástól kezdve. Amikor az 5-ös lőállás végzett, az a lövész az 1-es lőállás mögé megy várakozni, mindenki más egy lőállással jobbra lép, a várakozó lövész pedig beáll az 1-esre.", "Egyes versenyeken a Compak® Sportingot egyvonalas (in-line) rendszerben lövik: minden lövész az 1-es lőálláson kezd, és az 5-ösön végez. Kérdezd meg a szervezőt, melyik rendszert használják, mert az eljárás eltér."], "key_points": ["35–40 m × 25 m-es téglalap, amely fölött minden korongnak át kell repülnie.", "Öt 1 m-es lőállás egy vonalban, 2–5 m távolságra, mindegyik lőszögkorlátozóval.", "Hat dobógép A-tól F-ig, balról jobbra; a vonal mögötti gép legalább 4 m magas toronyban van.", "Körönként 25 korong, lőállásonként öt; a rotte egy lőállással jobbra forog.", "A Compak® Sporting lőhető rotte-rendszerben vagy egyvonalas rendszerben."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "A rotte forog; az 5-ös lőállás lövésze az 1-es lőállás mögé megy.", "say": "Mindenki egyet jobbra. Az ötös a várakozóhelyre."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "Az E gép korongját egy magas toronyból dobják, és a fej fölött repül át.", "say": "Az E gép a toronyban van – a fejed fölött jön át."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Tartsd tiszteletben a lőszögkorlátozót; ne lendítsd túl rajta a fegyvert.", "say": "Vigyázz a keretre – ne lendíts túl az oszlopon."}], "quiz": [{"q": "Hány dobógép és lőállás van egy Compak® Sporting lőtéren?", "options": ["4 dobógép, 3 lőállás", "6 dobógép, 5 lőállás", "5 dobógép, 6 lőállás", "8 dobógép, 8 lőállás"], "answer": 1, "why": "A–F dobógépek és 1–5 lőállások."}, {"q": "Egy hatfős rottéban hol van a hatodik lövész, amíg a többiek lőnek?", "options": ["A klubházban", "A bíró mellett az 5-ös lőállásnál", "Az F gép mögött", "Az 1-es lőállás mögött várakozik"], "answer": 3, "why": "A várakozó lövész az 1-es lőállás mögött áll, és minden rotáció után belép oda."}, {"q": "Mire való a lőszögkorlátozó (Firing Angle Limiter)?", "options": ["Korlátozza a lendítést, és megakadályozza az előrelépést", "Méri minden kidobott korong sebességét", "Az egész kör töltényeit tartja", "A lövész kérésére indítja a korongokat"], "answer": 0, "why": "Ez minden lőálláson egy biztonsági keret, amely korlátozza az oldalirányú és függőleges lendítést."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Egy versenynap az elejétől a végéig", "body": ["A nap a regisztrációval kezdődik: a lövész megerősíti a nevezését, megkapja a rajtszámát, és a háta felső részére tűzi, teljesen láthatóan. Aztán mindenki megnézi a rottebeosztást és a lövési időpontokat. Az időbeosztás betartása a lövész saját felelőssége.", "A rotte (squad) legfeljebb hat, sorsolással összeállított lövész, akik együtt lőnek. A ClayAway-ben ugyanez az angol szó egy túra alcsoportját is jelenti, ezért tedd világossá, melyikre gondolsz. A Parcours de Chasse – Sporting™ versenyszámban a rotte előbb egy lőállás összes szóló korongját lövi le, aztán a dublékat, és a lövési sorrend lőállásról lőállásra forog. A rotte első lövésze látja a korongok bemutatását, mielőtt bárki lőne.", "Egy kör 25 korong: a Sporting™ versenyszámban egy lőpálya, a Compak® Sporting versenyszámban egy lőtér. Egy nemzetközi verseny 200 korong, tehát nyolc kör több napon át. A bíró minden korongot feljegyez az eredménylapra, általában X-szel a találatot és O-val a hibát. A lövészek a Sporting™ versenyszámban a lőállás elhagyásakor ellenőrzik az eredményüket, a Compak® Sporting kör végén pedig aláírják a lapot.", "A késés drága. A Sporting™ versenyszámban a bíró egy percen belül háromszor szólítja a nevet; az a lövész, aki lekési a sorát, a le nem lőtt korongokra nullát kap. A Compak® Sporting versenyszámban az a lövész, aki azután érkezik, hogy a rotte első lövésze kérte a korongot, a körre 25 nullát kap.", "Ha az első három helyen holtverseny alakul ki, szétlövés következik: 25 korong, aztán hirtelen halál. Az alacsonyabb helyeken a holtversenyt fordított sorrendű összevetéssel döntik el, először az utolsó kört hasonlítva össze. A nap az eredménytáblával és a díjátadással ér véget."], "key_points": ["Regisztráció, rajtszám a háton, rottebeosztás és időpontok.", "A rotte legfeljebb hat, sorsolással összeállított lövész; a Sporting™ versenyszámban előbb a szóló korongok, aztán a dublék, forgó sorrenddel.", "Egy kör 25 korong; a nemzetközi versenyek 200 korongosak.", "A késés nullákba kerül; a Compak® Sporting versenyszámban 25 nullába a körre.", "Holtverseny a dobogón: 25 korongos szétlövés, aztán hirtelen halál; alacsonyabb helyeken fordított sorrendű összevetés."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "A rotte száma, a kezdő lőpálya és a kezdés időpontja.", "say": "A tizenkettes rottéban vagy, kilenc harminckor kezdesz az ötös lőpályán."}, {"en": "Check your card before you leave the stand.", "meaning": "Győződj meg róla most, hogy a bíró helyesen jegyezte fel az eredményedet; később már késő.", "say": "Mielőtt elhagyod a lőállást, ellenőrizd a lapodat."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "25-ből 22 az első körben; egy 200 korongos versenyen még hét kör van hátra.", "say": "Huszonkettő az első körben rendben van – még hét kör jön."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Annak a lövésznek, aki szétlövésbe kerülhet, a szólítás után hamar készen kell állnia.", "say": "Maradj a közelben – ha holtverseny lesz, a szólítástól számított tizenöt percen belül lősz."}], "quiz": [{"q": "Hány korongos egy nemzetközi FITASC-verseny?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 korong, 25-ös körökben."}, {"q": "Rotte-rendszerű Compak® Sporting versenyszámban egy lövész azután érkezik, hogy az első lövész kérte az első korongot. Mi történik?", "options": ["Semmi, beáll", "Arra a körre 25 nullát kap", "Később egyedül, büntetés nélkül lövi le a kört", "Elveszít egy korongot"], "answer": 1, "why": "Rotte-rendszerű Compak® Sporting versenyszámban az első korongkérés utáni késést 25 nullával értékelik; alapos indokkal a zsűrihez lehet fellebbezni."}, {"q": "Két lövész holtversenyben áll az 5. helyen. Hogyan döntik el a sorrendet?", "options": ["25 korongos szétlövéssel", "A verseny után sorsolással", "Fordított sorrendű összevetéssel, az utolsó körtől", "Életkor alapján, a fiatalabb előbb"], "answer": 2, "why": "Szétlövés csak a dobogóért van; alatta a fordított sorrendű összevetés a 8. kört, aztán a 7.-et és így tovább hasonlítja össze."}]}]}, {"id": "gear", "icon": "tool", "title": "Fegyver és felszerelés", "intro": "Az edzők egész nap a fegyverről beszélnek: „raise the comb” (emeld a pofadékot), „check your selector” (nézd meg a sorrendváltót), „change chokes” (cserélj szűkületet), „nines in the bottom” (kilences sörét az alsó csőbe). Ez a küldetés megadja a szavakat a fegyverhez, a részeihez, a szűkületekhez, a töltényekhez és a védőfelszereléshez, valamint azt a néhány felszerelési szabályt, amelyet minden tolmácsnak ismernie kell.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "A sörétes puskák típusai, és amit a szabályok megengednek", "body": ["Minden fegyver, amelyet a lőálláson látni fogsz, sima csövű sörétes puska. Szinte minden versenylőálláson bock (over-and-under, O/U): két cső egymás fölött, amelyet a csuklópántján „megtörve” nyitnak ki. Mindkét csőben lehet saját szűkület (choke), ami a dubléknál számít.", "A duplapuskának (side-by-side) két egymás melletti csöve van. Ez a klasszikus vadászfegyver, megengedett, de versenyen ritkán látni. Az over-and-under szót ne fordítsd egyszerűen „kétcsövű”-nek: az a szó mindkét típust lefedi.", "A félautomatának (semi-automatic) egy csöve van, és minden lövés után magától újratölt, oldalra kivetve az üres hüvelyt. A FITASC feltételekkel engedi: legfeljebb két töltény lehet a fegyverben, hordozáskor a zárnak mindig nyitva kell lennie, a Compak® Sporting versenyszámban pedig olyan eszköz kell, amely megakadályozza, hogy a kivetett hüvelyek eltalálják a szomszédot.", "A pumpás puskák, amelyeket az előagy kézi elcsúsztatásával töltenek újra, sem a Parcours de Chasse – Sporting™, sem a Compak® Sporting versenyszámban nem megengedettek. A szabálykönyvek indoklás nélkül mondják ki a tilalmat, ezért ha egy ügyfél kérdezi, ne találj ki okot; egyszerűen mondd, hogy ez a szabály. A Compak® Sporting a drillingeket is tiltja, vagyis azokat a fegyvereket, amelyek sörétes és golyós csövet egyesítenek.", "Mindkét versenyszámban még két korlát érvényes: a kaliber nem lehet nagyobb 12-esnél (tehát a 20-as rendben van), a csöveknek pedig legalább 66 cm hosszúnak kell lenniük. Fegyverszíj, fegyverre szerelt kamera és bármilyen mesterséges célzóeszköz tilos."], "key_points": ["A legtöbb versenyző bockkal lő.", "A félautomata megengedett: legfeljebb két töltény, hordozáskor nyitott zár, a Compak® Sporting versenyszámban hüvelyfogó.", "A pumpás puska mindkét versenyszámban tilos; a szabályok nem adnak indoklást.", "Kaliber legfeljebb 12-es, cső legalább 66 cm, nincs fegyverszíj vagy célzóeszköz."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "A kétcsövű versenyfegyver és tartalék szűkületek.", "say": "Hozd a bockodat és egy tartalék choke-készletet."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Biztonsági szabály: a félautomatát nyitott zárral kell vinni.", "say": "Félautomatánál tartsd nyitva a zárat, amíg a lőállásra nem érsz."}, {"en": "No pumps on this ground.", "meaning": "Pumpás puskát nem fogadnak el.", "say": "Ezen a lőtéren pumpás puska nem lehet."}], "quiz": [{"q": "Melyik fegyver NEM megengedett a FITASC Sporting™ és Compak® Sporting versenyszámban?", "options": ["20-as kaliberű bock", "Duplapuska", "Pumpás puska", "Félautomata két tölténnyel"], "answer": 2, "why": "A pumpás puska tilos; a többi megengedett, ha megfelel a kaliber- és csőhossz-korlátoknak."}, {"q": "Hány töltény lehet egy félautomatában?", "options": ["Egy", "Kettő", "Három", "Amennyi a tárba fér"], "answer": 1, "why": "Mindkét szabálykönyv két töltényre korlátozza a félautomatát."}, {"q": "Egy ügyfél megkérdezi, miért tilos a pumpás puska. Mi az őszinte válasz?", "options": ["A szabályok kimondják a tilalmat, de nem indokolják", "A szabálykönyv szerint túl lassú a dublékhoz", "A szabálykönyv szerint kevésbé biztonságos", "Valójában a Compak® Sporting versenyszámban megengedett"], "answer": 0, "why": "A szabálykönyvek nem adnak indoklást; tolmácsként közöld a szabályt, és ne találj ki magyarázatot."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "A fegyver részei, a válltól a torkolatig", "body": ["Az edzők folyton megnevezik a fegyver részeit, ezért hátulról előre tanuld meg őket. A tus (stock) kerül a vállba. A felső éle, amelyen az arc nyugszik, a pofadék (comb); a „raise the comb” vagy „drop the comb” (emeld vagy engedd le a pofadékot) a fegyver testre szabásáról szól. Az a keskeny rész, amelyet az elsütő kéz fog, a markolat (grip), a végén lévő gumipárna pedig a tusgumi (recoil pad).", "A fegyver fém középső része a tok (receiver, action; billenőcsövűeknél baszkül). A tetején van a nyitókar (top lever): ha oldalra nyomod, kinyílik a fegyver. Mögötte van a biztosító (safety catch), gyakran egybeépítve a sorrendváltóval (barrel selector, „selector”), amely eldönti, melyik cső sül el először. Alul található az elsütő billentyű (trigger) a sátorvasban.", "A fordított sütésű elsütő (release trigger) akkor sül el, amikor elengedik, nem amikor meghúzzák. Az ilyen fegyveren figyelmeztetésként matricát kell viselni nagy „R” betűvel, fluoreszkáló alapon, a tus külső oldalán.", "A csövek alatt a másik kéz az előagyat (fore-end) fogja. A csöveknek (barrels) hátul van a tölténykamrájuk a töltények számára, elöl pedig a csőtorkolat (muzzles), ahová a szűkületeket csavarják. A tetejükön fut a sín (rib), a végén célgömbbel (bead). A célgömb viszonyítási pont, nem irányzék: „look at the target, not the bead” – a korongot nézd, ne a célgömböt.", "Két hamis barát: a rib nem „borda”, hanem sín, a „break the gun” pedig azt jelenti, hogy nyisd ki (törd meg) a fegyvert, nem azt, hogy tedd tönkre. És egy biztonsági szabály, amely a részekhez kapcsolódik: csütörtök vagy bármilyen más fegyver- vagy lőszerhiba után a lövész nem nyithatja ki a fegyvert, és nem nyúlhat a biztosítóhoz, amíg a bíró meg nem nézte."], "key_points": ["Tus, pofadék, markolat, tusgumi; tok nyitókarral, biztosítóval és sorrendváltóval; elsütő billentyű.", "Előagy, csövek tölténykamrával és csőtorkolattal, sín célgömbbel.", "A fordított sütésű elsütőhöz „R” matrica kell a tuson.", "Rib ≠ „borda”; break the gun = nyisd ki (törd meg).", "Csütörtök után: ne nyisd ki a fegyvert, és ne nyúlj a biztosítóhoz, amíg a bíró meg nem nézte."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "A szem túl magasan van a sín fölött, általában mert a fej felemelkedik a pofadékról.", "say": "Túl sokat látsz a sínből – fent van a fejed."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "A sorrendváltó fordítva van beállítva.", "say": "Nézd meg a sorrendváltót – a felső csővel lőttél először."}, {"en": "Break your gun and show me it's clear.", "meaning": "Nyisd ki a fegyvert, és mutasd meg az üres tölténykamrákat.", "say": "Törd meg a fegyvert, és mutasd, hogy üres."}, {"en": "Forget the bead — look at the target.", "meaning": "A korongra fókuszálj, ne a cső végére.", "say": "Felejtsd el a célgömböt – a korongot nézd."}], "quiz": [{"q": "Az edző azt mondja: „Raise the comb”. Melyik részre gondol?", "options": ["A tus tetejére, ahol az arc nyugszik", "A sín végén lévő kis célgömbre", "Az elsütő billentyű körüli sátorvasra", "A torkolatban lévő szűkületre"], "answer": 0, "why": "A pofadék a tus teteje; ha felemelik, a szem magasabbra kerül a sín fölött."}, {"q": "Mit kell viselnie egy fordított sütésű elsütővel ellátott fegyvernek?", "options": ["Piros festésű csövet a többiek figyelmeztetésére", "Nagy „R” matricát a tuson", "Egy második, külön biztosítót", "Semmit: nincs előírt jelölés"], "answer": 1, "why": "Mindkét szabálykönyv előírja az „R” figyelmeztető matricát, fluoreszkáló alapon, a tus külső oldalán."}, {"q": "Hogyan fordítod: „Break your gun”?", "options": ["„Törd össze a fegyvert”", "„Szedd darabokra a fegyvert”", "„Nyisd ki (törd meg) a fegyvert”", "„Tisztítsd ki a fegyver csöveit”"], "answer": 2, "why": "A lőtéren a „break” azt jelenti, hogy a fegyvert a csuklópántján kinyitják, így nem tud elsülni."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Szűkületek: mit csinálnak, és hogyan beszélnek róluk az edzők", "body": ["A szűkület (choke, csőszűkület) a cső enyhe szűkülése a torkolatnál. Azt szabályozza, milyen gyorsan szóródik szét a sörét. A nagyobb szűkítés tovább tartja együtt a söréteket, és szűkebb sörétképet ad a távoli korongokhoz; a kisebb szűkítés hamarabb szétszórja, és szélesebb, megbocsátóbb sörétképet ad a közeli korongokhoz.", "A legtöbb versenyfegyverben cserélhető szűkület (multichoke, csere choke) van: rövid csövek, amelyeket choke kulccsal csavarnak a torkolatba. A régebbi fegyvereken fix, a csőbe megmunkált szűkület lehet. A különböző gyártók szűkületei gyakran nem illenek egymáshoz, és a gyártók figyelmeztetnek, hogy cserélhető szűkületes fegyverrel soha ne lőjenek szűkület nélkül.", "A nevek angolból jönnek, a nyitottól a szűkig: cylinder (henger), skeet, improved cylinder, light modified, modified, improved modified, full. Európában gyakran törtként mondják őket: negyedes (1/4, improved cylinder), feles (1/2, modified), háromnegyedes (3/4, improved modified) és full (teljes szűkítés). Sok olasz fegyver csillagokkal jelöli a szűkületet, és ott fordított a szabály: több csillag nyitottabb szűkületet jelent.", "Az edzők olyanokat mondanak, mint „quarter and half” (negyedes és feles), „open up the bottom barrel” (nyisd ki az alsó csövet), „go tighter in the top” (szűkebbet a felsőbe) vagy „change chokes for this stand” (cserélj szűkületet ehhez a lőálláshoz). A neveket pontosan úgy add tovább, ahogy az edző mondja; ne váltsd át milliméterre, mert az gyártónként eltér.", "A szabályok a versenyszámok között eltérnek. A Parcours de Chasse – Sporting™ versenyszámban a szűkületet lőállások között, vagy a szóló korongok és a dublék között lehet cserélni, ha nem okoz késést, de soha nem azután, hogy a lövész a lőállásra lépett. A Compak® Sporting versenyszámban a fegyvert, a csöveket és a szűkületeket egy körön belül egyáltalán nem lehet cserélni, csak körök között, kivéve meghibásodás után."], "key_points": ["A szűkület a torkolatot szűkíti: szűkebbet a távoli, nyitottabbat a közeli korongokhoz.", "A cserélhető szűkületeket choke kulccsal csavarják be; a gyártók szerint nélkülük soha ne lőj.", "Törtek: negyedes = improved cylinder, feles = modified, háromnegyedes = improved modified, full.", "A szűkületneveket úgy add tovább, ahogy elhangzanak; ne váltsd át milliméterre.", "Sporting™: csere lőállások között, a lőálláson soha; Compak®: körön belül nincs csere."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Az egyik csőben improved cylinder, a másikban modified.", "say": "Milyen choke van benne? – Negyedes és feles."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Nyitottabb szűkület az első, közelebbi korongra; szűkebb a második, távolabbira.", "say": "Az alsóba negyedest, a felsőbe felest – a második korong messzebb van."}, {"en": "Open up — these are all close.", "meaning": "Tegyél be nyitottabb szűkületeket, mert a korongok közel vannak.", "say": "Nyiss ki – ezek mind közeliek."}, {"en": "Check your tubes are tight before the round.", "meaning": "Győződj meg róla, hogy a szűkületek nem lazultak meg.", "say": "A kör előtt nézd meg, hogy szorosan be vannak-e csavarva a choke-ok."}], "quiz": [{"q": "Melyik szűkület adja a legszélesebb sörétképet?", "options": ["Full", "Improved modified", "Modified", "Cylinder"], "answer": 3, "why": "A cylinder (henger) nem szűkít, ezért abból szóródik szét leghamarabb a sörét."}, {"q": "Sporting™ versenyszámban a már lőálláson álló lövész szűkületet akar cserélni. Megengedett?", "options": ["Igen, ha nem okoz késést", "Nem, ha már a lőálláson van, nem", "Igen, de csak a dublék előtt", "Csak a zsűri engedélyével"], "answer": 1, "why": "Csere lőállások között vagy a szóló korongok és a dublék között megengedett, késés nélkül, de soha nem azután, hogy a lövész a lőállásra lépett."}, {"q": "Egy olasz fegyveren az öt csillaggal jelölt szűkület…", "options": ["a legnyitottabb", "a legszűkebb", "hibás szűkület", "golyós cső"], "answer": 0, "why": "Csillagos jelölésnél a több csillag nyitottabb szűkületet jelent."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Töltények: kaliber, sörétméret és a korlátok", "body": ["A töltény (cartridge) mindent tartalmaz egy lövéshez: a hüvelyt (hull) fém talppal, a csappantyút (primer), a lőport (powder), a fojtást (wad) és a söréteket (shot). A lövészek mondják úgy is: shell. Az „empties” a kilőtt üres hüvelyek.", "A kalibert (gauge) a régi módon számolják: minél kisebb a szám, annál tágabb a furat, így a 12-es kaliber tágabb a 20-asnál. A FITASC legfeljebb 12-es kaliberű fegyvereket enged, és a legtöbb lövész 12-est használ. A „12 gauge” kifejezést soha ne fordítsd „12 mm”-nek.", "A sörétméret is fordított: minél nagyobb a szám, annál kisebb a sörétszem, így a 9-es finomabb a 7½-esnél. Ugyanaz a szám kissé eltérő méretet jelenthet Nagy-Britanniában, a kontinentális Európában és az USA-ban, ezért a számot úgy mondd, ahogy elhangzott, a millimétert pedig nézd meg a dobozon. A „nines” (kilences) és a „seven-and-a-halfs” (hét és feles) gyakori edzői szavak.", "A Parcours de Chasse – Sporting™ és a Compak® Sporting szabályai azonosak: legfeljebb 28 g ólomsörét, +2% tűréssel; 2,0–2,5 mm-es (±0,1 mm) gömbölyű sörétszemek. Tilos az újratöltött töltény, a szórófojtás (disperser), a vegyes sörétméret, a fekete lőpor és a nyomjelző. A Sporting™ versenyszámban a bíró két töltényt vehet el ellenőrzésre, a mellény mindkét zsebéből egyet-egyet; a Compak® Sporting versenyszámban az ellenőrzés előtt nem megfelelő töltényekkel leadott lövések nullának számítanak.", "Egyes lőterek saját környezetvédelmi szabályokat is alkalmaznak az edzéseken, például csak rostfojtás vagy csak acélsörét: a túra előtt nézd meg a lőtér szabályait. Az üres hüvelyek a lőálláson lévő gyűjtőbe kerülnek, a félautomatával lövők pedig távozáskor összeszedik a kivetett hüvelyeiket."], "key_points": ["Töltény = hüvely, csappantyú, lőpor, fojtás, sörét.", "Kaliber: kisebb szám, tágabb furat; a FITASC-maximum 12-es kaliber.", "Sörétméret: nagyobb szám, kisebb sörétszem; a számozás országonként eltér, nézd meg a millimétert.", "Korlátok: 28 g ólom (+2%), sörétszem 2,0–2,5 mm; nincs újratöltött töltény, vegyes sörét, fekete lőpor vagy nyomjelző.", "Az üres hüvelyek a gyűjtőbe kerülnek; a félautomatával lövők összeszedik a hüvelyeiket."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Finomabb, 9-es sörét a közeli korongokra, nagyobb, 7½-es a távoli keresztezőkre.", "say": "Kilencest a közeliekre, hét és felest a messzi keresztezőkre."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "A verseny töltetsúly-korlátja, a FITASC-szabályok szerint.", "say": "Ezen a versenyen legfeljebb huszonnyolc gramm."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "A kilőtt hüvelyeket tedd a gyűjtőbe.", "say": "Az üres hüvelyeket a gyűjtőbe, kérlek, ne a fűre."}, {"en": "Steel only on this ground.", "meaning": "Ezen a lőtéren ólomsörét nem megengedett (helyi szabály, nem FITASC-szabály).", "say": "Ezen a lőtéren csak acélsörét."}], "quiz": [{"q": "Melyik a finomabb sörét?", "options": ["7-es", "7½-es", "8-as", "9-es"], "answer": 3, "why": "Minél nagyobb a sörétszám, annál kisebb a sörétszem."}, {"q": "Mekkora a legnagyobb töltetsúly a FITASC-szabályok szerint?", "options": ["24 g, tűrés nélkül", "28 g, +2% tűréssel", "32 g, csak távoli korongokra", "Nincs korlát, bármilyen töltet megengedett"], "answer": 1, "why": "Mindkét versenyszám legfeljebb 28 g ólomsörétet enged, +2%-kal."}, {"q": "Egy ügyfél azt mondja, hogy a fegyvere „12 gauge”. Mit jelent ez?", "options": ["A furat méretét: tágabb a 20-as kalibernél", "A furat 12 milliméter átmérőjű", "Tizenkét töltény fér a tárba", "A csövek 12 hüvelyk hosszúak"], "answer": 0, "why": "A kaliber régi mértékegység: minél kisebb a szám, annál tágabb a furat. Nem milliméter."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Védőfelszerelés, mellény és öltözködési szabályok", "body": ["A hallásvédelem mindenkinek kötelező a lőpályán vagy annak közelében: lövészeknek, bíróknak, személyzetnek és nézőknek, és ez rád is vonatkozik. A füldugó (earplugs) és a fülvédő (ear muffs) egyaránt megfelel; az elektronikus fülvédő felerősíti a hangokat, és elnyeli a durranást, így jobban hallod az edzőt és a bírót. Azt a lövészt, aki védőeszköz nélkül érkezik a lőállásra, távollévőnek tekintik.", "A lövészszemüveg (safety glasses) is kötelező a lövészeknek, a bíróknak és a személyzetnek, a Parcours de Chasse – Sporting™ versenyszámban pedig mindenkinek, aki egy lőállás közelében van. A lencsék többféle színben kaphatók (sárga, narancs, lila, füstszürke), hogy különböző fényviszonyok között is jól látszódjanak a korongok.", "A lőmellény (shooting vest) két elülső zsebében tartja a töltényeket, és vállpárnája van. A Sporting™ versenyszámhoz kontrasztos vízszintes vonal van rajta, 25 cm-rel a vállak tengelye alatt: a korong kérése előtt a tus tetejének alatta kell maradnia, és ezt a bíró ellenőrzi. A Compak® Sporting versenyszámban nincs ilyen vonal, mert a fegyver helyzete a korong kérésekor szabad.", "Az öltözködési szabályok mindkét versenyszámban azonosak: nincs rövid sort (csak legfeljebb 5 cm-rel térd fölött végződő hosszú rövidnadrág), a felső legalább rövid ujjú, nincs csupasz felsőtestre vett mellény, és biztonsági okból nincs szandál. A rajtszámot a háton, teljesen láthatóan kell viselni. A szabálysértés először figyelmeztetéssel jár, aztán további büntetésekkel.", "Sok lövész nap és eső ellen siltes sapkát és kesztyűt is visel, és töltényes táskában viszi a napi készletet. Ezek szokások, nem szabályok."], "key_points": ["A fülvédő mindenkinek kötelező a lőpálya közelében, a tolmácsoknak is.", "A lövészszemüveg kötelező; védőeszköz nélkül a lövészt távollévőnek tekintik.", "Sporting™ mellény: kontrasztos vonal 25 cm-rel a vállak tengelye alatt; a Compak® versenyszámban nincs.", "Öltözet: rövidnadrág legfeljebb 5 cm-rel térd fölött, ujjas felső, nincs csupasz felsőtest a mellény alatt, nincs szandál.", "Rajtszám a háton, teljesen láthatóan."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Mielőtt a lőálláshoz mész, tedd fel a fülvédőt és a szemüveget.", "say": "Fülvédő és szemüveg fel, mielőtt odamész."}, {"en": "Butt under the tape until you see the target.", "meaning": "A Sporting™ leengedett fegyveres szabálya: a tus a mellényen lévő vonal alatt marad, amíg a korong meg nem jelenik.", "say": "A tus a csík alatt, amíg nem látod a korongot."}, {"en": "No marker needed here — it's Compak.", "meaning": "A Compak® versenyszámban nincs mellényvonal-követelmény.", "say": "Itt nem kell jelölés – ez Compak."}], "quiz": [{"q": "Tolmácsként a lőállás közelében állsz. Kötelező fülvédőt viselned?", "options": ["Nem, csak a lőálláson álló lövészeknek", "Csak döntőkben és szétlövéseken", "Igen, mindenkinek a lőpályán vagy annak közelében", "Csak ha a bíró megkér rá"], "answer": 2, "why": "A hallásvédelem a lövészeknek, a bíróknak, a személyzetnek és a nézőknek is kötelező."}, {"q": "Hol van a mellényvonal a Sporting™ versenyszámban?", "options": ["25 cm-rel a vállak tengelye alatt", "A derékon, az övvonalon", "A lövőkar ujján", "A Sporting™ versenyszámban nincs ilyen"], "answer": 0, "why": "A kontrasztos vonal 25 cm-rel a vállak tengelye alatt, azzal párhuzamosan fut; a korong megjelenése előtt a tusnak alatta kell maradnia."}, {"q": "Melyik lábbeli tilos mindkét versenyszámban?", "options": ["Terepfutó cipő", "Szandál", "Bakancs", "Edzőcipő"], "answer": 1, "why": "A szandál biztonsági okból tilos."}]}]}, {"id": "targets", "icon": "target", "title": "Korongok", "intro": "Az az edző, aki azt mondja: „it's a midi off the tower, then a rabbit on report” (egy midi a toronyból, aztán egy nyúl vadászdubléban), feltételezi, hogy el tudod képzelni. Ez a küldetés megtanítja a korongtípusokat, azt, hogy a szín és a fény hogyan változtatja meg, amit a lövész lát, hogyan indítják a dobógépek a korongokat, hogyan kell kiolvasni a kottát, és azt az egyetlen pontozási kérdést, amely mindent eldönt: találat vagy hiba.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Korongtípusok: standard, midi, mini, battue, nyúl, flash, ZZ", "body": ["A FITASC listája a Parcours de Chasse – Sporting™ számára hét korongtípust nevez meg: standard, midi, super mini, battue, nyúl (rabbit), flash és ZZ. A Compak® Sporting bármilyen standard vagy különleges korongot megenged, és a listája a rakéta korongot (rocket) is megnevezi. Minden típus másként repül.", "A standard, a leggyakoribb korong, egy kb. 108–110 mm átmérőjű kupola. A midi 90 mm-es: jól megtartja a sebességét, és messzebbinek látszik, mint amilyen. A mini 60 mm-es: gyorsan hagyja el a dobógépet, és gyorsan lassul, ezért a lövészek hajlamosak túl sok elétartást adni neki. A Sporting™ listája a kis korongot „super mini”-nek hívja, a kottára vonatkozó szabály pedig 70 mm-es és 60 mm-es méretet is megnevez; a neveket nem használják következetesen, ezért mindig a kottára írt millimétert kövesd.", "A battue lapos, vékony, 110 mm-es korong. Élével repül, szinte láthatatlanul, aztán megfordul, megmutatja a lapját, és gyorsan esik. A nyúl 110 mm-es korong vastag, erős peremmel, amelyet élén gurítanak a földön; pattog, és a buckákon átugorhat. Magyarul „nyúl” vagy „nyúlkorong” hallható; ez a tanfolyam a „nyúl” szót használja.", "A flash korong színes porral van töltve, amely találatkor fényes felhőt hagy; ugyanúgy értékelik, mint bármely más korongot. A ZZ korong, más néven helice, fehér középső sapkás műanyag propeller, amely kiszámíthatatlanul repül. A rakéta különleges korong, amelyet csak a Compak® Sporting listája nevez meg; műszaki adatokat nem adunk meg róla.", "A Sporting™ versenyszámban a rossz színű, méretű vagy típusú korong „No bird”, és megismétlik."], "key_points": ["Sporting™ lista: standard, midi, super mini, battue, nyúl, flash, ZZ; a Compak® bármilyen típust megenged, a rakétát is.", "Standard kb. 108–110 mm, midi 90 mm, mini 60 mm; a kottán 70 mm is szerepelhet – a milliméter számít.", "Battue: lapos, élével repül, megfordul és esik; nyúl: vastag perem, gurul és ugrik.", "A flash porfelhőt hagy; a ZZ propeller alakú korong.", "Sporting™: rossz szín, méret vagy típus = „No bird”."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "A 90 mm-es korong messzebbinek látszik, mint amilyen, ezért kevesebb elétartás kell neki, mint amit a lövész gondol.", "say": "A midi messzinek látszik, de nem az – ne adj neki túl sokat."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Akkor lődd a battue-t, amikor a lapos oldalát feléd fordítja.", "say": "A battue a végén megfordul és esik – akkor lődd, amikor megmutatja a hasát."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "A kis korong gyorsan veszít a sebességéből; ne várj.", "say": "A mini gyorsan hal el – lődd korán."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Guruló korongnál tartsd lent a csöveket, hogy egy ugrásnál is a sörétbe fusson.", "say": "A nyúl azon a buckán ugrik – maradj alatta."}], "quiz": [{"q": "Melyik korong gurul a földön?", "options": ["Midi", "Battue", "Nyúl", "Flash"], "answer": 2, "why": "A nyúlnak vastag pereme van, és élére állítva dobják a földön."}, {"q": "A kottán az áll: „70 mm”. Az edző mininek hívja. Mit fordíts?", "options": ["Javítsd 60 mm-re, mert a mini 60 mm-es", "Tartsd meg az edző szavát és a kottán szereplő 70 mm-t", "Nevezd midinek, mert 60 mm fölött van", "Kérd meg az edzőt, hogy inkább „super mini”-t mondjon"], "answer": 1, "why": "A szabályok 70 mm-es és 60 mm-es méretet, valamint a „super mini” nevet is megnevezik; bízz a kottán lévő milliméterben, és ne javítsd ki az edzőt."}, {"q": "Egy Sporting™ lőálláson a dobógép a kottán szereplő standard helyett midit dob. Mi történik?", "options": ["„No bird”, a korongot megismétlik", "Találatnak számít", "A lövész elveszíti a korongot", "A kört törlik"], "answer": 0, "why": "A Sporting™ versenyszámban a rossz színű, méretű vagy típusú korong „No bird”, és megismétlik."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Színek, fény és láthatóság", "body": ["Mindkét szabálykönyv ugyanazt kéri: a korong színének jól el kell válnia a háttértől. A kétszínű korongok nem ajánlottak. A szín tehát a pályaépítő választása, minden röppályához külön, nem önálló korongtípus.", "Hallani fogsz fekete, narancs, fehér, sárga és rózsaszín korongokról. Sok pályaépítő az ég előtt feketét, a fák és a fű előtt narancsot használ. A „blazed” korong kupolája élénk narancsra van festve. Vigyázat: amikor az edző azt mondja: „the orange one” (a narancs), színre gondol, nem méretre. Egy fekete midi és egy narancs standard ugyanabból a lőállásból is jöhet.", "Ha rossz színű korongot dobnak, a bíró „No bird”-öt mond, és megismétlik. A Compak® Sporting szabályai hozzáteszik, hogy a rossz idő soha nem ok a „No bird”-re: az eltört korong számít, az elhibázott elveszett, bármilyenek is a körülmények. A Parcours de Chasse – Sporting™ versenyszámban a bíró rövid, heves vihar vagy felhőszakadás idejére szüneteltetheti a lövészetet.", "A fény mindent megváltoztat. Az edzők beszélnek az ellenfényről (a nap a korong mögött van), a szürke napok lapos fényéről, a fák alatti árnyékokról és a korong mögötti háttérről: égbolt, erdőszél vagy talaj. Egy korong „eltűnhet” a sötét fák előtt, és „kiugorhat” az ég előtt. Ezért cserélnek a lövészek napközben lencseszínt.", "Fordításkor a szín- és fényszavakat pontosan és röviden add vissza: „it's coming out of the dark trees” (a sötét fák közül jön ki), „you lose it in the sun” (elveszíted a napban). Ezek megmagyarázzák, miért hibázott a lövész, ezért számítanak."], "key_points": ["A korong színének el kell válnia a háttértől; a kétszínű korongok nem ajánlottak.", "A szín nem típus: „the orange one” szín, nem méret.", "Rossz szín = „No bird”.", "Compak®: a rossz idő soha nem indokol „No bird”-öt; a Sporting™ bírói rövid viharnál szüneteltethetnek.", "Ellenfény, lapos fény, háttér: a fényszavakat pontosan fordítsd."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "A lőállás két korongja színben és méretben különbözik.", "say": "A fekete a midi, a narancs a standard – ne keverd össze őket."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "A korongot nehéz látni a fák előtt; ott kezdd figyelni, ahol mögötte az ég van.", "say": "A fák előtt elveszíted – vedd fel később, az égen."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Szürke, kontraszt nélküli fény; a sárga lencse javítja a kontrasztot.", "say": "Ma lapos a fény – tedd be a sárga lencsét."}], "quiz": [{"q": "Mit írnak elő a szabályok a korong színére?", "options": ["Mindig narancsnak kell lennie", "Jól el kell válnia a háttértől", "Kétszínűnek kell lennie", "Bármilyen színű lehet: a szabályok hallgatnak"], "answer": 1, "why": "A követelmény a háttér előtti láthatóság; a kétszínű korongok nem ajánlottak."}, {"q": "Compak® Sporting versenyszámban erősen esni kezd, és egy lövész hibázik. Kérhet „No bird”-öt az időjárás miatt?", "options": ["Igen, az időjárás mindig indokolja", "Csak a dublé első korongjánál", "Csak ha a zsűri beleegyezik", "Nem, az időjárás soha nem indokol „No bird”-öt"], "answer": 3, "why": "A Compak® Sporting szabályai kimondják, hogy az időjárás soha nem ok a „No bird”-re."}, {"q": "Az edző azt mondja: „Watch the orange one.” Mit ír le?", "options": ["Egy korong színét", "Egy 90 mm-es korongméretet", "Egy nyulat", "Egy eltört korongot"], "answer": 0, "why": "A színt a láthatóság miatt választják, és semmit nem mond a méretről vagy a típusról."}]}, {"id": "targets-traps", "minutes": 5, "title": "Dobógépek, indítás és a puller", "body": ["A dobógép (trap) az a gép, amely a korongokat dobja. A dobógépek lehetnek kéziek vagy automaták (a Compak® Sporting szabályai félautomatákat is említenek). A Parcours de Chasse – Sporting™ versenyszámban egy lőállás dobógépeit A, B, C, D betűkkel jelölik, balról jobbra, ahogy a lőállásból látszik; a Compak® Sporting versenyszámban a hat dobógép A-tól F-ig van jelölve, mindegyik betűjeles táblával. Fordításkor tartsd meg a latin betűket: a kotta is ezeket használja.", "A lövész a korong kérésével indítja a korongot: a szabályok a „pull” vagy „ready” szót nevezik meg, bár a gyakorlatban a lövészek kérőszavai eltérnek. A Sporting™ versenyszámban a bíró hangjelzéssel továbbítja a parancsot a pullernek (gépkezelőnek, aki az indítást kezeli), és a korongnak három másodpercen belül ki kell repülnie. Magát a kérőszót ne fordítsd le: ez parancs a gépnek, nem mondat.", "A Compak® Sporting versenyszámban a korongokat kézzel, távirányítóval vagy hangvezérléssel (sonopull) lehet indítani. Kézi indításnál a korong 0–3 másodperccel a kérés után repül ki; a hangvezérlésnek fix 0,5 másodperces késleltetése van. A nemzetközi egyvonalas Compak® Sporting csak hangvezérlést használ, elektronikus bírálattal.", "A hangvezérlésnek mikrofonja van a lőálláson. A te hangod is elindíthatja. Ilyen lőálláson soha ne beszélj hangosan, amíg a lövész készenlétben áll: a korongok között suttogj, vagy lépj hátrébb.", "A dobógép hibái „No bird”-nek számítanak: a kérés után több mint három másodperccel kirepülő korong, a rossz gépből jövő korong, a kérés nélkül dobott korong, a Sporting™ versenyszámban ugyanannak a lőállásnak két gépéből jövő két korong, vagy ugyanannak a Compak pályának egy gépe által tévedésből dobott korong."], "key_points": ["Dobógépek: Sporting™ lőállásonként A–D, Compak® lőtéren A–F; tartsd meg a latin betűket.", "A kérés („pull”, „ready”) indítja a korongot; ne fordítsd le.", "Sporting™: a bíró jelez a pullernek; a korong 3 másodpercen belül.", "Compak®: kézi 0–3 s, távirányító vagy fix 0,5 s késleltetésű hangvezérlés.", "A késő, rossz gépből jövő vagy kéretlen korong „No bird”; a mikrofon hall téged."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "A gép röppályája megváltozott; a lövésznek a lövés előtt jeleznie kell.", "say": "A B gép alacsonyabban dob, mint a bemutatáson – szólj a bírónak."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Mikrofon indítja a korongokat; a beszéd kilőhet egyet.", "say": "Itt hangvezérlés van – ne beszélgess a lőálláson."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "A korong több mint három másodperccel a kérés után repült ki.", "say": "A puller késett ennél – ez no bird."}], "quiz": [{"q": "A Sporting™ versenyszámban mennyi idő telhet el a bíró jelzése és a korong kirepülése között?", "options": ["Legfeljebb 1 másodperc", "Legfeljebb 3 másodperc", "Legfeljebb 10 másodperc", "Bármennyi"], "answer": 1, "why": "A három másodpercnél később indított korong „No bird”."}, {"q": "Mekkora a Compak® hangvezérlés fix késleltetése?", "options": ["0 másodperc", "3 másodperc", "0,5 másodperc", "Minden lövész maga állítja be"], "answer": 2, "why": "A hangvezérlésnek fix, nem változtatható 0,5 másodperces késleltetést kell alkalmaznia."}, {"q": "Hangvezérlésű lőálláson vagy, és a lövész készenlétben áll. Mit teszel?", "options": ["Hangosan fordítasz, hogy hallja", "Megkéred a pullert, hogy várjon egy pillanatot", "Megismétled neki a kérőszót", "Csendben maradsz; csak a korongok között suttogsz"], "answer": 3, "why": "A hangod beindíthatja a mikrofont, és kilőhet egy korongot, amelyet senki nem kért."}]}, {"id": "targets-menu", "minutes": 5, "title": "A kotta kiolvasása", "body": ["A kotta (target menu) a lőállásnál lévő tábla, amely megmondja a lövésznek, mi következik. Angolul a lövészek tényleg „menu”-t mondanak, magyarul pedig „kotta” (néha „menü”), ezért ezt a szót használd.", "A Parcours de Chasse – Sporting™ versenyszámban a kotta lövési sorrendben sorolja fel a dobógépeket, és fel kell tüntetnie a különleges korongokat: 90 mm, 70 mm, 60 mm, battue vagy nyúl. A bírók előre ellenőrzik, hogy a gépek megfelelnek-e a kottának. Egy lőpálya 15 szóló korongot és 5 dublét ad, a dublékhoz pedig csak olyan korongokat lehet használni, amelyeket ugyanabból a lőállásból már szóló korongként bemutattak. A rotte előbb a szóló korongokat lövi, aztán a dublékat.", "A dublét a típusával jelölik: vadászdublé (on report – a második korong az első lövés hangjára indul), szimultán (mindkettő egyszerre) vagy rafale (kettő ugyanabból a gépből, egymás után; csak Sporting™). A kották lőterenként másként néznek ki, ezért a szavakat olvasd, ne csak a betűket. Példa egy háromgépes lőállásra: szóló korongok A, B, C; dublék A + B szimultán és C + C rafale (egy ilyen lőálláson két vadászdublé nem megengedett).", "A Compak® Sporting versenyszámban mind az öt lőálláson ki van függesztve egy kotta. Minden lőálláson öt korong van: öt szóló, három szóló és egy dublé, vagy egy szóló és két dublé. A dublé típusa egy Compak pálya mind az öt lőállásán ugyanaz, és minden dublé első korongja az előző lőállás utolsó korongja. A FITASC 40 kész kottát kínál a versenyekhez.", "Mielőtt a lövészed fellép, olvasd fel neki a kottát a saját nyelvén, betűről betűre: „A, aztán F, aztán B, aztán a C és E vadászdublé.”"], "key_points": ["Magyarul „kotta” (angolul menu).", "Sporting™ kotta: a gépek sorrendje plusz a különleges korongok (90, 70, 60 mm, battue, nyúl).", "15 szóló + 5 dublé; a dublék már szólóként bemutatott korongokat használnak; előbb a szóló korongok.", "Dublék: vadász, szimultán, rafale (csak Sporting™).", "Compak®: lőállásonként öt korong, minden lőálláson ugyanaz a dublétípus, minden dublé az előző lőállás utolsó korongjával kezdődik."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then B, then the pair C and E on report.", "meaning": "3-as lőállás: három szóló korong, aztán egy vadászdublé; összesen öt korong.", "say": "Olvasd el a kottát: a hármas lőálláson A, aztán F, aztán B, aztán a C és E vadászdublé."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "A sorrend megváltozott a legutóbbi kör óta.", "say": "Ugyanazok a gépek, új kotta – ne emlékezetből lőj."}, {"en": "Three singles, then a simo pair.", "meaning": "A „simo” a szimultán dublé rövidítése.", "say": "Három szóló, aztán egy szimultán dublé."}], "quiz": [{"q": "Milyen különleges korongokat kell feltüntetnie egy Sporting™ kottának?", "options": ["Csak a korongok színét", "90 mm, 70 mm, 60 mm, battue vagy nyúl", "Csak a nyulakat és a battue-ket", "Semmit; a bíró bejelenti őket"], "answer": 1, "why": "A kottának sorrendben fel kell sorolnia a dobógépeket és minden különleges korongtípust."}, {"q": "A Compak® Sporting versenyszámban melyik koronggal kezdődik minden dublé?", "options": ["Mindig az A géppel", "Egy még soha nem látott koronggal", "Az előző lőálláson utoljára lőtt koronggal", "Bármelyik koronggal, amelyet a lövész választ"], "answer": 2, "why": "A dublék láncot alkotnak a lőállásokon át: mindegyik az előző lőállás utolsó korongjával kezdődik."}, {"q": "Melyik dublétípus létezik csak a Sporting™ versenyszámban?", "options": ["Rafale", "Vadászdublé", "Szimultán", "Egyik sem"], "answer": 0, "why": "A Compak® dublék vadász- vagy szimultán dublék; a rafale Sporting™ dublé."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Találat vagy hiba: a látható darab és a „füst” csapdája", "body": ["Egy korongot „egy”-nek (találat) értékelnek, ha szabályosan dobták, a lövész a szabályok szerint lőtt, és legalább egy darab láthatóan levált róla, vagy a korong teljesen vagy részben megsemmisült. A flash korongokra ugyanez a szabály vonatkozik. Egy korong „nulla” (hiba), ha nem válik le róla látható darab, és csak por vagy füst látszik.", "A szabály tehát egyetlen képen múlik: a látható darabon. Egy kis leváló forgács találatnak számít. Egy porpamacs, miközben a korong egy darabban repül tovább, hiba. Az eredménylapon a találatot általában X-szel, a hibát O-val jelölik.", "Csak a bíró dönt. A rottetársak nem mondhatnak véleményt, és senki nem veheti fel a korongot, hogy megvizsgálja. A Compak® Sporting versenyszámban a bíró minden nullát hangosan vagy hangjelzéssel bejelent. A Parcours de Chasse – Sporting™ versenyszámban a lövésznek ott kell eltalálnia a korongokat, ahol a bíró látja őket. A következő korong kérésével a lövész elfogadja az előzőre vonatkozó döntést, ezért minden kifogást azonnal jelezni kell.", "És most a tolmácsok csapdája. Az edzők a tökéletes találatot így dicsérik: „smoked it”, „inked it” vagy „powdered it” (porrá lőtte): a korong fekete felhővé vált. Ez a lehető legjobb találat, nem nulla. A szabályokban viszont a „csak por vagy füst” hibát jelent. A „dusted it” kockázatos: általában azt jelenti, hogy csak por szállt fel, tehát hiba, de egyesek dicséretként használják. Ha nem vagy biztos benne, kérdezz rá, mert a két jelentés ellentétes.", "Továbbá: a „dead” találatot jelent (nem „halott”-at), a „lost” hibát (nem azt, hogy „eltűnt”)."], "key_points": ["Egy = legalább egy látható darab levált, vagy a korong teljesen vagy részben megsemmisült.", "Nulla = nincs látható darab, csak por vagy füst.", "Csak a bíró dönt; korongot felvenni tilos; a következő korong kérése elfogadja a döntést.", "Edzői szleng „smoked it” = tökéletes találat; szabálybeli „csak füst” = hiba.", "„Dead” = találat, „lost” = hiba; ha a „dusted” nem egyértelmű, kérdezz rá."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Tökéletes találat: a korong porrá vált; a lövész jegyezze meg ezt a képet.", "say": "Porrá lőtted! Ez az a kép."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Egy kis látható darab levált, tehát találat.", "say": "Talált – csak egy kis darab, de számít."}, {"en": "Lost — you were just behind it.", "meaning": "Hiba; a lövés a korong mögött ment el.", "say": "Nulla – épp mögötte voltál."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "A kifogást azonnal jelezni kell; a következő korong kérése elfogadja a döntést.", "say": "Ne később vitatkozz velem – most mondd, mielőtt kéred a korongot."}], "quiz": [{"q": "A korong egészben repül tovább, de egy porpamacs jelenik meg. Mi az eredmény?", "options": ["Nulla (hiba)", "Egy (találat)", "„No bird”", "Fél pont"], "answer": 0, "why": "Ha csak por vagy füst látszik, látható darab nélkül, az hiba."}, {"q": "Az edző bekiáltja: „Smoked it!” Hogyan fordítod a jelentését?", "options": ["Csak füstölt, tehát a korong hiba", "Túlmelegedtek a csövek", "Tökéletes találat: a korong porrá vált", "Kigyulladt a dobógép"], "answer": 2, "why": "Az edzői szlengben a „smoked it” dicséret a teljes törésre; a szabályok „csak füst” megfogalmazása az ellenkezőjét jelenti."}, {"q": "Egy rottetárs azt mondja, hogy az utolsó korong találat volt. Ki dönt?", "options": ["A rotte szavazása", "Az edző", "A tolmács", "Egyedül a bíró"], "answer": 3, "why": "A korongokról a bíró dönt; a rottetársak nem avatkozhatnak be."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Hogyan repülnek a korongok (bemutatások)", "intro": "Az edzők minden korongot aszerint neveznek meg, hogyan repül: keresztező (crosser), bejövő (incomer), teal, íves (looper), nyúl (rabbit), vadászdublé (report pair). Hat rövid leckében megtanulod, mit jelentenek ezek a nevek, mit kell velük kezdenie a lövésznek, és melyik szavakat könnyű félrefordítani.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "A keresztező: oldalirányban átrepülő korong", "body": ["A keresztező (crosser) a lövész előtt oldalirányban repül át, nagyjából derékszögben a látóirányra: balról jobbra (írva B→J, angolul L→R) vagy jobbról balra (J→B, angolul R→L). A Parcours de Chasse – Sporting™ lőpályán a szabályok keresztező, rézsútos, bejövő és elmenő korongok keverékét kérik. A Compak® Sporting versenyszámban a balról jobbra és a jobbról balra keresztező a három kötelező röppálya közül kettő, így minden Compak pályán megvan.", "A keresztező a teljes oldalirányú sebességét mutatja, ezért ennél kell a legnagyobb elétartás (az előretartás) az összes bemutatás közül, és minél messzebb van, annál több elétartás kell. A „long crosser” messzi keresztezőt jelent, nem olyat, amelyik sokáig repül.", "Olvasd ki a vonalát és a sebességét: laposan repül, emelkedik, vagy a lövési pontnál már esik? Mutatja a „lapját” (a domború tetejét vagy a hasát), vagy csak az élét? Lassul? A lassuló keresztezőhöz kevesebb elétartás kell, mint a teljes sebességűhöz.", "Tipikus terv: lábak a lövési pontra állítva, a szem korán felveszi a korongot, aztán pull-away vagy elévezetés, a fegyver a lövéskor is mozog. Keresztezőnél az edző egyik leggyakoribb ítélete: „behind” (mögé) – kevés volt az elétartás, vagy megállt a cső.", "Az irányokat mindig a lövész szemszögéből adják meg. Ha a lövésszel szemben állsz, az ő „balról jobbra” iránya neked jobbról balra, ezért soha ne fordítsd meg a szavakat."], "key_points": ["A keresztező kb. 90°-ban repül át a látóirányra: B→J vagy J→B.", "Ennél kell a legtöbb elétartás; nagyobb távolság = több elétartás.", "„Long crosser” = messzi, nem hosszan tartó.", "A Compak® Sporting versenyszámban mindig van B→J és J→B keresztező.", "A bal és a jobb mindig a lövész szemszögéből értendő."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "A korong messze van, és a lövész jobbjáról balra repül; add meg neki a tervezett elétartást, és ne állítsd meg a lendítést.", "say": "Messzi keresztező, jobbról balra – bízz az elétartásban, és tartsd mozgásban a fegyvert."}, {"en": "You're behind it — give it more.", "meaning": "A lövés a korong mögött ment el: több elétartás kell.", "say": "Mögötte vagy – adj neki többet."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "Ott, ahol a lövész eltalálja, a keresztező már esik, ezért a fegyvernek kicsivel a pályája alatt kell haladnia.", "say": "A lövési pontodnál már esik – maradj a vonal alatt."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "A korongot a szokásosnál közelebb a dobógéphez keresd, mert gyorsan hagyja el a gépet.", "say": "Vedd fel korán, gyorsan jön ki a gépből."}], "quiz": [{"q": "Melyik bemutatáshoz kell általában a legtöbb elétartás?", "options": ["Egyenesen elmenő korong", "Egyenesen a lövész felé repülő bejövő korong", "Keresztező ugyanakkora távolságban", "Egyenesen elguruló nyúl"], "answer": 2, "why": "A keresztező a teljes oldalirányú sebességét mutatja, ezért a fegyvernek a legjobban elé kell mennie; az egyenes vonalú korongokhoz kevés oldalirányú elétartás kell."}, {"q": "Az edző azt mondja: „long crosser”. Mit jelent a „long”?", "options": ["A korong messze van", "A korong sokáig repül", "A korong hosszúkás, ovális", "A lövésznek sokáig kell várnia"], "answer": 0, "why": "Az edzői nyelvben a „long” távolságot jelent. A long crosser messzi keresztező, amelyhez több elétartás kell."}, {"q": "Mi igaz a keresztezőkre a Compak® Sporting versenyszámban?", "options": ["Compak pályán keresztező nem megengedett", "Csak jobbról balra keresztező megengedett", "Keresztezőt csak nyúlként lehet dobni", "Egy B→J és egy J→B keresztező kötelező"], "answer": 3, "why": "A Compak® Sporting szabályai három röppályát tesznek kötelezővé: egy B→J keresztezőt, egy J→B keresztezőt és egy elmenő korongot."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "Bejövő, elmenő, magasan berepülő és fej fölötti", "body": ["A bejövő korong (incomer) a lövész felé repül, gyakran egy távoli dobógépből vagy toronyból, és jöttében általában esik. Úgy tűnhet, hogy lelassul és megáll a levegőben, ami célzásra csábítja a lövészt. Rendszerint elöl lövik le, mielőtt a fej fölé érne, és a csövek a lövés pillanatában eltakarhatják a korongot („blot out”). Ez szándékos, nem hiba.", "Az elmenő korong (going-away) a lövész közeléből vagy mögüle indul, és elrepül. Kevés oldalirányú elétartás kell hozzá, de gyorsan kisebbedik, és gyakran emelkedik vagy esik, ezért az elétartás főleg függőleges, és az időzítés számít: ne várj. A Compak® Sporting versenyszámban kötelező egy elmenő korong a BC oldal fölött; jöhet egy elöl lévő árokból vagy a lőállások mögötti toronyból, legalább 4 m-rel fölöttük.", "A magasan berepülő korong (driven) olyan bejövő korong, amely a lövész feje fölött repül át, mint a hajtók által felvert fácán. Vedd fel korán, mozogj vele, lendíts fel hátulról, rajta keresztül, lőj, amikor a csövek eltakarják, és lendíts tovább. Vigyázat: a francia „en battue” (olasz „in battuta”) hajtásos vadat jelent, nem a battue korongot.", "A hátulról jövő, fej fölötti korong (overhead from behind) a lövész háta mögül jön át, és elrepül. Későn látni, ezért a lövész korán hátranéz érte, vele együtt veszi vállba, akkor lő, amikor a csőtorkolat eléri a korong elejét, és elkíséri.", "A „bejövő” (incoming) és az „elmenő” (going away) mindig a lövészhez viszonyítva írja le a korongot."], "key_points": ["Bejövő: a lövész felé jön, általában esik; lődd elöl.", "Elmenő: kevés oldalirányú elétartás, főleg függőleges; lőj gyorsan.", "Magasan berepülő: bejövő a fej fölött; hátulról lendíts át rajta, és takard el.", "Hátulról jövő, fej fölötti: nézz hátra korán, vedd vállba vele, kísérd el.", "A Compak® Sporting versenyszámban mindig van elmenő korong."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "A bejövő korongot találd el, amíg még előtted van, ne akkor, amikor már a fejed fölött.", "say": "Lődd le elöl, mielőtt föléd ér."}, {"en": "Blot it out and keep swinging.", "meaning": "Hagyd, hogy a csövek a lövéskor eltakarják a korongot, és ne állítsd meg a fegyvert.", "say": "Takard el, és lendíts tovább."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Az elmenő korongot lődd gyorsan, mert hamar távolodik.", "say": "Ne várj az elmenőre – egyre kisebb."}, {"en": "It comes from behind you — look back for it early.", "meaning": "Hátulról jövő, fej fölötti korong; a korong kérése előtt fordítsd a szemedet felé.", "say": "Mögüled jön – nézz hátra érte korán."}], "quiz": [{"q": "Az edző azt mondja: „Blot it out.” Mit tegyen a lövész?", "options": ["Törölje meg a lövészszemüveg lencséit", "Hagyja, hogy a csövek a lövéskor eltakarják a korongot", "Várjon, amíg a korong eltűnik a szeme elől", "Csak a lehulló darabokra lőjön"], "answer": 1, "why": "Bejövő, magasan berepülő és emelkedő korongoknál a fegyver a lövés pillanatában gyakran eltakarja a korongot; az edző pontosan ezt kéri."}, {"q": "Miért nem szabad túl sokáig hagyni az elmenő korongot?", "options": ["Gyorsan távolodik és kisebbedik", "A szabályok csak három másodpercet engednek", "Mindig keresztezővé válik", "A bíró a tetőpont után „No bird”-öt mond"], "answer": 0, "why": "Az elmenő korong gyorsan növeli a távolságot, így minél tovább vársz, annál nehezebb. A három másodperc az indítási idő, nem a lövés határideje."}, {"q": "Miben különbözik a magasan berepülő korong egy közönséges bejövőtől?", "options": ["Mindig nyúl", "A lövész mögül jön", "A lövész feje fölött repül át", "Csak a Compak® Sporting versenyszámban dobják"], "answer": 2, "why": "A driven olyan bejövő korong, amely a fej fölött jön át, mint a hajtásos vad. A mögülünk jövő korong a hátulról jövő, fej fölötti korong."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Rézsútos korongok: elmenő és bejövő", "body": ["A rézsútos korong (quartering) szögben repül: részben keresztez, részben távolodik vagy közeledik. A rézsútosan elmenő (quartering away) szögben távolodik a lövésztől, például előre-jobbra kifelé. A rézsútosan bejövő (quartering towards, más néven „quartering in”) szögben jön a lövész felé, és elhalad az egyik oldalon, vagy elöl leesik. A szög gyakran 45° körül van, de bármi lehetséges az egyenes korong és a teljes keresztező között.", "Az elétartás a szögtől függ: több, mint egy egyenesen elmenő korongnál, kevesebb, mint egy teljes keresztezőnél. Éles szögnél kevés elétartás kell, a majdnem keresztezőnél majdnem annyi, mint egy keresztezőnél.", "A rézsútosan elmenő gyorsan kisebbedik és lassul, ezért lődd gyorsan. A pull-away jól illik hozzá, mert a fegyver a korong vonalán marad. A rézsútosan bejövő egyre nagyobb, és lassúnak látszik, ami várakozásra csábítja a lövészt; ilyenkor túl közel jöhet, vagy eltűnhet a szem elől.", "Ugyanaz a dobógép különböző lőállásokból különböző bemutatást ad: az egyik lőállásból a korong keresztező, a következőből rézsútos. Ezért a korongokat pontosan abból a lőállásból kell kiolvasni, amelyikből a lövész lőni fog.", "Magyarul mondd: „rézsútosan elmenő” és „rézsútosan bejövő” (vagy „ferdén elmenő / ferdén bejövő”). A „quarter” szóból képzett tükörfordítás a lövésznek semmit nem mond."], "key_points": ["Rézsútos = szögben repül, az egyenes és a keresztező között.", "A rézsútosan elmenő szögben távolodik; a rézsútosan bejövő szögben közeledik.", "Az elétartás a szöggel nő: kevesebb, mint keresztezőnél, több, mint egyenes korongnál.", "Egy dobógép minden lőállásból másképp néz ki: a saját lőállásodból olvasd ki.", "Magyarul: „rézsútosan (ferdén) elmenő / bejövő”."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "Az első korong szögben távolodik a lövész bal oldala felé; találd el korán.", "say": "Az első rézsútosan megy el balra – lődd gyorsan, mielőtt kicsi lesz."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "A korong jobbról, szögben jön a lövész felé; ne várj rá.", "say": "Rézsútosan jön be jobbról – ne engedd túl közel."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "A korong majdnem egyenes, ezért csak kis elétartás kell hozzá.", "say": "Kevesebb elétartás, mint gondolnád – csak enyhe a szög."}], "quiz": [{"q": "Egy korong szögben jön a lövész felé, és oldalt elhalad. Hogy hívják?", "options": ["Elmenő", "Rézsútosan bejövő", "Teal", "Rafale"], "answer": 1, "why": "A rézsútosan bejövő (quartering towards / in) szögben közeledő korong; a rézsútosan elmenő a szögben távolodó korong."}, {"q": "Hogyan viszonyul a rézsútos korong elétartása egy teljes keresztezőéhez azonos távolságnál és sebességnél?", "options": ["Ugyanannyi, mint a keresztezőnél", "Mindig nulla", "Nagyobb, mint a keresztezőnél", "Kisebb, a szögtől függően"], "answer": 3, "why": "Csak a mozgás oldalirányú része kíván oldalirányú elétartást, ezért minél élesebb a szög, annál kisebb az elétartás."}, {"q": "Miért kell a korongot pontosan abból a lőállásból kiolvasni, amelyikből lőni fogsz?", "options": ["Egy dobógép az egyik lőállásból keresztező, a másikból rézsútos lehet", "A szabályok tiltják, hogy máshonnan nézd", "A korongok lőállásról lőállásra színt váltanak", "Csak a bíró állhat máshol"], "answer": 0, "why": "A lövész és a korong vonala közötti szög a helyzettel változik, így a bemutatás is."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Teal, chandelle, íves és eső korongok", "body": ["Ezek a bemutatások inkább a magasságról és az ívről szólnak, mint a szögről. A nevük pályaépítői szó, nem szabálykönyvi kifejezés: a szabályok korongtípusokat sorolnak fel, a Compak® Sporting szabályai pedig változatos röppályákat kérnek, például emelkedő, eső és magasra dobott korongokat.", "A teal (springing vagy rising teal, a kis récefajról elnevezve) szinte függőlegesen felfelé repül, lelassul, a tetőponton megáll, és visszaesik. Vagy felfelé menet lövik, alulról lendítve át rajta, vagy a tetőponton, amíg megáll. A klasszikus hiba a tetején való célzás (poking). Egyes pályaépítők a „springing” szót olyan korongra használják, amely nem egyenesen felfelé, hanem szögben emelkedik, mint egy felrebbenő madár.", "A chandelle (franciául „gyertya”) enyhe ívben, meredeken emelkedik, átfordul, és szinte függőlegesen esik. Felfelé menet a legkönnyebb; az átfordulásnál az elétartás oldalra és lefelé kerül.", "Az íves korong (looper) széles ívet ír le az égen, mint egy szivárvány: emelkedik, átbillen a csúcson, és esik. Általában standard korong; egyes pályaépítők ilyen vonalon battue-t is dobnak, amely fordulás közben a lapját mutatja. A fegyver követi az ívet, elé és alá.", "Eső korong (dropping) minden olyan korong, amely a röppályája eső szakaszában van. Az elétartás részben függőleges: alá és elé, mozgó fegyverrel.", "Vigyázat: a nevek országonként eltérnek. Sok francia anyanyelvű a „chandelle” szót olyan korongra használja, amely szinte egyenesen felfelé megy – ezt egy angol edző tealnek hívja –, a magyar lövészek pedig az íves korongot is nevezhetik chandelle-nek. Amikor chandelle-t, candle-t vagy „gyertyát” hallasz, kérdezz rá: egyenesen fel, vagy átívelve?"], "key_points": ["Teal: szinte függőlegesen fel, megáll, esik; lődd emelkedőben vagy a tetőponton.", "Chandelle: meredek, íves emelkedés, átfordul, szinte függőlegesen esik.", "Íves: széles, szivárványszerű ív, általában standard korong, amely átbillen a csúcson, és esik.", "Eső: elétartás alá és elé, soha ne állítsd meg a fegyvert.", "A nevek eltérnek: a franciák a tealt gyakran „chandelle”-nek hívják; a magyar „chandelle” is kétértelmű lehet, ezért tisztázd."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Az emelkedő tealt a tetőpont előtt találd el; a fegyver tovább emelkedik rajta túl.", "say": "A tealt felfelé menet lődd – a csövek fölötte mozogjanak."}, {"en": "Don't poke at it on the top.", "meaning": "Ne állj meg, és ne célozz a korongra, amíg a tetőponton megáll.", "say": "Ne célozgass rá a tetején."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "A korong átfordul az ívének tetején, és esni kezd; az elétartás alá és elé kerül.", "say": "Az íves átfordul – alá és elé."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "A dublé második korongja esik; lőj alá, mozgásban lévő fegyverrel.", "say": "A második esik – menj alá, és tartsd mozgásban a fegyvert."}], "quiz": [{"q": "Melyik korong repül szinte egyenesen felfelé, áll meg a tetőponton, és esik vissza?", "options": ["Íves", "Rézsútosan elmenő", "Nyúl", "Teal"], "answer": 3, "why": "Ez a teal (springing vagy rising teal). Az íves korong széles ívet ír le az égen."}, {"q": "Hová kerül általában az elétartás eső korongnál?", "options": ["Fölé és mögé", "Alá és elé", "Egyenesen a korongra", "Csak oldalra, soha nem lefelé"], "answer": 1, "why": "Az eső korong lefelé és előre is mozog, ezért az elétartás egy része függőleges: alá és elé."}, {"q": "Egy francia anyanyelvű edző azt mondja: „chandelle”. Mi a legbiztonságosabb teendő?", "options": ["Rákérdezni: egyenesen fel, vagy átívelve?", "Mindig az angol looper szóval fordítani", "Mindig az angol teal szóval fordítani", "Figyelmen kívül hagyni, mert nem szabálykönyvi kifejezés"], "answer": 0, "why": "A franciák gyakran szinte függőleges korongra gondolnak (angolul teal), egy angol pályaépítő chandelle-je viszont ívben emelkedik és átfordul; egy gyors kérdés megelőzi a téves tervet."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "A nyúl: guruló, ugráló és kilövő", "body": ["A nyúl (rabbit) 110 mm-es korong vastag, erős peremmel, amelyet élére állítva dobnak, így a földön gurul, mint egy futó nyúl. Különleges korong, ezért a Parcours de Chasse – Sporting™ versenyszámban fel kell tüntetni a lőállás kottáján.", "Az edzők leírják, hogyan fut: a guruló nyúl (rolling) egyenletesen fut; az ugráló nyúl (hopping, bouncing) a buckákon és köveken ugrik; a kilövő nyúl (bolting) kitör a takarásból, és gyorsan fut. A nyúl mehet keresztben, a lövész felé vagy tőle el.", "A nyúl nehéz, és gyorsan lassul, ezért a lövészek gyakran túl sok elétartást adnak neki. Az edzők azt kérik, hogy a csőtorkolat maradjon lent, és a lövés az alsó elülső élre menjen, hogy egy hirtelen ugrásnál is a sörétbe fusson. Gyakran csak egy rövid résben látszik a bokrok között, ezért a lövési pontot pontosan meg kell tervezni.", "Szabályok: minden korongot, a nyulat is, vállból kell lőni; csípőből lőni egyik versenyszámban sem szabad. Különleges eset: ha az első lövés hibázik, és a nyúl a második lövés előtt magától eltörik, például egy kövön, az „No bird”. Az ismétlésnél csak a második lövéssel elért találat számít.", "A „fur and feather” (szőr és toll) angol sporting szleng egy nyúlból („fur”) és egy légi korongból („feather”) álló dubléra. Magyarul „nyúl” vagy „nyúlkorong” hallható; ez a tanfolyam a „nyúl” szót használja."], "key_points": ["Nyúl: 110 mm, vastag perem, élén gurul a földön.", "Guruló, ugráló, kilövő: azt írja le, hogyan fut.", "Gyorsan lassul: ne adj túl sok elétartást; a csőtorkolat maradjon lent.", "Mindig vállból lőjük; az első lövés hibája után magától eltört nyúl „No bird”.", "„Fur and feather” = nyúl + légi korong dublé."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "A nyúl egy ismert ponton ugrik; tartsd a fegyvert lent és mozgásban.", "say": "Azon a buckán ugrik – maradj alatta, és mozogj tovább."}, {"en": "Shoot its feet.", "meaning": "A lövést a nyúl alsó élére tedd, ne fölé.", "say": "A lábát lődd."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "A nyúl gyorsan veszít a sebességéből, ezért kisebb elétartás kell hozzá.", "say": "Nagyon lelassul – kevesebb elétartás, mint gondolnád."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "A nyúl és madár dubléban a nyulat lődd előbb, mert eltűnik a takarásban.", "say": "Nyúl és madár: előbb a nyulat, mielőtt a bokrokhoz ér."}], "quiz": [{"q": "Az első lövés elhibázza a nyulat, ami aztán a második lövés előtt egy kövön eltörik. Mi történik?", "options": ["Találatnak számít, mert eltört", "Az első hiba miatt nulla", "„No bird”: megismétlik, csak a második lövéssel elért találat számít", "A lövész egyszerűen továbblép a következő korongra"], "answer": 2, "why": "Mindkét szabálykönyv „No bird”-nek tekinti; az ismétlésnél a lövésznek az első lövéssel szándékosan mellé kell lőnie."}, {"q": "Miért figyelmeztetnek az edzők a túl sok elétartásra nyúlnál?", "options": ["A szabályok korlátozzák az elétartást", "Nehéz, és gyorsan lassul", "Mindig felfelé repül", "Kisebb, mint a mini korong"], "answer": 1, "why": "A nyúlnak vastag pereme van, és a földön gurul, gyorsan veszítve a sebességéből, így a szokásos keresztező-elétartással a lövés elé megy."}, {"q": "Mit jelent a „fur and feather”?", "options": ["Egy nyúlból és egy légi korongból álló dublé", "Vadászöltözködési szabály", "Ráragasztott tollakkal ellátott korong", "Két nyúlból álló dublé"], "answer": 0, "why": "Az angol sporting szlengben a „fur” a nyúl, a „feather” a repülő korong."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Szóló korongok és dublék: vadász, rafale, szimultán", "body": ["A szóló korong egy korong egy dobógépből. Mindkét versenyszámban két lövést lehet rá leadni, így egy hibát a második csővel meg lehet menteni. A dublé (pair, double) két korong, amelyet egy kérés után, egy egységként lőnek.", "Vadászdublé (report pair, double on report): a kérés az első korongot indítja, az arra leadott lövés pedig a másodikat. A Parcours de Chasse – Sporting™ versenyszámban a második 0–3 másodperccel a lövés után jön. A sorrend rögzített. A „report” itt a lövés hangját jelenti, nem írásos jelentést.", "Az egymást követő dublé, amelyet a FITASC rafale-nak hív: két korong ugyanabból a dobógépből, ugyanazon a vonalon, a második olyan gyorsan, ahogy a gép újratölt; bármelyiket lehet előbb lőni. Csak a Sporting™ versenyszámban létezik: a Compak® Sporting dublé vadász- vagy szimultán dublé.", "Szimultán dublé („simo”; az angol sportingban „true pair”): mindkét korong ugyanabban a pillanatban indul, egy vagy két dobógépből (a Compak® Sporting versenyszámban mindig két különböző gépből), és tetszőleges sorrendben lőhető.", "Töltények: a Sporting™ versenyszámban a dubléra kettő jár, és mindkettő mehet egy korongra; ha egy lövés mindkettőt eltöri, mindkettő számít. A Compak® Sporting versenyszámban korongonként csak egy töltény megengedett, és ha mindkét lövés egy korongra megy, az nulla-nulla; az egy lövéssel eltört két korongot sem értékelik egyszerűen kétszer (a Compak® küldetés elmagyarázza).", "A Sporting™ lőálláson a rotte előbb a szóló korongokat lövi, aztán a dublékat. A szimultán és a rafale dublékat a lövés előtt bemutatják; a vadászdublékat nem."], "key_points": ["Szóló korong: egy korong, két lövés megengedett.", "Vadászdublé: az elsőre leadott lövés indítja a másodikat; a sorrend rögzített.", "Rafale (egymást követő dublé): ugyanaz a gép, ugyanaz a vonal, csak Sporting™.", "Szimultán (true pair): mindkettő egyszerre, tetszőleges sorrendben.", "Sporting™: mindkét töltény mehet egy korongra; Compak® Sporting: korongonként egy."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "A második korong csak akkor jön, amikor a lövész az elsőre lő, így nem kell sietni az elsővel.", "say": "Vadászdublé – az elsőt rendesen fejezd be, a második a lövésedre vár."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "A szimultán dubléban előbb a nyulat lődd, mert a teal tovább marad a levegőben.", "say": "Szimultán: előbb a nyulat, a teal megvár."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Mindkét korong ugyanabból a gépből jön; az első lövés után vidd vissza a szemedet és a fegyvert a gép felé, hogy felvedd a másodikat.", "say": "Rafale – az első után rögtön vissza a géphez a másodikért."}, {"en": "True pair from the tower, five of them.", "meaning": "Öt szimultán dublé a toronyból (angol sporting szóhasználat).", "say": "Szimultán dublé a toronyból, ötször."}], "quiz": [{"q": "Vadászdublénál mi indítja a második korongot?", "options": ["Egy második kérés", "A bíró jelzése", "Az első korongra leadott lövés", "Pontosan 5 másodperces időzítő"], "answer": 2, "why": "Az „on report” a lövés hangjára értendő: az első korongra leadott lövés indítja a másodikat."}, {"q": "Egy lövész Compak® Sporting versenyszámban szimultán dublé első korongjára lövi mindkét töltényét. Eredmény?", "options": ["Megengedett, mint a Sporting™ versenyszámban", "Nulla-nulla", "„No bird” és ismétlés", "Csak a második korong nulla"], "answer": 1, "why": "A Compak® Sporting dublénál korongonként egy töltényt enged; ha szándékosan mindkettőt egy korongra lövik, az nulla-nulla. A Sporting™ versenyszámban megengedett lenne."}, {"q": "Egy brit edző azt mondja: „true pair”. Hogyan fordítod?", "options": ["Helyes, szabályos dublé", "Igazi madarakból álló pár", "Rafale", "Szimultán dublé"], "answer": 3, "why": "A „true pair” a szimultán dublé angol sporting neve; a „true” itt semmi köze a helyességhez."}]}]}, {"id": "basics", "icon": "stance", "title": "A lövés alapjai", "intro": "Mielőtt bármi szóba kerülne az elétartásról, az edző rendbe teszi az alapokat: a lábakat, a vállba vételt, a szemet, a háromlépéses tervet és a mozgásban maradó fegyvert. Ez az öt lecke megadja az edző szavait minden lépéshez, és azokat a szabályokat, amelyek korlátozzák, mit tehet a lövész.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "Beállás: lábak a lövési pont felé", "body": ["A beállás (stance, lábtartás) az, ahogyan a lövész a lövés előtt áll. A hely kicsi: a Parcours de Chasse – Sporting™ versenyszámban a lőállás 1 m-es négyzet vagy kör, és a korong kérése előtt mindkét lábnak benne kell lennie. A Compak® Sporting versenyszámban minden lőállás 1 m-es négyzet lőszögkorlátozóval (Firing Angle Limiter): ez egy keret, amely megakadályozza, hogy a lövész előrelépjen, és korlátozza a lendítést.", "A szokásos alapállás: a lábak nagyjából vállszélességben; jobbkezes lövésznél a bal láb kissé elöl (balkezesnél fordítva); a térd laza, nem feszített; a testsúly kissé előre tolódik, nagyjából 60 százaléka az elülső lábon. Az edzők azt mondják: „nose over toes” – az orr a lábujjak fölött.", "A legfontosabb utasítás: az elülső lábfej mutasson a lövési pont (break point) felé, oda, ahol a lövész a korongot el akarja találni. Így a test pontosan ott van kényelmes, „kicsavarodott” helyzetben, ahol a lövés történik. A lövész a csípőből visszafordul a fegyvertartási pontig (hold point), majd a lövésbe „kicsavarodik”. Ha a lábak a dobógép felé néznek, figyelmeztetnek az edzők, a testnek elfogy a fordulása, és megáll a cső, vagy felemelkedik a fej.", "A test a csípőből fordul, nem a karokból. A lábak minden korongnál kissé másképp állhatnak.", "A „front foot” és „back foot” kifejezést elülső és hátsó lábnak fordítsd, ne bal és jobb lábnak: a lövészed lehet balkezes."], "key_points": ["Sporting™: a korong kérése előtt mindkét láb az 1 m-es lőálláson belül.", "Compak® Sporting: 1 m-es lőállás lőszögkorlátozóval.", "Lábak vállszélességben, laza térd, testsúly kissé előre.", "Az elülső láb a lövési pont felé mutat; a csípőből fordulj vissza a fegyvertartási pontig.", "Elülső/hátsó lábat fordíts, ne bal/jobb lábat."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Fordítsd az elülső lábfej hegyét afelé a hely felé, ahol a korongot eltalálod.", "say": "Az elülső lábad mutasson a lövési pontra."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Előbb a lövési ponthoz állítsd be a lábadat, aztán fordítsd vissza a felsőtestet a fegyvertartási pontig.", "say": "Állj be a lövési pontra, aztán fordulj vissza a kiinduló pontig."}, {"en": "Weight forward, soft knees.", "meaning": "Dőlj kissé az elülső lábadra, és ne feszítsd ki a térdedet.", "say": "Súly előre, laza térd."}, {"en": "Turn from the hips, not the arms.", "meaning": "Az egész felsőtest forog; a karok nem lendítik egymagukban a fegyvert.", "say": "Csípőből fordulj, ne a karodból."}], "quiz": [{"q": "Merre szeretné általában az edző, hogy az elülső láb mutasson?", "options": ["A dobógép felé", "A korongfelvételi pont felé", "A bíró felé", "A lövési pont felé"], "answer": 3, "why": "A lövési ponthoz állított lábak mellett a test kényelmes ott, ahol a lövés történik; ha a lábak a dobógép felé néznek, a testnek elfogy a fordulása."}, {"q": "Mit írnak elő a Parcours de Chasse – Sporting™ szabályai a lábakra a korong kérése előtt?", "options": ["Mindkét láb a lőálláson belül legyen", "Az elülső láb a lőállás vonalán legyen", "A lábak legyenek összezárva", "Semmilyen előírás nincs"], "answer": 0, "why": "A készenléti testhelyzetről szóló szabály szerint a korong kérése előtt mindkét lábnak az 1 m-es lőálláson belül kell lennie."}, {"q": "Balkezes lövész. Az edző azt mondja: „Open your front foot”. Melyik lábról van szó?", "options": ["Mindig a balról, kezességtől függetlenül", "A jobbról: ez a balkezes lövész elülső lába", "A hátsóról, amelyik közelebb van a dobógéphez", "Mindkét lábról egyszerre"], "answer": 1, "why": "Balkezes lövésznél az elülső láb a jobb. Ha a „front foot” kifejezést „elülső láb”-nak fordítod, elkerülöd a hibát."}]}, {"id": "basics-mount", "minutes": 6, "title": "Készenléti testhelyzet és vállba vétel", "body": ["A Parcours de Chasse – Sporting™ versenyszámban a kezdés leengedett fegyverrel történik. A korong kérése előtt a tus sarka érinti a testet, és a tus felső hátsó része egy vonal alatt marad, amely a lőmellényen, 25 cm-rel a vállak tengelye alatt, kontrasztos színnel van megjelölve. A lövész ezt a helyzetet addig tartja, amíg a korong ki nem repül és láthatóvá nem válik. A korábbi vállba vételért szóbeli figyelmeztetés és sárga lap jár; ha ugyanazon a lőpályán megismétlődik, piros lap következik, és a korongot nullának értékelik.", "A Compak® Sporting versenyszámban a fegyver helyzete a korong kérésekor szabad, így a fegyver már vállban is lehet. Mindkét versenyszámban minden korongra vállból kell lőni, a Sporting™ versenyszámban pedig a dublé két korongja között a fegyver helyzete szabad.", "A vállba vétel (gun mount) az arcához és vállához emeli a fegyvert. Az edzők azt tanítják: „muzzles first” – a csövek indulnak először: az elülső kéz a korong vonalán elindítja a csőtorkolatot, a tus felemelkedik az archoz, és a vállzsebbe ül, miközben a fegyver felveszi a vonalat. A „move, mount, shoot” – mozdulj, vedd vállba, lőj – egyetlen folyamatos mozdulat. A fegyver jön az archoz, nem az arc a fegyverhez; az arc a pofadékon marad, mert a szem a hátsó irányzék.", "Egy brit edző mondhatja: „gun up” vagy „pre-mount this one” – ezt vállból indítsd. Ez FITASC Sporting™ versenyen szabálytalan, a Compak® Sporting versenyszámban szokásos, edzésen pedig csak gyakorlat. A Sporting™ versenyszámban tilos a korong kérése előtt vállba venni a fegyvert, és egy elképzelt vonalon végiglendíteni (lövés imitálása): először figyelmeztetés, aztán nulla."], "key_points": ["Sporting™: a tus a mellényen lévő vonal alatt (25 cm-rel a vállak tengelye alatt), amíg a korong láthatóvá nem válik.", "Korai vállba vétel: sárga lap, majd ugyanazon a lőpályán piros lap és elveszett korong.", "Compak® Sporting: a korong kérésekor a fegyver helyzete szabad; mindig vállból kell lőni.", "Csövek először, fegyver az archoz, arc a pofadékon: mozdulj, vedd vállba, lőj.", "A „pre-mount” edzésgyakorlat, FITASC Sporting™ versenyen soha."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Emeld a tust az arcodhoz; ne engedd le a fejed a fegyver elé.", "say": "A fegyver jöjjön az arcodhoz, ne az arcod a fegyverhez."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Indítsd a csöveket a koronggal együtt, a mozdulat közben vedd vállba, és lőj, amikor a vállba vétel befejeződik.", "say": "Előbb a csövek – mozdulj, vállba, lövés."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "A fegyver túl későn és rántva jön fel; az elülső kéznek korábban kellene vezetnie a mozdulatot.", "say": "Későn és túl gyorsan veszed vállba – az elülső kezeddel indítsd."}, {"en": "Low gun on this one, like in competition.", "meaning": "Kezdj a mellényen lévő vonal alatt tartott tussal, ahogy a FITASC Sporting™ szabályai előírják.", "say": "Ezt lent tartott fegyverrel, mint a versenyen."}], "quiz": [{"q": "A Parcours de Chasse – Sporting™ versenyszámban meddig kell a tusnak a mellényen lévő vonal alatt maradnia?", "options": ["Amíg a lövész kéri a korongot", "Amíg a bíró nem bólint", "Amíg a korong ki nem repül és láthatóvá nem válik", "Amíg el nem dördül az első lövés"], "answer": 2, "why": "A készenléti testhelyzetet addig kell tartani, amíg a korong kirepült és látható; csak ezután szabad vállba venni a fegyvert."}, {"q": "A Compak® Sporting versenyszámban kérheti-e a lövész a korongot úgy, hogy a fegyver már a vállában van?", "options": ["Nem: sárga lap jár érte", "Csak nyúlra és más alacsony korongokra", "Csak a dublé két korongja között", "Igen: a fegyver helyzete a korong kérésekor szabad"], "answer": 3, "why": "A Compak® Sporting versenyszámban nincs leengedett fegyverre vonatkozó szabály: a fegyver a korong kérésekor lehet vállban vagy sem, de minden korongra vállból kell lőni."}, {"q": "Miért ragaszkodnak az edzők ahhoz, hogy az arc a pofadékon maradjon?", "options": ["A szem a hátsó irányzék, ezért mindig ugyanott kell lennie", "Hogy kevesebb zaj érje a fület", "Mert mindkét versenyszám szabályai előírják", "Hogy az arc ne látsszon a bíró felől"], "answer": 0, "why": "A sörétes puskának nincs hátsó irányzéka: a sín fölötti szem maga az irányzék, ezért ha felemelkedik az arc, a lövés magasra megy."}]}, {"id": "basics-eyes", "minutes": 5, "title": "A szem: dominancia, két nyitott szem, éles fókusz", "body": ["A legtöbb embernek van egy domináns szeme (vezérszem), amelyben az agy jobban megbízik; általában ugyanazon az oldalon, mint az ügyesebb kéz. A sín mentén a domináns szemnek kell néznie. Keresztdominancia (cross-dominance) esetén a domináns szem a lövővállal ellentétes oldalon van; centrális látásnál egyik szem sem domináns egyértelműen. Mindkettő miatt a fegyver oda mutat, ahová a lövész nem várja, gyakran oldalra.", "Egyszerű teszt: két nyitott szemmel egy távoli tárgyat a kezekből formált kis háromszögbe foglalunk, majd felváltva becsukjuk a szemünket; amelyik szemmel a tárgy a háromszögben marad, az a domináns. Az edző a lövész elé is állhat, és a háromszögön keresztül megnézheti.", "Az edző által választott megoldások: a másik szem becsukása vagy hunyorítása a vállba vétel közben; egy kis pötty a lövészszemüvegen; a lövés megtanulása a másik vállból; vagy ritkábban keresztezett (cross-over) tus. Ahol lehet, a két nyitott szem az előnyösebb, mert két szem jobban megítéli a sebességet, a szöget és a távolságot.", "Fókusz: a korongfelvételi pontnál várakozva laza, széles fókusz, aztán éles fókusz magán a korongon, ideális esetben az elülső élén. Ha a lövész visszanéz a csőre vagy a célgömbre, hogy ellenőrizze az elétartást, megáll a cső.", "A lövészszemüveg mindkét versenyszámban kötelező a lövészeknek, ezért a pötty arra kerül."], "key_points": ["A sín mentén a domináns szemnek kell néznie.", "A keresztdominancia és a centrális látás miatt a fegyver a korong mellé mutat.", "Teszt kézzel formált háromszöggel; a megoldást az edző választja.", "Laza fókusz a felvételnél, éles fókusz az elülső élen; soha ne nézz vissza a célgömbre.", "A lövészszemüveg mindkét versenyszámban kötelező."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "A bal szemedet a vállba vétel közben csukd be, ne előtte, hogy a jobb szem irányítsa a fegyvert.", "say": "Csukd be a bal szemed, ahogy jön fel a fegyver."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Folyamatosan a korongot nézd; ha a csövet ellenőrzöd, megáll a fegyver.", "say": "A korongot nézd, ne a csövet."}, {"en": "Look at the leading edge.", "meaning": "A mozgó korong elülső élére fókuszálj, ne a közepére.", "say": "Az elülső élét nézd."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Kicsit kijjebb, a vonal mentén várj a szemeddel, ott, ahol először látod tisztán a korongot.", "say": "Ne a gépet nézd – nézz ki a felvételi pontodra."}], "quiz": [{"q": "Egy jobbkezes lövésznek a bal szeme domináns. Hogy hívják ezt?", "options": ["Centrális látás", "Éles fókusz", "Keresztdominancia", "Elülső él"], "answer": 2, "why": "Keresztdominancia: a domináns szem a lövővállal ellentétes oldalon van."}, {"q": "Miért hiba visszanézni a célgömbre, hogy ellenőrizzük az elétartást?", "options": ["A szabályok tiltják", "Megáll tőle a cső, és a lövés mögé megy", "A célgömb visszaveri a napfényt", "Ettől a korong színe megváltozik"], "answer": 1, "why": "Amikor a fókusz a fegyverre kerül, megáll a lendítés, és a korong a perifériára kerül, így a lövés mögé megy."}, {"q": "Hová kerül általában a dominancia elleni pötty?", "options": ["A lövészszemüvegre, a kizárandó szem elé", "A célgömbre a sín végén", "A sínre, annak közepére", "A mellényen lévő vonalra, a váll alá"], "answer": 0, "why": "A lövészszemüveg amúgy is kötelező, így a nem domináns szem előtti lencsére tett kis pötty a legegyszerűbb megoldás."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Felvételi, fegyvertartási és lövési pont: a lőállás megtervezése", "body": ["Minden korong előtt a lövész három pontot jelöl ki. A korongfelvételi pont (pick-up point) az, ahol a szem először látja tisztán a korongot: kicsit a dobógéptől kijjebb, nem a gép szájánál, ahol a korong még csak elmosódott folt. A fegyvertartási pont (hold point) az, ahol a csövek várakoznak a korong kérésekor, általában a korong vonalán vagy kicsivel alatta, a felvételi pont és a lövési pont között. A lövési pont (break point) az, ahol a lövész a korongot el akarja találni.", "A tervezés sorrendje: először a lövési pontot kell kiválasztani, hozzá kell állítani a lábakat, vissza kell fordulni a fegyvertartási pontig, aztán a szemet a felvételi pontra kell tenni. A Parcours de Chasse – Sporting™ versenyszámban a tus lent van, amíg a korong meg nem jelenik, így ott a fegyvertartási pont azt jelenti, hová mutatnak a csövek, amíg a fegyver lent van.", "Tipikus hibák: a túl messzi lövési pont gyors, kontrollálatlan lendítést jelent, vagy azt, hogy a korong már esik; a túl közeli túl kevés mozgást és „bökést” (poke). A dobógéphez túl közeli fegyvertartási pontnál a fegyver kergeti a korongot; a túl kintinél a korong megelőzi a fegyvert.", "A korongokat a bemutatás alatt kell kiolvasni. A Sporting™ versenyszámban az első lövésznek minden röppályát bemutatják, és kérésre a bíró megismétli a bemutatást, a kotta minden korongjából legfeljebb két korongot; a rotte-rendszerű Compak® Sporting versenyszámban a szóló korongokat reggel egyszer mutatják be, az első rottének. A korongot ott kell eltalálni, ahol a bíró látja, a lőterület határán belül.", "A „Where are you taking it?” kérdés a lövési pontra vonatkozik; a „kill point” semleges szinonima."], "key_points": ["Felvétel = szem; fegyvertartás = csövek; lövési pont = ahol a korongot eltalálod.", "A lövési ponttól visszafelé tervezz: lábak, fegyvertartás, szem.", "A fegyvertartási pont általában a felvételi és a lövési pont között van, a vonalon vagy kicsivel alatta.", "A korongokat a bemutatás alatt olvasd ki; ott találd el őket, ahol a bíró látja.", "„Where are you taking it?” = hol a lövési pontod?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "Az edző azt kérdezi, hol akarja a lövész eltalálni a korongot.", "say": "Hol lövöd?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Tartsd a csöveket közelebb a dobógéphez, a jelenlegi távolság felénél.", "say": "Hozd vissza a kiinduló pontodat félútig a gép felé."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Vidd a szemed távolabb a dobógéptől, oda, ahol először látod tisztán a korongot.", "say": "Nézz kijjebb – ott vedd fel, ahol már éles."}, {"en": "Hold a little lower, just under the line.", "meaning": "A korong kérésekor tartsd a csöveket kicsivel a korong pályája alatt.", "say": "Tartsd kicsit lejjebb, épp a vonal alatt."}], "quiz": [{"q": "Melyik pont szól a szemről, nem a fegyverről?", "options": ["Fegyvertartási pont", "Lövési pont", "Korongfelvételi pont", "Beszállási pont"], "answer": 2, "why": "A korongfelvételi pont az, ahol a szem először látja tisztán a korongot; a fegyvertartási pont a csöveké."}, {"q": "Mi történik általában, ha a fegyvertartási pont túl közel van a dobógéphez?", "options": ["A korong megelőzi a fegyvert", "A bíró „No bird”-öt mond", "A fegyvernek kergetnie kell a korongot", "A korong lelassul"], "answer": 2, "why": "A dobógéphez túl közel a korong teljes sebességgel húz el a csövek mellett, és a lövésznek kergetnie kell."}, {"q": "A Parcours de Chasse – Sporting™ versenyszámban a lőállásban álló lövész újra látni szeretné a bemutatást. Legfeljebb mennyi jár a kotta egy korongjára?", "options": ["Két korong", "Egy sem: ismétlés nem engedélyezett", "Amennyit csak akar", "Pontosan öt"], "answer": 0, "why": "A bíró kérésre megismétli a bemutatást, a kotta minden korongjára legfeljebb két korongot."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Elkísérés, fegyversebesség és tempó", "body": ["Az elkísérés (follow-through) azt jelenti, hogy a fegyver az elsütés után is tovább mozog a korong vonalán, mint egy golf- vagy teniszütés. A lövés elhatározása és a sörét csőből való kilépése között van egy kis késés; ha a fegyver az elsütésnél megáll, a lövés mögé megy. Az edzők a lövés után a csőtorkolatot figyelik: ha megdermed vagy lesüllyed, hiányzott az elkísérés.", "A fegyversebesség azt jelenti, milyen gyorsan mozognak a csövek a koronghoz képest, és ez határozza meg az elétartási módszert: a koronggal azonos sebesség az elévezetés (maintained lead); a korongnál gyorsabb az áthúzás (swing-through); az azonos sebesség, majd egy rövid gyorsítás a pull-away. A túl lassú fegyver lemarad; a túl gyors – mondják az edzők – túllő, és a lövész ilyenkor gyakran megállítja.", "A tempó az, hogy milyen gyorsan zajlik le az egész lövés; a ritmus az, hogy mennyire egyenletesen. A gyors, közeli korong gyors tempót kíván, a hosszú, lassú keresztező nyugodtabbat, de a ritmus mindig egyenletes marad. Sok edző szerint azok a lövészek, akiknek mindenre egy tempójuk van, elvesztik azokat a korongokat, amelyek az ellenkezőjét kívánják.", "„Stay in the gun” – maradj a fegyverben: arc a tuson, szem a korongon, amíg el nem törik. Ez a második csőre is készenlétben tartja a lövészt, mert szóló korongra is két lövés adható le.", "A „finish the shot” kifejezést a mozdulat folytatásaként fordítsd, ne megállásként."], "key_points": ["Elkísérés: a fegyver az elsütés után is mozog; a megállás miatt a lövés mögé megy.", "A fegyversebesség határozza meg a módszert: azonos (elévezetés), gyorsabb (áthúzás), azonos, majd gyorsabb (pull-away).", "Tempó = az egész lövés sebessége; ritmus = annak egyenletessége.", "Maradj a fegyverben: légy kész a második csőre szóló korongnál is.", "„Finish the shot” = folytasd a mozdulatot."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Ne állítsd meg a lendítést a lövésnél.", "say": "Kísérd el – a fegyver a durranás után is megy tovább."}, {"en": "You stopped the gun.", "meaning": "A csövek az elsütésnél megálltak, így a lövés mögé ment.", "say": "Megállt a cső."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "A fegyver sokkal gyorsabban mozog, mint a korong; a korong sebességével mozogj.", "say": "Vedd fel a korong sebességét – versenyzel vele."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "A korong lassú vagy hosszú, így az egész mozdulat lehet nyugodtabb.", "say": "Lassíts a tempón, erre bőven van időd."}, {"en": "Stay in the gun until you see it break.", "meaning": "Tartsd az arcod a tuson és a szemed a korongon, amíg el nem törik.", "say": "Maradj a fegyverben, amíg nem látod eltörni."}], "quiz": [{"q": "Az edző azt mondja: „You stopped the gun”. Hová ment valószínűleg a lövés?", "options": ["Elé", "Fölé", "Pontosan a korongra", "Mögé"], "answer": 3, "why": "A korong tovább mozog, a megállított fegyver viszont nem, így a sörét a korong mögött megy el."}, {"q": "Melyik fegyversebesség jellemzi az elévezetést (maintained lead)?", "options": ["Sokkal gyorsabb, mint a korong", "Ugyanakkora, mint a korongé", "Nulla: a fegyver vár", "Lassabb, mint a korong"], "answer": 1, "why": "Elévezetésnél a csövek a korong sebességével mozognak, és állandó marad a távolság. A váró fegyver a lesből lövés (ambush), a gyorsabb az áthúzás."}, {"q": "Mi a különbség a tempó és a ritmus között?", "options": ["A tempó a lövés sebessége, a ritmus annak egyenletessége", "Ugyanannak a dolognak két neve", "A tempó a lőtéren szóló zene", "A ritmus a korongok közötti időkorlát"], "answer": 0, "why": "Az edzők minden korongnál változtatják a tempót, miközben egyenletes ritmust tartanak, ezért a két szót külön fordítsd."}]}]}, {"id": "lead", "icon": "lead", "title": "Elétartás és lövési módszerek", "intro": "Az elétartásról (lead, forward allowance) beszélnek az edzők a legtöbbet: miért kell a fegyvernek a mozgó korong elé mutatnia, mi a négy módja annak, hogy odakerüljön, és milyen furcsa mértékegységekkel írják le. Ez a küldetés lépésről lépésre bemutatja az egyes módszereket, és megtanítja, hogyan fordítsd a „four foot”, „half a bird” vagy „double it” kifejezést úgy, hogy a jelentés ne változzon.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Miért van elétartás: valós és érzékelt elétartás", "body": ["A sörétnek a másodperc törtrészére van szüksége, hogy elérje a korongot, és ezalatt a korong továbbhalad. Az egyenesen a keresztezőre irányított fegyver ezért mögé lő. A fegyvernek elé kell mutatnia, hogy a sörét és a korong találkozzon. Ez a távolság az elétartás (lead), brit angolul „forward allowance” is.", "Az elétartás a korong sebességével, távolságával és szögével nő. A teljes keresztezőhöz kell a legtöbb; az egyenesen a lövész felé vagy tőle elrepülő koronghoz szinte semmilyen oldalirányú elétartás nem kell, bár az emelkedő és eső korongokhoz függőleges elétartás kell (fölé vagy alá).", "A valós számok meglepők. Egy lövészeti weboldal szerint egy kb. 21–25 yardos (kb. 20 m-es) keresztezőnél a valós elétartás kb. 3–4 láb, nagyjából egy méter. Sok lövész szerint nagyjából a távolsággal arányosan nő, így ugyanaz a kis távolság a csőtorkolatnál egy messzi korongnál sokkal több valós elétartást jelent.", "A valós elétartás (actual lead) a korong előtti tényleges távolság a levegőben. Az érzékelt elétartás (perceived lead, más néven „lead picture” vagy „sight picture”) az a távolság, amelyet a lövész a csőtorkolat és a korong között lát. Egy méter 20 m-en néhány centiméternek látszik a torkolatnál. A módszer megváltoztatja a képet: a mozgó fegyverrel dolgozó módszerek közül az elévezetés mutatja a legnagyobb távolságot, az áthúzás keveset vagy semennyit, mert a fegyver sebessége hozzáad az elétartáshoz. Lesből lövésnél a fegyver áll, ezért a lövésznek még nagyobb távolságot kell látnia: a korong a reakcióidő alatt is halad.", "Egy amerikai oktató megjegyzi, hogy a jobbkezes lövész gyakran úgy érzi, a balról jobbra keresztezőhöz több elétartás kell, mint a jobbról balrához; a valós elétartás ugyanakkora, csak az érzékelés más. Az edző „four feet”-je tehát a saját képét írja le, nem mérést."], "key_points": ["Az elétartás azért létezik, mert a korong mozog, amíg a sörét halad.", "Nagyobb sebesség, távolság és szög = több elétartás.", "A valós elétartás méterekben mérhető a levegőben, a korongnál; a torkolatnál a kép csak néhány centiméter, mert a torkolat közel van a szemhez.", "A módszer megváltoztatja a képet: mozgó fegyvernél elévezetésnél látod a legtöbbet, áthúzásnál a legkevesebbet; lesből lövésnél (álló fegyver) a távolság még nagyobb.", "Az edző száma kép, nem mérés."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Ne a levegőben lévő méterekben gondolkodj; arra a távolságra emlékezz, amelyet a torkolatnál láttál, amikor eltaláltad.", "say": "Felejtsd el a valós távolságot – a képed számít."}, {"en": "That's the picture — remember it.", "meaning": "Ennél a találatnál jó volt az elétartás; tartsd meg ugyanazt a képet.", "say": "Ez az a kép – jegyezd meg."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "A valós elétartás mindkét irányban egyenlő; csak az érzékelés változik.", "say": "A jobbról balrára ugyanannyi elétartás, csak másnak látszik."}], "quiz": [{"q": "Mi az érzékelt elétartás?", "options": ["A korong előtti valós távolság a levegőben", "Az a távolság, amelyet a lövész a csőtorkolat és a korong között lát", "A kottára írt elétartás", "A lőállás és a dobógép közötti távolság"], "answer": 1, "why": "Az érzékelt elétartás a kép a torkolatnál; a valós elétartás a tényleges távolság a levegőben, és sokkal nagyobb."}, {"q": "Melyik módszer adja általában a legnagyobb érzékelt elétartást?", "options": ["Áthúzás", "Pull-away", "Elévezetés", "Mind azonos"], "answer": 2, "why": "Elévezetésnél a fegyver a korong sebességével mozog, és a fegyver sebessége semmit nem ad hozzá, ezért a lövésznek a teljes távolságot látnia kell."}, {"q": "Melyik koronghoz nem kell szinte semmilyen oldalirányú elétartás?", "options": ["Egyenesen elmenő korong", "Messzi keresztező", "45°-ban rézsútosan elmenő korong", "Keresztező 40 m-en"], "answer": 0, "why": "Az egyenesen elmenő korongnak nincs oldalirányú mozgása; amire szüksége van, az függőleges elétartás."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Elévezetés: kerülj elé, és maradj előtte", "body": ["Az elévezetés (maintained lead, USA: sustained lead) a csöveket a kezdettől a lövésig a korong előtt tartja.", "Hogyan néz ki lépésről lépésre egy keresztezőnél. 1) Kezdés: a csövek egy jóval kijjebb, a vonalon lévő fegyvertartási ponton várnak, előtte annak, ahol a korong elhalad; a szem visszanéz a korongfelvételi pont felé. 2) Beszállás: ahogy a korong jön, a fegyver megmozdul, és a csövek a korong előtt csatlakoznak a vonalhoz, soha nem mögötte; ez a beszállási pont (insertion point). 3) Követés: a csövek a korong sebességével mozognak, így a távolság változatlan marad. 4) Lövés: az elsütés akkor történik, amikor a távolság megfelelő, és a fegyver még mozog. 5) A fegyver a lövés után is mozog tovább.", "Erősségek: pontos, kevés fegyvermozgással jár, gyors a korongok között, és az elétartás könnyen állítható. Az egyenletes, kiszámítható korongokhoz illik: messzi keresztezőkhöz, egyenletes magas korongokhoz.", "Gyengeségek: ezt a legnehezebb megtanulni; a lövésznek előre ismernie kell a korong sebességét és vonalát; és mivel a fegyver nem gyorsabb a korongnál, a lövész a legnagyobb távolságot látja, és kísértést érez, hogy kimérje, lelassítson és megálljon.", "Az edzők azt mondják: „insert the gun in front” (a fegyvert elé szállítsd be), „stay ahead of it” (maradj előtte), „match its speed” (vedd fel a sebességét)."], "key_points": ["A csövek elöl indulnak, és a korong előtt csatlakoznak a vonalhoz.", "Fegyversebesség = korongsebesség; a távolság állandó.", "Elsütés, amikor a távolság megfelelő és a fegyver mozog; aztán elkísérés.", "Messzi, kiszámítható korongokhoz a legjobb.", "Fő kockázat: a távolság kimérése és a cső megállítása."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Vidd a csöveket a korong elé, és tartsd ott a lövés utánig.", "say": "Kerülj elé, és maradj előtte."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "A csövek a korong mögött csatlakoztak a vonalhoz; elé kellene.", "say": "A beszállási pontod a korong mögött van – tedd elé a fegyvert."}, {"en": "Match its speed — don't let it catch you.", "meaning": "A korong sebességével mozgasd a fegyvert, hogy a távolság ne csökkenjen.", "say": "Vedd fel a sebességét – ne hagyd, hogy utolérjen."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "A lövész lelassít, hogy ellenőrizze a távolságot; lőj, amint a kép jó.", "say": "Méricskélsz – bízz a képben, és süsd el."}], "quiz": [{"q": "Elévezetésnél hol csatlakoznak a csövek a korong vonalához?", "options": ["A korong mögött", "A korongon", "A korong előtt", "A dobógép alatt"], "answer": 2, "why": "A csöveket a korong elé szállítják be, és előtte maradnak; mögötte az áthúzás, a korongon a pull-away."}, {"q": "Mi az elévezetéssel lövők tipikus hibája?", "options": ["Túl messze hátulról indulnak", "Kimérik a távolságot, és megállítják a fegyvert", "Csípőből veszik vállba", "Túl korán lőnek a gépnél"], "answer": 1, "why": "A távolság nagy és jól látható, ezért a lövészek kísértést éreznek, hogy ellenőrizzék; a fegyver lelassul vagy megáll, és a lövés mögé megy."}, {"q": "Melyik koronghoz ajánlják gyakran az elévezetést?", "options": ["Messzi, kiszámítható keresztezőhöz", "Rövid résben ugráló nyúlhoz", "Hátulról érkező meglepetéskoronghoz", "ZZ koronghoz"], "answer": 0, "why": "A módszerhez ismert sebesség és vonal kell, amit a messzi, egyenletes keresztezők megadnak; a kiszámíthatatlan vagy meglepetésszerű korongokhoz más módszerek illenek."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Áthúzás: hátulról, a korongon keresztül", "body": ["Áthúzásnál (swing-through) a csövek a korong mögül indulnak, és megelőzik. Magyarul „áthúzás” vagy „átlendítés”, de hallani egyszerűen „swing-through”-t is.", "Hogyan néz ki lépésről lépésre. 1) Kezdés: a csövek a korong mögött, a farkánál csatlakoznak a vonalához. 2) Előzés: a fegyver gyorsabban mozog a korongnál, a vonalán, a testén keresztül. 3) Lövés: az elsütés akkor történik, amikor a csövek elhaladnak a korong eleje előtt, épp előtte. Mivel a döntés és a lövés között kis késés van, a fegyver pedig gyorsabban mozog a korongnál, a csövek már előrébb vannak, amikor a sörét kilép: a lövés pillanatában a valós elétartás nagyobb annál, amit a lövész lát, és kevés vagy semmi távolság nem látszik. 4) A lendítés a lövés után is folytatódik. A memóriatámasz: „butt, belly, beak, bang” – farok, has, csőr, durr. Brit angolban a „butt” helyett „bum” is elhangozhat; fordítsd semlegesen „farok”-nak.", "Erősségek: természetes és gyors; jó kezdőknek, közeli gyors korongokhoz, magasan berepülő és fej fölötti korongokhoz, valamint kiszámíthatatlan vagy meglepetésszerű korongokhoz.", "Gyengeségek: nagyon rövid időablak az elsütésre; messzi keresztezőknél a lövésznek kifuthat az ideje, elveszítheti a vonalat vagy túllendülhet; ha lelassít, amikor a csövek elérik a korongot, mögé hibáz.", "A források nem értenek egyet a „CPSA-módszer” elnevezésben: egyesek áthúzásként írják le, a CPSA mai oktatásáról viszont azt írják, hogy a pull-away-t tanítja. Ha egy edző „CPSA method”-ot mond, kérdezd meg, melyikre gondol."], "key_points": ["A csövek hátulról, a korong vonalán indulnak.", "A fegyver gyorsabb a korongnál: farok, has, csőr, durr.", "Elsütés, amikor a csövek elhaladnak a korong eleje előtt; a valós elétartás nagyobb a látottnál.", "Közeli, gyors, magasan berepülő és meglepetéskorongokhoz jó; messzi keresztezőknél nehezebb.", "A „CPSA-módszer” kétértelmű: kérdezd meg, melyik módszerre gondolnak."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Indulj a korong mögül, lendíts át rajta, és lőj, amikor elöl rés jelenik meg.", "say": "Gyere hátulról, át a korongon, és lőj, amikor meglátod a rést."}, {"en": "Butt, belly, beak, bang.", "meaning": "Memóriatámasz: farok, has, a korong eleje, aztán lövés.", "say": "Farok, has, csőr, durr."}, {"en": "You slowed down as you got to it.", "meaning": "A fegyver lelassult, amikor elérte a korongot, ezért a lövés mögé ment.", "say": "Lelassítottál, amikor odaértél."}, {"en": "Brush it out and keep going.", "meaning": "Lendíts át a korongon, mintha letörölnéd az égről, megállás nélkül.", "say": "Töröld ki, és menj tovább."}], "quiz": [{"q": "Honnan indulnak a csövek áthúzásnál?", "options": ["A korong elől", "A korong elülső éléről", "Egy rögzített pontról a lövési pontnál", "A korong mögül, a vonalán"], "answer": 3, "why": "Az áthúzás hátulról indul, és megelőzi a korongot; az elölről indulás az elévezetés, a rögzített pont a lesből lövés."}, {"q": "Miért lát az áthúzással lövő kevés elétartást vagy semennyit?", "options": ["A korongok mindig lassabbak", "A fegyver sebessége hozza létre az elétartást", "A szabályok tiltják a látható rést", "A lövész mindkét szemét becsukja"], "answer": 1, "why": "A fegyver gyorsabban mozog a korongnál, így a döntés és a lövés között magától előrébb kerül."}, {"q": "Egy edző azt mondja: „bum, belly, beak, bang”. Hogyan fordítsd a „bum” szót?", "options": ["„Farok”", "Durva szóval, szó szerint", "„Bumm” (hang)", "Teljesen hagyd ki"], "answer": 0, "why": "A korong farkát jelenti; a semleges „farok” megőrzi a jelentést és a memóriatámasz ritmusát."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Pull-away: rajta, vele, elhúz, lövés", "body": ["Pull-away-nél (magyarul körülírva „mutass oda és lendíts”) a csövek előbb rámennek a korongra, aztán elhúznak előtte. A modern brit oktatásban széles körben tanítják, és ma gyakran CPSA-módszernek hívják.", "Hogyan néz ki lépésről lépésre. 1) „On it” (rajta): a fegyvert a korongra vagy annak elülső élére veszik vállba; a csövek a vonalán érintik. 2) „With it” (vele): a csövek egy pillanatig a korong sebességével követik, vonalban és tempóban. 3) „Pull away” (elhúz): a fegyver egyenletesen előregyorsul, amíg meg nem jelenik a megfelelő elétartás-kép. 4) „Shoot” (lövés): az elsütés akkor történik, amikor a fegyver még gyorsul vagy mozog. 5) Elkísérés: a fegyver a lövés után is megy tovább.", "Erősségek: mivel a lövész előbb követi a korongot, megítélheti a sebességét, a távolságát és a vonalát, mielőtt elkötelezi magát, így jó a vonal. Messzi, rézsútos és emelkedő korongokhoz illik. A gyorsítás miatt az érzékelt elétartás kisebb, mint elévezetésnél.", "Gyengeségek: a gyorsítás mértéke korongonként változik, ezért gyakorlat kell az érzéséhez; a túl hosszú követésből „túlkísérés” (riding the target) lesz, a gyorsítás abbahagyása pedig mögé hibázást okoz.", "Az edzők azt mondják: „touch it and go” (érintsd és menj), „mount on it and push out” (vedd rá vállba, és told ki), vagy a négyütemű „on it, with it, pull away, shoot”. Fordításkor tartsd meg a négyütemű ritmust: ez fontosabb a pontos szavaknál."], "key_points": ["A csövek a korongon (vagy annak elülső élén) indulnak.", "Kövesd a sebességével, aztán gyorsíts elé.", "Elsütés, amíg a fegyver még előre mozog; aztán elkísérés.", "Jó vonalkontroll; messzi, rézsútos és emelkedő korongokhoz illik.", "Fordításkor tartsd meg a négyütemű ritmust."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Menj rá a korongra, kövesd, gyorsíts elé, lőj.", "say": "Rajta, vele, elhúz, lövés."}, {"en": "Touch it and go.", "meaning": "A csövekkel érd el a korongot, és azonnal kezdj el elé húzni.", "say": "Érintsd, és menj."}, {"en": "You rode it too long.", "meaning": "A lövész túl sokáig követte a korongot, mielőtt elhúzott volna, és elveszítette a vonalat vagy a pillanatot.", "say": "Túl sokáig vitted."}, {"en": "Mount on it and push out a bit more.", "meaning": "Vedd vállba a korongra, aztán lövés előtt húzz kicsit jobban elé.", "say": "Vedd rá vállba, és told ki egy kicsit jobban."}], "quiz": [{"q": "Pull-away-nél mi történik közvetlenül az elsütés előtt?", "options": ["A fegyver megáll a korongon", "A fegyver a korong elé gyorsul", "A fegyver a korong alá süllyed", "A fegyver a lövési pontnál vár"], "answer": 1, "why": "Maga a pull-away az előregyorsítás; a lövés akkor dördül el, amikor a fegyver még előre mozog."}, {"q": "Az edző azt mondja: „You rode it too long”. Mi ment félre?", "options": ["Túl sokáig állt a lőálláson a korong kérése előtt", "Túl korán vette vállba a fegyvert", "Túl sokáig követte, mielőtt elhúzott volna", "A puller későn indította a korongot"], "answer": 2, "why": "A „riding the target” azt jelenti, hogy a lövész túl sokáig követi a korongot, így az lelassul, esik vagy elszökik, és elvész a vonal."}, {"q": "Az elévezetéshez képest a pull-away érzékelt elétartása általában…", "options": ["kisebb, mert a gyorsítás hozzáad az elétartáshoz", "nagyobb, mert a fegyver a korongon indul", "mindig pontosan kétszeres", "minden korongnál nulla"], "answer": 0, "why": "A rövid gyorsítás a lövési késés alatt előreviszi a fegyvert, így kisebb rést kell látni."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Lesből lövés és ösztönös lövés", "body": ["A lesből lövés (ambush, spot shooting – magyarul körülírva „pontra lövés”, „elébe várás”) a lendítés ellentéte. 1) A csöveket a korong elé, a vonalára, a lövési pont közelébe helyezik. 2) Kevés mozgással vagy mozdulatlanul várnak. 3) Az elsütés még azelőtt történik, hogy a korong arra a pontra érne: a lövész reakciója és a sörét repülése is időbe telik, így a korong berepül a lövésbe. Ha csak akkor lő, amikor a korong már odaért, a sörét mögötte megy el.", "Általános szokásként – ami a képzetlen lövészekre jellemző – megbízhatatlan: a fegyver áll, és az időzítésnek tökéletesnek kell lennie. A szándékos lesből lövés viszont néha a helyes választás: olyan korongnál, amelyet nagyon gyorsan kell lelőni, vagy olyan nyúlnál, amely csak egy rövid résben látszik a bokrok között. Ehhez rokon mozdulat a röppályájuk tetején élükkel látszó battue korongoknál a „collapse” (ráesés): nagyon közel a lövési ponthoz tartani, és minimális mozdulatot tenni. A korongot ilyenkor is ott kell eltalálni, ahol a bíró látja.", "Az ösztönös lövés (instinctive shooting) azt jelenti, hogy nincs tudatos elétartás. A lövész élesen a korongra fókuszál, és hagyja, hogy a kezei kövessék; a lendítés és a vállba vétel egyszerre történik, a lövés pedig akkor jön, amikor a fegyver az archoz ér. A klasszikus iskola az angol fegyverkészítő Robert Churchill nevéhez kötődik, és a vadászlövészetben népszerű.", "Sok élvonalbeli Parcours de Chasse – Sporting™ lövész keveri a módszereket, korongonként választva. A „Which method for this one?” (melyik módszer erre?) teljesen szokásos edzői kérdés."], "key_points": ["Lesből lövés: a csövek mozdulatlanul várnak egy ponton elöl; lövés még azelőtt, hogy a korong odaér, így berepül a lövésbe.", "Szokásként megbízhatatlan, szándékosan hasznos (nagyon gyors korongok, rövid rések).", "„Collapse”: minimális mozdulat a lövési pont közelében, élükkel látszó battue korongoknál.", "Ösztönös: nincs tudatos elétartás, éles fókusz, vállba vétel és lendítés együtt (Churchill-iskola).", "A jó lövészek korongonként választanak módszert."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "before-target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "A lövész egy ponton vár; az edző itt mozgó módszert akar.", "say": "Lesből lövöd – tartsd mozgásban a fegyvert a koronggal."}, {"en": "Ambush this one in the gap.", "meaning": "Szándékosan várj a nyílásnál, és lőj közvetlenül azelőtt, hogy a korong a pontodhoz ér, hogy berepüljön a lövésbe.", "say": "Ezt a résben lődd, lesből."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Lőj ösztönösen: fókuszálj a korongra, és hagyd, hogy a kezed kövesse.", "say": "Ne gondolj az elétartásra, csak nézd a korongot, és engedd hozzá a fegyvert."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Tedd a csöveket szinte a lövési pontra, és csak egy apró mozdulatot tegyél, amikor a battue odaér.", "say": "Tartsd pont a lövési ponton, és csak ess rá."}], "quiz": [{"q": "Mi jellemzi a lesből lövést (spot shooting)?", "options": ["A fegyver gyorsabban lendül a korongnál", "A fegyver egy ponton vár a korong előtt", "A fegyver követi a korongot, aztán gyorsít", "A fegyver a korong mögül, a vonalán indul"], "answer": 1, "why": "A lesből lövés kevés lendítéssel vagy anélkül történik: a csövek a vonalon várnak, és a korong berepül a lövésbe."}, {"q": "Mikor lehet jó választás a szándékos lesből lövés?", "options": ["Minden messzi, egyenletes keresztezőnél", "Soha: a szabályok tiltják", "Csak a Compak® Sporting versenyszámban, a Sporting™ versenyszámban soha", "Egy csak rövid résben látható nyúlnál"], "answer": 3, "why": "Ha a korong csak rövid ideig látható, nincs idő lendítésre, így a résnél várakozás működhet. Egyik módszert sem tiltja szabály."}, {"q": "Mi az ösztönös lövés?", "options": ["Éles fókusz a korongon, tudatos elétartás nélkül", "Lövés lövészszemüveg nélkül", "Lövés csípőből, vállba vétel nélkül", "Várakozás a gépnél minden korongnál"], "answer": 0, "why": "Az ösztönös lövés a szem–kéz koordinációra épül; ezt is vállban lévő fegyverrel végzik, ahogy a szabályok előírják."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Hogyan mondják az edzők az elétartást, és hogyan fordítsd", "body": ["Mértékegységek. A brit és amerikai edzők lábban és yardban beszélnek: „give it four foot” (brit szóhasználat négy lábra), „two feet in front” (két lábbal elé). Az európai edzők métert használnak. Egy láb kb. 30 cm, egy yard kb. 0,9 m. Az elétartás-szám azonban az edző képe, nem mérés, ezért tartsd meg a számát és a mértékegységét. Utasítás közben soha ne váltsd át; ha a lövész kérdezi, a korongok között nagyjából magyarázd el. A korong távolsága („it's 30 yards”) megadható úgy, hogy „körülbelül 27 m”.", "Korongszélességek: „half a bird” (fél korong), „a bird's width” (egy korongnyi), „a clay's length” (egy korong hossza). A bird itt korongot jelent, soha nem igazi madarat: „fél korong”. Csőszélességek: a „a barrel's width” (egy csőszélességnyi), „two barrels” (két csőnyi) a torkolatnál látott távolságot jelenti. Vigyázat: a bíró szájából a „two barrels” azt jelenti, hogy a két cső egyszerre sült el.", "Viszonylagos szavak: „more” (több), „less” (kevesebb), „a touch more” (egy hajszállal több), „double it” (duplázd meg), „half that” (annak a fele), „same lead” (ugyanannyi elétartás). Maradjanak viszonylagosak, és soha ne találj ki számot. A „same lead” létfontosságú: a lövész ne növelje az elétartást.", "Irányok: az „in front” (elé) és a „behind” (mögé) a korong haladási irányára vonatkozik; az „over” és a „high” (fölé), az „under” és a „low” (alá) szinonimák. A számlap pozíciókat ír le: a 12 óra fent, a 3 óra jobbra van, ahogy a lövész látja. A „you hit it at six” az alsó élt jelenti; az „it comes from eleven” irányt ad meg.", "Módszer: a számot, a mértékegységet, a viszonyítási alapot és az irányt pontosan, röviden, az edző ritmusában fordítsd. Ha nem világos, kérdezz vissza egy szóval: „Feet?” (láb?). Versenyen az edzői irányítás tilos."], "key_points": ["Tartsd meg az edző számát és mértékegységét; utasítás közben soha ne váltsd át az elétartást.", "Bird = korong: „half a bird” = „fél korong”.", "A viszonylagos szavak maradjanak viszonylagosak; a „same lead” kifejezést le kell fordítani.", "Számlap: 12 fent, 3 jobbra, ahogy a lövész látja.", "A bíró „two barrels”-e beduplázás, nem elétartás."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Add meg azt az elétartást, amelyet az edző „négy lábnak” nevez; a képét írja le, ezért tartsd meg a számát és a mértékegységét.", "say": "Adj neki négy lábat."}, {"en": "Half a bird more.", "meaning": "Adj hozzá fél korongszélességet az elétartás-képhez.", "say": "Fél koronggal többet."}, {"en": "Double it.", "meaning": "Az elétartás-kép legyen kétszer akkora, mint legutóbb.", "say": "Duplázd meg."}, {"en": "Same lead, just keep it moving.", "meaning": "Az elétartás jó volt; a hibát a megálló cső okozta.", "say": "Ugyanannyi elétartás, csak tartsd mozgásban."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "A sörétkép a számlap szerint a korongtól fölfelé és jobbra volt; lőj kicsit lejjebb, és adj egy kicsivel több elétartást.", "say": "Két óránál voltál – egy kicsit lejjebb, és jobban elé."}, {"en": "A barrel's width in front.", "meaning": "Tarts a korong előtt egy csőszélességnyi rést, ahogy a torkolatnál látod.", "say": "Egy csőszélességgel elé."}], "quiz": [{"q": "Az edző azt mondja: „Give it four foot” egy lövésznek, aki méterben gondolkodik. Mit mondasz?", "options": ["„Adj neki 1,22 métert”", "„Adj neki kb. egy métert”", "„Adj neki négy lábat”", "„Adj neki négy métert”"], "answer": 2, "why": "Az elétartás-szám az edző képe; ha utasítás közben átváltod, hamis pontosságot vagy hibát viszel bele, a „négy méter” pedig teljesen megváltoztatja a jelentést. Ha a lövész kérdezi, a korongok között nagyjából magyarázd el."}, {"q": "Mit jelent a „half a bird”?", "options": ["Egy korong szélességének a felét", "Eltört korongot", "A gép közelében repülő kis madarat", "A kör felét"], "answer": 0, "why": "A koronglövészetben a „bird” korongot jelent, így az edző fél korongszélességnyi elétartást kér."}, {"q": "Az edző azt mondja: „Same lead, keep it moving”. Miért kell lefordítani a „same lead” kifejezést?", "options": ["Ezt a bíró használja", "Különben a lövész növelheti az elétartást, és hibázik", "Udvarias köszönés a lövészek között", "Megváltoztatja a korongok sorrendjét"], "answer": 1, "why": "Hiba után a legtöbb lövész magától növeli az elétartást; a „same lead” megmondja neki, hogy az ok a megálló cső volt, nem az elétartás."}]}]}, {"id": "faults", "icon": "search", "title": "Hibák és ahogyan az edzők diagnosztizálják őket", "intro": "Amikor egy korong hibázott, az edző egy-két szóval megnevezi a hibát, aztán az okát. Ez a küldetés megtanítja a hibák és lövéshibák szavait, azt, hogy mit jelentenek valójában, és hogyan add tovább az edző diagnózisát a lövésznek gyorsan és pontosan.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Mögé, elé, fölé, alá, megcsípte", "body": ["Minden hibának iránya van. Az edző, aki a lövész mögül figyel, általában először azt mondja meg, hová ment a lövés a koronghoz képest, és csak utána azt, hogy miért. Add tovább azonnal: a lövész már a következő korongra készül.", "A mögé (behind) azt jelenti, hogy a lövés a mozgó korong mögött ment el: kevés volt az elétartás, vagy lelassult a fegyver. Ez a leggyakoribb hiba keresztezőknél. Az elé (in front) az ellentéte: túl sok elétartás, gyakran azután, hogy a lövész túlkorrigált. Sok edző kifejezetten szereti az elé lőtt hibát: azt mutatja, hogy a fegyver mozgásban maradt.", "A fölé (over, más néven „high”, „over the top”) és az alá (under, „low”) a függőleges hibát írja le. A fölé gyakori eső korongnál, nyúlnál és bejövő korongnál, és sokszor összefügg azzal, hogy a fej elválik a tustól. Az alá tipikus emelkedő korongoknál, amelyek a lövés pillanatában még emelkednek.", "A „chipped” azt jelenti, hogy csak egy kis darab vált le (megcsípte). Az edzőnek ez félig dicséret, félig korrekció: a korong a sörétkép szélén volt. A bírónak ez találat, ha a darab látható. A csapda a por: a szabályok szerint az a korong, amelyből csak por vagy füst száll, látható darab nélkül, elveszett. Az edzői szlengben viszont a „smoked it” tökéletes, középre talált lövést jelent (porrá lőtte), a „dusted it” pedig mindkét értelemben előfordul, ezért ha bizonytalan vagy, kérdezz rá.", "Tartsd meg az edző sorrendjét: irány, ok, javítás. Ha az edző azt mondja: „behind, you stopped”, az ok a fontosabb: az a lövész, aki csak annyit hall, hogy „mögé”, növeli az elétartást, ami nem gyógyítja a megálló csövet."], "key_points": ["Előbb az irányt add tovább: mögé, elé, fölé, alá.", "Mögé = kevés elétartás vagy lassuló fegyver; elé = túl sok elétartás.", "A látható darab a bírónak találat; ha csak por vagy füst, elveszett.", "A „smoked it” edzői dicséret, nem a szabályok „füstje”: soha ne keverd össze őket.", "Tartsd meg az edző sorrendjét: irány, ok, javítás."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "A lövés a korong mögött ment el; növeld az elétartást.", "say": "Mögé, adj neki többet."}, {"en": "Just over the top, it was already dropping.", "meaning": "A lövés fölé ment, mert a korong már esett; lőj alacsonyabbra és elé.", "say": "Épp fölé, már esett."}, {"en": "In front this time, good, now a touch less.", "meaning": "Túl sok elétartás, de a fegyver mozgott; csökkentsd kicsit az elétartást.", "say": "Most elé, jó, most egy kicsivel kevesebbet."}, {"en": "You just chipped it, a little more in front.", "meaning": "Találat a sörétkép szélén; egy kicsivel több elétartás középre hozza.", "say": "Csak megcsípted, egy kicsit még elé."}, {"en": "Smoked it! Same again.", "meaning": "Tökéletes, középre talált lövés (szleng, nem a szabályok „füstje”); ismételd meg pontosan.", "say": "Porrá lőtted! Még egyszer ugyanígy."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "Az ok a megálló cső; önmagában a több elétartás nem segít.", "say": "Mögé, de megállt a cső, úgyhogy ne csak az elétartást növeld."}], "quiz": [{"q": "Az edző bekiáltja: „Behind, you stopped!” Mi a legfontosabb rész, amit le kell fordítani?", "options": ["Az ok: megállt a cső", "Csak az irány: „mögé”", "Semmi: a lövész látta a hibát", "Felszólítás, hogy jóval több elétartást adjon"], "answer": 0, "why": "A több elétartás nem gyógyítja a megálló csövet; a lövésznek az okot kell kijavítania."}, {"q": "Egy kicsi, de jól látható darab válik le a korongról. Az edző azt mondja: „just chipped it”. Hogyan értékeli a bíró?", "options": ["Elveszett, mert a korong nagy része továbbrepült", "„No bird”", "Találat (egy)", "Csak akkor találat, ha az edző is egyetért"], "answer": 2, "why": "Legalább egy látható darab a Sporting™ és a Compak® Sporting versenyszámban is találattá teszi a korongot; a bíró egyedül dönt."}, {"q": "Egy találat után az edző bekiáltja: „Smoked it!” Mit akar mondani?", "options": ["Csak por szállt belőle, tehát elveszett", "Tökéletes, középre talált lövés", "Flash korong volt", "A lövésznek töltényt kell cserélnie"], "answer": 1, "why": "Az edzői szlengben a „smoked it” dicséret a porrá lőtt korongra; a szabályokban a por vagy füst látható darab nélkül hiba."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Fejfelemelés, megálló cső, túlkísérés, célzás", "body": ["Az irány után az edző megnevezi az okot. Négy ok minden edzésnapon előkerül, mindegyiknek megvan a maga rövid szava. Párban tanuld meg őket: a hiba és a javítás.", "Fejfelemelés (head lift): az arc a lövéskor vagy közvetlenül előtte elválik a tustól, gyakran azért, mert a lövész látni akarja, ahogy eltörik a korong. A szem a hátsó irányzék, ezért ha felemelkedik, elmozdul a kép, és a lövés általában fölé megy. Javítás: „head down” (fejet le), „cheek on the stock” (arc a tuson), „stay in the gun” (maradj a fegyverben).", "Megálló cső (stopping the gun): a csövek a lövésnél megállnak, többnyire azért, mert a lövész a csövön ellenőrzi az elétartást. A lövés mögé megy. Enyhébb változata a „checking”: a lendítés egy pillanatra megtorpan. Javítás: „keep the gun moving” (tartsd mozgásban a fegyvert), „follow through” (kísérd el), „finish the shot” (fejezd be a lövést).", "Túlkísérés (riding the target): a lövész túl sokáig követi a korongot a lövés előtt, így az lelassul, esik vagy elkanyarodik, és a lövész elveszíti a vonalat. Javítás: „take it earlier” (lődd korábban), „commit to it” (határozd el magad). Célzás (poking, más néven „aiming”, „measuring”): a sörétes puska lassú, puskaszerű ráirányítása, a szem a célgömbön a korong helyett. Tipikus, ha a lövési pont túl közel van, vagy egy teal korong tetőpontján. Javítás: „eyes on the clay” (a korongot nézd), „let the gun go” (engedd a fegyvert).", "Az edzők gyakran már azelőtt megnevezik az okot, hogy a lövész leengedte volna a fegyvert. Fordítsd le ugyanazzal a lendülettel és ugyanazzal az igével: a „you stopped” nem azt jelenti, hogy „hibáztál”. Az olyan szó, mint az „aiming”, szinte mindig bírálat, ezért soha ne csinálj belőle olyan tanácsot, hogy „célozz jobban”."], "key_points": ["Fejfelemelés: a lövés általában fölé megy; javítás: fejet le, maradj a fegyverben.", "Megálló cső vagy megtorpanás: a lövés mögé megy; javítás: tartsd mozgásban a fegyvert, kísérd el.", "Túlkísérés: a korong lelassul vagy elesik; javítás: lődd korábban, határozd el magad.", "Célzás: lassú, puskaszerű ráirányítás; javítás: a korongot nézd.", "Az okot azonnal fordítsd, az edző saját igéjével."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "Az arc elvált a tustól, ezért a lövés a korong fölé ment.", "say": "Felemelted a fejed, ezért ment fölé."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "A lendítés megállt a lövésnél; folytasd a mozgást a lövésen át és utána is.", "say": "Tartsd mozgásban a fegyvert, megálltál rajta."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Rövid habozás az elsütés előtt; dönts, és lőj lassítás nélkül.", "say": "Közvetlenül a lövés előtt megtorpantál, határozd el magad."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Bírálat: a lövész úgy irányoz, mint egy golyós puskával; fókuszálj a korongra, és lendíts szabadon.", "say": "Ne célozz, nézd a korongot, és engedd a fegyvert."}, {"en": "You rode it too long, take it earlier.", "meaning": "A lövész túl sokáig követte a korongot; lődd le hamarabb.", "say": "Túl sokáig vitted, lődd korábban."}, {"en": "Stay in the gun.", "meaning": "Az arc maradjon a tuson a lövés utánig.", "say": "Maradj a fegyverben."}], "quiz": [{"q": "Az edző azt mondja: „You lifted your head”. Hová ment valószínűleg a lövés?", "options": ["Mögé", "Fölé", "Alá", "Elé"], "answer": 1, "why": "A szem a hátsó irányzék: ha felemelkedik a fej, a lövés általában fölé megy."}, {"q": "Egy edző bekiáltja: „Stop aiming!” Mit akar?", "options": ["Ne irányozz úgy, mint golyós puskával: nézd a korongot, és lendíts", "Célozz pontosabban", "Azonnal szüntesd be a tüzelést", "Engedd le a fegyvert"], "answer": 0, "why": "Az „aiming” az edző szájából hiba (célzás); a javítás: a korongot nézni és szabadon lendíteni."}, {"q": "A „You rode it too long” azt jelenti…", "options": ["A lövész túl korán lőtt", "A dobógép túl lassú volt", "A lövész túl messze hátulról indult", "A lövész túl sokáig követte a korongot a lövés előtt"], "answer": 3, "why": "A „riding the target” azt jelenti, hogy a lövész túl sokáig követi a korongot, így az lelassul vagy esik, és elvész a vonal."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Vállba vételi hibák: késői, arc a fegyverhez, megdöntés", "body": ["Sok hiba már a lendítés előtt kezdődik, a vállba vételnél: annál a mozdulatnál, amely az archoz és a vállhoz emeli a fegyvert. Az edző szavai erre rövidek és testiek.", "Késői vállba vétel (late mount): a fegyver azután ér a vállba, hogy a lövésnek már el kellett volna dördülnie, ezért a lövész kapkod, vagy azelőtt lő, hogy az arca leérne. Az ellentétes hiba a túl korán befejezett vállba vétel, amely után a fegyver vár, mozdulatlanul és nehézként. Javítás: „move, mount, shoot” – mozdulj, vedd vállba, lőj –, ahol a csövek a koronggal együtt indulnak, és a vállba vétel a lövéssel együtt fejeződik be.", "Arc a fegyverhez (face to the gun): ahelyett, hogy a tust az archoz emelné, a lövész leengedi a fejét a tushoz. A szem így minden alkalommal máshová kerül, és a visszarúgás az arcot üti. Az edzők azt mondják: „bring the gun to your face, not your face to the gun” – a fegyvert hozd az arcodhoz, ne az arcodat a fegyverhez. Fáj az is, ha a tus a vállzseb helyett a karra kerül.", "Megdöntés (canting): a fegyver a lövéskor oldalra billen, és a lövés elsodródik a vonalról. Gyakran leesett vállal jár együtt. Javítás: „keep the gun level” (tartsd vízszintesen a fegyvert), „turn from the hips” (csípőből fordulj).", "A FITASC Parcours de Chasse – Sporting™ versenyeken a fegyvert nem szabad vállba venni, mielőtt a korong megjelenik, így a „pre-mount this one” (ezt vállból indítsd) csak edzésgyakorlat. Ha Sporting™ versenyen valaki korán veszi vállba, figyelmeztetést és sárga lapot kap. A Compak® Sporting versenyszámban a fegyver a korong kérésekor már vállban lehet. A gyakorlatot gyakorlatként fordítsd, és ne tegyél hozzá semmit magadtól."], "key_points": ["Késői vállba vétel: kapkodó lövés; javítás: mozdulj, vedd vállba, lőj.", "Arc a fegyverhez: elmozdul a szem, és fáj a visszarúgás; a fegyvert hozd az archoz.", "Megdöntés: a lövés elsodródik a vonalról; tartsd vízszintesen a fegyvert, csípőből fordulj.", "A vállból indítás gyakorlat: Sporting™ versenyen a korong megjelenése előtt tilos, a Compak® Sporting versenyszámban a korong kérésekor megengedett."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Emeld a tust az arcodhoz; ne engedd le a fejed a tushoz.", "say": "A fegyvert hozd az arcodhoz, ne az arcodat a fegyverhez."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Indulj a koronggal, a vállba vételt a lövéssel fejezd be, egyetlen folyamatos mozdulattal.", "say": "Mozdulj, vállba, lövés – egyben."}, {"en": "You canted the gun, keep it level.", "meaning": "A fegyver a lövéskor oldalra billent.", "say": "Megdöntötted a fegyvert, tartsd vízszintesen."}, {"en": "Mount on the line.", "meaning": "A fegyvernek már a korong pályáján kell feljönnie.", "say": "A vonalon vedd vállba."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Edzésgyakorlat már vállban lévő fegyverrel; Sporting™ versenyen nem megengedett.", "say": "Ezt indítsd vállból, csak gyakorlásképp."}], "quiz": [{"q": "Edzésen az edző egy FITASC Sporting™ versenyre készülő lövésznek azt mondja: „Pre-mount this one.” Mi igaz?", "options": ["Minden FITASC-versenyen megengedett", "A tolmácsnak meg kell tagadnia a fordítást", "Edzésgyakorlat; Sporting™ versenyen a fegyvert nem szabad vállba venni, mielőtt a korong megjelenik", "A lövés utáni vállba vételt jelenti"], "answer": 2, "why": "A Sporting™ leengedett fegyveres készenléti testhelyzetet ír elő, amíg a korong meg nem jelenik; a versenyen vállból indított lövésért figyelmeztetés és sárga lap jár."}, {"q": "A „You canted the gun” azt jelenti…", "options": ["A fegyver a lövéskor oldalra billent", "A fegyvert túl későn vette vállba", "Megállt a cső", "Be volt kapcsolva a biztosító"], "answer": 0, "why": "A „canting” a fegyver oldalirányú megdöntése, amely lehúzza a lövést a vonalról."}, {"q": "Melyik utasítás javítja az „arc a fegyverhez” hibát?", "options": ["Nyomd le erősebben a fejed", "A fegyvert hozd az arcodhoz", "Csukd be az egyik szemed", "Tartsd lejjebb a fegyvert a karodon"], "answer": 1, "why": "A tusnak kell feljönnie az archoz, hogy a szem minden alkalommal ugyanott legyen."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Dublék: a második korong", "body": ["Dublénál (pair, double) sok lövész eltalálja az első korongot, és elhibázza a másodikat. Az edző ilyenkor az átmenetről (transition), vagyis az első korongról a másodikra való átállásról, és a visszaállásról (recovery) beszél: arról, hogy az első lövés után a fegyver és a fej visszakerüljön az irányítás alá.", "Az aranyszabály: „eyes first, then the gun” – előbb a szem, aztán a fegyver. A szem elhagyja az eltört első korongot, és megkeresi a másodikat; a fegyver követi. Az a lövész, aki nézi, ahogy az első korong eltörik, vagy azelőtt lendíti a fegyvert, hogy megtalálta volna a másodikat, időt veszít. Az edzők azt mondják: „eyes to the second” (szemmel a másodikra), vagy egyszerűen rámutatnak.", "Visszaállás: a visszarúgás megemeli a csöveket és néha a fejet is. A „let the gun recover, then go” azt jelenti: az arc vissza a tusra, a fegyver vissza a vonalra, mielőtt a második korong után indulsz. A jó beállás előretolt testsúllyal gyorsítja a visszaállást.", "Tervezés: a dublé kiolvasása közben az edző eldönti, melyik korongot kell előbb lőni, és hol kell eltalálni, hogy a második könnyen felvehető legyen. Tipikus mondatok: „take the dropping one first” (az esőt lődd előbb), „break the first early” (az elsőt lődd korán), „stick to the plan” (tartsd magad a tervhez). Ha a lövész a lőálláson megváltoztatja a sorrendet, „went for the wrong one” – a rosszat lőtte előbb.", "A szabályok itt számítanak. A Parcours de Chasse – Sporting™ versenyszámban bármelyik dublé két korongja között szabad a fegyver helyzete, és a lövésznek két tölténye van a dubléra, mindkettő mehet ugyanarra a korongra. A Compak® Sporting versenyszámban dublénál korongonként csak egy töltény megengedett. A büntetéseket ne magyarázd el magad: fordítsd az edzőt, a szabálykérdéseket pedig hagyd a bíróra."], "key_points": ["Előbb a szem, aztán a fegyver.", "Visszaállás: az arc vissza a tusra, a fegyver a vonalra a második korong előtt.", "Az edző a dublé kiolvasása közben megtervezi a sorrendet és a lövési pontokat.", "Sporting™: a korongok között szabad a fegyver helyzete, és mindkét töltény mehet egy korongra; Compak® Sporting: korongonként egy töltény."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Előbb a szemeddel keresd meg a második korongot, csak aztán mozdítsd a fegyvert.", "say": "Előbb a szemed a második korongra, aztán a fegyver."}, {"en": "Let the gun recover, then go to the second.", "meaning": "A visszarúgás után a második lövés előtt állítsd vissza a fegyvert és az arcodat.", "say": "Hagyd visszaállni a fegyvert, aztán mehetsz a másodikra."}, {"en": "Take the dropping one first.", "meaning": "Azt a korongot lődd előbb, amelyik leghamarabb eltűnik vagy leesik.", "say": "Az esőt lődd előbb."}, {"en": "Don't watch the first one break.", "meaning": "A szemed azonnal menjen tovább a második korongra.", "say": "Ne nézd, ahogy az első eltörik."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "A lövész megváltoztatta a tervezett sorrendet; technikai megjegyzés, nem szabálysértés.", "say": "A rosszat lőtted előbb, tartsd magad a tervhez."}], "quiz": [{"q": "Mit jelent dublénál az „eyes first, then the gun”?", "options": ["Az első lövés után csukd be a szemed", "A második lövés előtt nézz a csőre", "Vedd vállba a fegyvert, mielőtt a dublét kéred", "Előbb a szemeddel találd meg a második korongot, csak aztán vidd rá a fegyvert"], "answer": 3, "why": "Jó átmenetnél a szem vezet, a fegyver követ."}, {"q": "Compak® Sporting dublénál a lövész elhibázza az első korongot, és a második töltényt is arra akarja lőni. Megengedett?", "options": ["Igen, mint a Sporting™ versenyszámban", "Igen, de csak szimultán dublénál", "Nem: Compak® Sporting dublénál korongonként csak egy töltény megengedett", "Csak a bíró engedélyével"], "answer": 2, "why": "A Compak® Sporting tiltja, hogy dublénál kétszer lőjenek az első korongra; a Sporting™ megengedi, hogy mindkét töltény egy korongra menjen."}, {"q": "Sporting™ dublénál leengedheti-e a lövész a fegyvert az első és a második korong között?", "options": ["Igen, a két korong között szabad a fegyver helyzete", "Nem, a fegyvernek vállban kell maradnia", "Csak vadászdublénál", "Csak ha a bíró engedi"], "answer": 0, "why": "A szabad helyzet bármely dublé korongjai között érvényes, de az első korong előtt nem."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Az edző olvasása: rövid utasítások és jelek", "body": ["A lőálláson az edző töredékekben beszél: „Behind.” „Head.” „More.” „Again.” A korongok között csak néhány másodperc van, ezért a rövidség szándékos. A fordításod is legyen ugyanilyen rövid; egy hosszú mondat a következő korongkérés után érkezik meg.", "Sok edző előbb kérdez, és csak utána mond valamit: „Where did it go?” (hová ment?) vagy „What did you see?” (mit láttál?). Ez tanítási kérdés, nem a tolmács vizsgáztatása. Fordítsd le a kérdést, hagyd, hogy a lövész válaszoljon, és a választ pontosan fordítsd vissza, akkor is, ha tévesnek hangzik. Az edzőnek tudnia kell, mit érzékelt a lövész.", "A kézjelek sokat közölnek. Gyakoriak: széttáruló vagy közeledő kezek a több vagy kevesebb elétartásra, lefelé mozduló lapos kéz a „lejjebb” jelzésére, egy koppintás az arcon a „fejet le” jelzésére, a korong vonalát követő ujj, felfelé tartott hüvelykujj a „még egyszer ugyanígy” jelzésére. A jelek edzőnként eltérnek, ezért beszéljétek meg őket a foglalkozás előtt, és ne fordíts le olyan gesztust, amelyet a lövész már látott.", "Vannak szavak, amelyek tisztán a ritmusról és a bátorításról szólnak: „commit”, „trust it”, „smooth”, „good, same again”. Tartsd meg a hangnemet. A hiba utáni „bad luck” (pech) kedvesség, nem megjegyzés a bíróra.", "Versenyen az edzői irányítás tilos: a bíró sárga lapot ad a versenyzőnek, az edzőt pedig kiküldi a lőterületről. A szabályok nem mondják meg, hogy a tolmács továbbíthatja-e verseny közben az edző tanácsát: ez a FITASC számára nyitott kérdés. A biztonságos gyakorlat: versenyen csak a bírónak, a zsűrinek és a szervezőnek tolmácsolj."], "key_points": ["Az edzők töredékekben beszélnek; fordíts ugyanilyen röviden.", "A „Where did it go?” tanítási kérdés: a lövész válaszát pontosan fordítsd.", "A kézjeleket beszéljétek meg a foglalkozás előtt.", "Versenyen nincs edzői irányítás; csak a bírónak, a zsűrinek és a szervezőnek tolmácsolj."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "Az edző azt kérdezi, a lövész szerint hová ment a lövés; tanítási kérdés.", "say": "Hová ment?"}, {"en": "What did you see?", "meaning": "Írd le a képet a lövés pillanatában.", "say": "Mit láttál?"}, {"en": "More.", "meaning": "Az adott helyzetben szinte mindig „több elétartás”.", "say": "Többet."}, {"en": "Good, same again.", "meaning": "Ismételd meg pontosan, amit az előbb csináltál.", "say": "Jó, még egyszer ugyanígy."}, {"en": "Trust it, commit to it.", "meaning": "Ne habozz; dönts, és lőj.", "say": "Bízz benne, határozd el magad."}, {"en": "Bad luck.", "meaning": "Együttérzés hiba után; nem panasz a bíróra.", "say": "Pech."}], "quiz": [{"q": "Az edző megkérdezi a lövészt: „Where did it go?” Mit tegyen a tolmács?", "options": ["Válaszoljon a lövész helyett", "Fordítsa le a kérdést, aztán pontosan a lövész válaszát", "Magyarázza el a hibát a saját szavaival", "Ne mondjon semmit: ez költői kérdés"], "answer": 1, "why": "Az edző a lövész saját érzékelésére kíváncsi, ezért a válasznak változatlanul kell eljutnia hozzá."}, {"q": "Verseny közben a lövész edzője megkér, hogy add tovább: „Give the next one more lead.” Mi a biztonságos gyakorlat?", "options": ["Halkan továbbadni", "Csak a lőállások között továbbadni", "Versenyen nem továbbítani az edzői irányítást; csak a bírónak, a zsűrinek és a szervezőnek tolmácsolni", "Előbb megkérdezni a többi lövészt"], "answer": 2, "why": "Versenyen az edzői irányítás tilos, és a szabályok nem mondják meg, hogy a tolmács továbbíthatja-e; ha kimaradsz belőle, a lövészt véded."}, {"q": "Mi történik a szabályok szerint, ha a bíró úgy ítéli meg, hogy egy versenyzőt edzői irányítással segítenek?", "options": ["Sárga lap a versenyzőnek; az edzőt kiküldik a lőterületről", "Semmi: az edzői irányítás megengedett", "A korongot megismétlik", "Az egész rottét kizárják"], "answer": 0, "why": "Mindkét szabálykönyv sárga lapot ad a versenyzőnek, ismétlés esetén súlyosabb büntetéssel, és eltávolítja az edzőt."}]}]}, {"id": "sporting", "icon": "flag", "title": "A Parcours de Chasse – Sporting™ szabályai", "intro": "A Parcours de Chasse – Sporting™ az a FITASC-versenyszám, amely természetes terepen a vadászatot utánozza. Ez a küldetés úgy vezet végig a szabályain, ahogyan egy bíró alkalmazza őket: körök és lőállások, leengedett fegyveres kezdés, szóló korongok és dublék, a korongok bemutatása, hibás működés és időkorlátok. Itt minden összefoglalás; a szabályhivatkozások a ClayArena szabályútmutatóját nyitják meg.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Körök, lőállások és a lövési sorrend", "body": ["A Parcours de Chasse – Sporting™ versenyt 25 korongos körökben számolják. Egy nemzetközi verseny 200 korong, tehát nyolc kör; minden kört egy lőpályán (lőállások egy csoportján) vagy egy vonalon lőnek.", "Minden lőpálya 15 szóló korongot és 5 dublét ad. A lőállások és dobógépek száma a rendszertől függ: a régi rendszer 3 lőálláshoz 5 dobógépet használ, az új rendszerű vonalakon pedig 4 vagy 5 lőállás van, mindegyiken 3 vagy 4 dobógéppel. A dobógépeket A, B, C, D betűkkel jelölik, balról jobbra, ahogy a lőállásból látszik. A lőállás előtti kotta lövési sorrendben sorolja fel őket, a különleges korongokkal együtt: 90, 70 vagy 60 mm, battue, nyúl.", "Maga a lőállás 1 m-es négyzet vagy 1 m átmérőjű kör. Minden röppályának nehézségi osztálya van: A (egy átlagos lövész több mint 80%-ot talál el), B (60–80%) vagy C (40–60%).", "A lövészek legfeljebb hatfős, sorsolással összeállított rottékban haladnak. Minden lőállásnál mindenki előbb a szóló korongokat lövi, aztán a dublékat, és a lövési sorrend minden lőállásnál, majd a dubléknál is újra forog. A többiek a közelben várnak, anélkül, hogy zavarnák azt, aki lő.", "Az eredménylapot a bíró vezeti, vagy egy általa felügyelt személy, minden korongot a dobógép betűjele alá jegyezve. Minden lőállás elhagyásakor minden lövész ellenőrzi az eredményét; nézeteltérés esetén azonnal a bíróhoz kell fordulni, és a bíró döntése végleges."], "key_points": ["Kör = 25 korong egy lőpályán: 15 szóló + 5 dublé; nemzetközi verseny = 200 korong.", "A, B, C, D dobógépek balról jobbra, ahogy a lőállásból látszik; a kotta adja meg a sorrendet és a különleges korongokat.", "Legfeljebb hatfős rotték; előbb a szóló korongok, aztán a dublék; a sorrend forog.", "Minden lőállás elhagyásakor ellenőrizd az eredményedet; a bíró dönt."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "A szokásos sorrend minden lőállásnál.", "say": "Előbb a szóló korongok, aztán a dublék."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "A kottatábla abban a sorrendben sorolja fel a dobógépeket, ahogyan lőni fogják őket.", "say": "Olvasd el a kottát: a gépek sorrendje A, B, C."}, {"en": "Next shooter.", "meaning": "A bíró a következő lövészt szólítja a lőállásra.", "say": "Következő lövész."}, {"en": "Check your score before you leave the stand.", "meaning": "Bármilyen nézeteltérést most kell jelezni, nem később.", "say": "Mielőtt elhagyod a lőállást, ellenőrizd az eredményedet."}], "quiz": [{"q": "Hány korongot ad egy Sporting™ lőpálya, és hogyan oszlanak meg?", "options": ["20: 10 szóló és 5 dublé", "25: mind szóló", "25: 15 szóló és 5 dublé", "50: 25 szóló és 25 dublé"], "answer": 2, "why": "Minden lőpályatípus 15 szóló korongot és 5 dublét ad, ami 25 korong."}, {"q": "Milyen sorrendben lő a rotte egy lőállásnál?", "options": ["Előbb a dublék, aztán a szóló korongok", "Mindenki előbb a szóló korongokat lövi, aztán a dublékat, és a sorrend forog", "Minden lövész egyben lövi le az egész lőpályát", "A lövészek szabadon választanak"], "answer": 1, "why": "Előbb a szóló korongok, aztán a dublék jönnek, forgó sorrendben, hacsak a zsűri másként nem dönt."}, {"q": "A lőállás elhagyásakor egy lövész észreveszi, hogy egy találatát hibának jegyezték fel. Mit tegyen?", "options": ["Várja meg a kör végét, és fellebbezzen a zsűrihez", "Javítsa ki maga a lapot", "Kérje a rotte szavazását", "Azonnal szóljon a bírónak; a bíró dönt"], "answer": 3, "why": "Az eredményt minden lőállás elhagyásakor ellenőrzik; egyedül a bíró dönt, és utána nincs fellebbezés."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "A leengedett fegyveres kezdés", "body": ["A Parcours de Chasse – Sporting™ leglátványosabb szabálya a leengedett fegyveres kezdés. A korong kérése előtt a lövész mindkét lábbal a lőálláson belül áll, a tus sarka érinti a testét, a tus felső hátsó pontja pedig a mellényen lévő vonal alatt van. Ezt a készenléti testhelyzetet addig kell tartani, amíg a korong ki nem repült, és láthatóvá nem vált.", "A vonalat a mellényen vagy a kabáton, 25 cm-rel a vállak tengelye alatt, azzal párhuzamosan jelölik, a mellénytől elütő színnel, hogy a bíró láthassa. A szabály minden tustípusra vonatkozik, az állítható pofadékosakra is.", "A fegyvert csak akkor szabad felemelni, amikor a korong megjelenik. Minden korongot, a nyulat is, vállból kell lőni; csípőből lőni tilos. Bármely dublé első és második korongja között a fegyver helyzete szabad, de az első korong előtt a készenléti testhelyzet érvényes.", "Büntetések: amikor a lövész első alkalommal szabálytalan helyzetben kéri a korongot, vagy a korong megjelenése előtt vállba veszi a fegyvert, a bíró szóbeli figyelmeztetést ad sárga lappal. Minden további szabálysértés ugyanazon a lőpályán piros lappal jár, és a korong értékelése: szóló korongnál nulla, vadászdublénál nulla és „No bird”, szimultán vagy rafale dublénál nulla és nulla.", "A korong kérése előtt vállba venni a fegyvert és végiglendíteni egy elképzelt vonalon (lövés imitálása) szintén tilos: először figyelmeztetés, aztán nulla. Ha egy edző Parcours de Chasse – Sporting™ verseny előtt vállból indított kezdést gyakoroltat, a „drill” (gyakorlat) szót is fordítsd le."], "key_points": ["A korong kérése előtt: mindkét láb a lőálláson belül, a tus érinti a testet, a tus teteje a mellényvonal alatt.", "A mellényvonal 25 cm-rel a vállak tengelye alatt van, kontrasztos színnel.", "Vállba vétel csak a korong megjelenésekor; mindig vállból kell lőni; a dublé korongjai között szabad a helyzet.", "Első szabálysértés: figyelmeztetés + sárga lap; a következő ugyanazon a lőpályán: piros lap és a korong értékelése."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Bíró: a korong kérése előtt vidd a tust a mellényvonal alá.", "say": "Fegyvert le, kérem."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Az első szabálysértés a fegyver helyzetével: szóbeli figyelmeztetés sárga lappal.", "say": "A tusa a vonal fölött volt. Ez figyelmeztetés."}, {"en": "Don't mount before the target appears.", "meaning": "A fegyvert csak akkor szabad felemelni, amikor a korong már látható.", "say": "Ne vegye vállba, mielőtt a korong megjelenik."}, {"en": "Red card, zero.", "meaning": "Ismételt szabálysértés ugyanazon a lőpályán; a szóló korong elveszett.", "say": "Piros lap, nulla."}], "quiz": [{"q": "Első lőállás. Egy lövész már vállban lévő fegyverrel kéri a korongot. Ez az első szabálysértése ezen a lőpályán. Mi a bíró döntése?", "options": ["A korong nulla", "Szóbeli figyelmeztetés sárga lappal", "„No bird”, és semmi más", "Kizárás"], "answer": 1, "why": "A fegyver helyzetével kapcsolatos első szabálysértés szóbeli figyelmeztetés, sárga lappal megerősítve."}, {"q": "Ugyanazon a lőpályán, két lőállással később ugyanez a lövész a mellényvonal fölött tartott tussal kér egy szóló korongot. Döntés?", "options": ["Újabb sárga lap", "„No bird”", "Piros lap, és a korongot megismétlik", "Piros lap, és a szóló korong nulla"], "answer": 3, "why": "A figyelmeztetés után az ugyanazon a lőpályán elkövetett újabb szabálysértés piros lap: szóló korongnál nulla."}, {"q": "Vadászdublé. Az első korong eltalálása után a lövész a második előtt kissé leengedi a fegyvert. Döntés?", "options": ["Megengedett: a két korong között szabad a fegyver helyzete", "Sárga lap", "A második korong nulla", "„No bird”"], "answer": 0, "why": "A szabad helyzet bármely dublé korongjai között érvényes; a készenléti testhelyzet csak az első előtt kötelező."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Szóló korongok és dublék", "body": ["A szóló korong egy korong egy dobógépből. A Parcours de Chasse – Sporting™ versenyszámban a lövész két töltényt lőhet rá, így az első csővel elhibázott korongot a másodikkal még meg lehet menteni. Minden szóló korongnál időt kell hagyni két lövésre.", "A dublé két korong, és a lövésnek csak két tölténye van rá; mindkettő mehet ugyanarra a korongra. Három fajtája van. Vadászdublé (on report): a második korong 0–3 másodperccel az elsőre leadott lövés után repül ki, azt a lövés indítja. Szimultán: mindkettő ugyanabban a pillanatban indul, egy vagy két dobógépből. Rafale: két korong ugyanabból a dobógépből, ugyanazon a vonalon, a második olyan gyorsan, ahogy a gép újratölt. Szimultán és rafale dublénál a korongok tetszőleges sorrendben lőhetők. A dublékhoz csak olyan korongokat használnak, amelyeket ugyanabból a lőállásból már szóló korongként bemutattak.", "Döntések, amelyeket a bírónak gyakran meg kell hoznia: ha egy lövés bármely dublé mindkét korongját eltöri, mindkettő számít, egy és egy. Ha a lövész alapos indok nélkül nem lő a rafale vagy szimultán dublére, az nulla és nulla.", "Vadászdublénál a szabálytalan első korong azt jelenti, hogy a dublét megismétlik; ha az első korong vagy annak darabjai a második lövés előtt eltörik a másodikat, vagy a második szabálytalan, a dublét megismétlik, és az első eredmény megmarad. Szimultán és rafale dublénál a szabálytalan korong eredmény feljegyzése nélküli ismétlést jelent.", "Tipp: a dublé eredményét párként add tovább, a bíró sorrendjében."], "key_points": ["Szóló korong: két töltény megengedett.", "Dublé: összesen két töltény, mindkettő mehet egy korongra; fajtái: vadász, szimultán, rafale.", "Egy lövés mindkét korongot eltöri: egy és egy.", "Ha a lövész indok nélkül nem lő szimultán vagy rafale dublére: nulla és nulla."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Edző: a második korongot az elsőre leadott lövés indítja.", "say": "Vadászdublé: a második a lövésedre jön."}, {"en": "On the rafale, take either one first.", "meaning": "Rafale dublénál a sorrend szabad.", "say": "A rafale-nál bármelyiket lőheted előbb."}, {"en": "One and one.", "meaning": "Bíró: a dublé mindkét korongja találat.", "say": "Egy és egy."}, {"en": "No Bird, repeat the double.", "meaning": "Szabálytalan korong; a dublét újra dobják.", "say": "No bird, ismételjük a dublét."}], "quiz": [{"q": "Szimultán dublé. Egy lövés mindkét korongot eltöri. Mi a bíró döntése?", "options": ["Egy és egy", "Egy és „No bird”", "„No bird”, a dublét megismétlik", "Egy és nulla"], "answer": 0, "why": "A Sporting™ versenyszámban bármely dublénál az egy lövéssel eltört két korong egy és egy (a Compak® Sporting versenyszámban más)."}, {"q": "Vadászdublé. A lövész eltalálja az első korongot, és annak egy darabja a második lövés előtt összetöri a másodikat. Döntés?", "options": ["Egy és egy", "A dublét megismétlik, és az első eredmény megmarad", "A második korong nulla", "Egy és nulla"], "answer": 1, "why": "Ha az első korong vagy annak darabjai a második lövés előtt eltörik a másodikat, a dublét megismétlik, és az első eredmény érvényes marad."}, {"q": "Rafale dublé. Mindkét korong szabályosan repül, de a lövész leengedi a fegyvert, és egyikre sem lő, alapos indok nélkül. Döntés?", "options": ["„No bird”", "Nulla és „No bird”", "Csak sárga lap", "Nulla és nulla"], "answer": 3, "why": "Az a szabályos korong, amelyre a lövész alapos indok nélkül nem lő, elveszett; rafale vagy szimultán dublénál ez nulla és nulla."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "A korongok bemutatása", "body": ["Mielőtt egy rotte egy lőállást lő, a bíró bemutatja a korongokat. A bemutatás a korongok kiolvasására szolgál: vonal, sebesség, távolság, és hogy mit csinál a korong. Minden röppályát a rotte első lövészének mutatnak be, akinek készenlétben kell állnia a lőálláson.", "A lőálláson álló lövész kérheti a bírót, hogy ismételje meg a bemutatást, a kotta sorrendjének minden korongjából legfeljebb két korongot.", "A vadászdublékat nem mutatják be, mert a második korong csak a lövés hangjára indul. A szimultán és rafale dublékat minden rotte első lövészének bemutatják, és kérésre legfeljebb két bemutatott dublét megismételnek.", "A bemutatás alatt a fegyverek nyitva és üresen vannak, mint minden megszakításkor, és csak akkor zárják vissza őket, amikor a bíró engedi. A bemutatás alatt tilos lőni vagy lövést imitálni, és ezt úgy büntetik, mint a fegyver helyzetével kapcsolatos szabálysértést: először figyelmeztetés, aztán piros lap.", "Ha egy dobógép elromlik, vagy a lövészet tíz percnél hosszabb ideig szünetel, a bíró újra bemutatja az adott lőállás korongjait. A verseny előtt senki nem gyakorolhat a versenylőpályákon.", "Edzésen a bemutatás az edző kedvenc pillanata: „watch where it turns” (figyeld, hol fordul). Versenyen a bemutatás a verseny része, így itt is érvényes az edzői irányítás tilalma: maradj csendben, hacsak a bírónak vagy a lövésznek nincs szüksége eljárási fordításra."], "key_points": ["Minden röppályát az első lövésznek mutatják be, aki készenlétben áll a lőálláson.", "Ismétlés kérésre: a kotta minden korongjából legfeljebb kettő.", "A vadászdublékat soha nem mutatják be; a szimultán és rafale dublékat igen.", "Bemutatáskor nyitott fegyver; nincs lövés vagy lövésimitálás.", "10 percnél hosszabb megszakítás: a korongokat újra bemutatják."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "A lövész a bírónak: kezdje el a bemutatást.", "say": "Kérem, mutassa be a korongokat."}, {"en": "Again, please, B only.", "meaning": "Kérés a kotta egy korongjának megismétlésére.", "say": "Még egyszer, kérem, csak a B-t."}, {"en": "Guns open during the show.", "meaning": "Bíró: nyisd ki és ürítsd ki, amíg nem engedi a bezárást.", "say": "Bemutatás alatt nyitott fegyver."}, {"en": "Watch where it turns.", "meaning": "Az edző edzésen: figyeld meg azt a pontot, ahol a korong irányt vagy alakot vált.", "say": "Figyeld, hol fordul."}], "quiz": [{"q": "Melyik dublékat NEM mutatják be?", "options": ["A szimultánt", "A rafale-t", "A vadászdublét", "Egyiket sem: mindet bemutatják"], "answer": 2, "why": "A vadászdublé második korongja csak a lövésre indul, ezért ezeket a dublékat nem mutatják be."}, {"q": "Hányszor kérheti a lőálláson álló lövész egy korong ismétlését?", "options": ["Egyszer sem", "A kotta minden korongjából legfeljebb kettőt", "Ahányszor szükséges", "Lőállásonként egyszer"], "answer": 1, "why": "A bíró kérésre megismétli a bemutatást, a kotta sorrendjének minden korongjából legfeljebb két korongot."}, {"q": "A bemutatás alatt egy lövész bezárja a fegyverét, és végiglendít egy korong vonalán. Mi érvényes?", "options": ["Tilos: a fegyver helyzetére vonatkozó büntetések érvényesek, figyelmeztetés, aztán piros lap", "Semmi: a bemutatás szabad", "A korongot újra bemutatják", "Csak az edzőt figyelmeztetik"], "answer": 0, "why": "A bemutatás alatt a fegyverek nyitva maradnak, a lövést vagy lövésimitálást pedig a figyelmeztetésre és piros lapra vonatkozó szabályok szerint büntetik."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Fegyver- és lőszerhibák", "body": ["A hibás működés a fegyver vagy a töltény meghibásodása: csütörtök, a második cső elmaradt lövése, vagy ha a két cső egyszerre sül el (beduplázás). A Parcours de Chasse – Sporting™ versenyszámban az eseteket 25 korongos körönként számolják.", "Először is, mit kell tennie a lövésznek: a helyén marad, a fegyver a lőtér felé mutat, nem nyitja ki, és nem nyúl a biztosítóhoz, amíg a bíró meg nem vizsgálta. Ha előbb kinyitja a fegyvert vagy a biztosítóhoz nyúl, a korongot vagy korongokat nullának értékelik.", "Az első eset egy körben „No bird” figyelmeztetéssel, és a korongot megismétlik. Ugyanabban a körben a második esettől a korongot már nem ismétlik meg, hanem nullának értékelik.", "Az első eset részletei: ha az első lövés nem sül el, a szóló korongot vagy bármely dublét megismétlik, de ha a lövész ennek ellenére leadja a második lövést, annak eredménye érvényes. Ha szóló korongnál a második lövés nem sül el, a korongot megismétlik, és ekkor csak a második lövéssel lehet eltalálni; az első lövéssel elért találat nulla. Vadászdublénál az első eredmény megmarad, és a dublét megismétlik. A szóló korongnál vagy bármely dublé első korongjánál történő beduplázás „No bird”, semmit nem jegyeznek fel.", "Ha a fegyvert megjavítják, mielőtt a rotte befejezi a lőállást, a lövész a bíró engedélyével utolsóként lőhet; különben azonnal folytathatja egy másik fegyverrel, vagy a zsűri jóváhagyásával egy másik rottéban fejezheti be. Ha már a lőálláson van, fegyvert, szűkületet vagy csövet nem cserélhet."], "key_points": ["Hiba után: maradj a helyeden, a fegyver a lőtér felé, ne nyisd ki, és ne nyúlj a biztosítóhoz.", "Az első eset egy körben: „No bird” + figyelmeztetés, a korongot megismétlik.", "A második eset ugyanabban a körben: nulla, nincs ismétlés.", "A második lövés hibája szóló korongnál: az ismétlésnél csak a második lövéssel elért találat számít."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Bíró: várd meg a vizsgálatot; ha előbb kinyitod, a korongba kerül.", "say": "Maradjon ott, ne nyissa ki a fegyvert."}, {"en": "Let me see the gun.", "meaning": "A bíró megvizsgálja a fegyvert vagy a töltényt.", "say": "Mutassa a fegyvert."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Az első eset a körben: a korongot megismétlik.", "say": "Hibás működés. No bird, első figyelmeztetés."}, {"en": "Second malfunction this round. Zero.", "meaning": "Ezúttal nincs ismétlés; a korong elveszett.", "say": "Második hibás működés ebben a körben. Nulla."}], "quiz": [{"q": "Az első fegyverprobléma a körben: szóló korongnál az első töltény csütörtököt mond. A lövész a fegyverrel a lőtér felé várja a bírót. Döntés?", "options": ["Nulla", "„No bird” figyelmeztetéssel; a korongot megismétlik", "Egy", "Sárga lap és nulla"], "answer": 1, "why": "Egy körben az első fegyver- vagy lőszerhiba „No bird” figyelmeztetéssel, és a szóló korongot megismétlik."}, {"q": "A töltény csütörtököt mond, és a bosszús lövész a bíró érkezése előtt megtöri a fegyvert, hogy megnézze a csappantyút. Döntés?", "options": ["„No bird”", "A korongot figyelmeztetés után megismétlik", "Nulla", "Piros lap, és a korongot megismétlik"], "answer": 2, "why": "Ha a lövész a bíró ellenőrzése előtt kinyitja a fegyvert vagy a biztosítóhoz nyúl, a korongot nullának értékelik."}, {"q": "Szóló korong, első eset: az első lövés hibázik, a második töltény csütörtököt mond, így a korongot megismétlik. Az ismétlésnél a lövész az első lövéssel eltalálja. Döntés?", "options": ["Egy", "Ismét „No bird”", "Egy, figyelmeztetéssel", "Nulla: ennél az ismétlésnél csak a második lövéssel elért találat számít"], "answer": 3, "why": "A második lövés hibája után a megismételt szóló korongot csak a második lövéssel lehet eltalálni, ezért az első lövéssel szándékosan mellé kell lőni."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Időkorlátok és késés", "body": ["A Parcours de Chasse – Sporting™ feszes ritmusban zajlik, és több szabály is védi ezt. Amikor a lövész azt mondja: „pull” vagy „ready”, a bíró hangjelzéssel továbbítja a kérést a pullernek, és a korongnak három másodpercen belül ki kell repülnie; a később érkező korong „No bird”.", "A szóló korongok vagy a dublék között a lövésznek legfeljebb 15 másodperce van. Amikor ezt először túllépi, a bíró figyelmeztet; utána a piros lapos büntetések érvényesek. Egy óvásról hozott végleges döntés után a lövésznek 15 másodpercen belül folytatnia kell, különben az az utasítás megtagadásának számít; a szándékos húzásra ugyanez vonatkozik.", "Késés: ha egy lövész hiányzik, a bíró egy percen belül háromszor szólítja a nevét és a számát. Ha az első lőállás szóló korongjainál a sora előtt érkezik, az semmibe nem kerül. Utána minden le nem lőtt korong nulla; ha egy későbbi lőállásnál csatlakozik, a korábbi lőállások összes korongja nulla. Egy kihagyott lőállásokkal rendelkező lőpályát soha nem lehet egy másik rottéban újra lőni.", "Annak a lövésznek, aki rajta kívül álló okból késik, abban a körben nem szabad visszatérnie a rottéjába, hanem írásban a zsűrihez kell fellebbeznie. Ha a zsűri elfogadja, a kört egy másik rottéban lövi le; ha nem, minden le nem lőtt lőpályára 25 nullát kap.", "Ha valaki hallásvédelem vagy lövészszemüveg nélkül lép a lőállásra, az távollétnek számít. Előre nem tervezett szétlövésnél a lövészeknek a szólítástól számított 15 percen belül készen kell állniuk.", "Neked: soha ne tartsd fel a rottét egy hosszú fordítással. Most röviden, a részleteket a lőállás után."], "key_points": ["A korong a bíró jelzése után 3 másodpercen belül, különben „No bird”.", "Legfeljebb 15 másodperc a szóló korongok vagy dublék között: figyelmeztetés, aztán piros lap.", "Végleges döntés után 15 másodpercen belül folytatni, különben az utasítás megtagadása.", "Késés: a nevet és a számot egy percen belül háromszor szólítják; a kihagyott korongok nullák."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "A bíró egy hiányzó lövészt szólít (egy percen belül háromszor).", "say": "Huszonhármas lövész!"}, {"en": "Watch your time.", "meaning": "Emlékeztető a korongok közötti 15 másodperces korlátra.", "say": "Figyeljen az időre."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Az első alkalom a korlát fölött: figyelmeztetés; legközelebb büntetés.", "say": "Több mint tizenöt másodperc. Ez figyelmeztetés."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Szemvédő nélkül a lövészt távollévőnek tekintik.", "say": "Szemüveget fel, különben nem lőhet."}], "quiz": [{"q": "A lövész kéri a korongot, a bíró továbbítja a jelzést, de a korong kb. öt másodperccel később repül ki. A lövész lő és hibáz. Döntés?", "options": ["Nulla", "„No bird”", "Egy", "Figyelmeztetés a lövésznek"], "answer": 1, "why": "A bíró jelzése után több mint három másodperccel kirepülő korong „No bird”."}, {"q": "Egy lövész akkor érkezik, amikor a rottéja még az 1-es lőállás szóló korongjait lövi, és még nem került rá a sor. Mi történik?", "options": ["Büntetés nélkül csatlakozik", "25 nulla", "Az 1-es lőállás összes szóló korongja nulla", "Egy másik rottéval kell lőnie"], "answer": 0, "why": "Ha a lövész még azelőtt érkezik, hogy az első lőállás szóló korongjainál lekéste volna a sorát, nem jár büntetés."}, {"q": "Két szóló korong között egy lövész kb. 25 másodpercig vár, ma először. Döntés?", "options": ["A következő korong nulla", "Piros lap", "Semmilyen következmény", "Figyelmeztetés a bírótól"], "answer": 3, "why": "A korlát 15 másodperc; első túllépéskor a bíró figyelmeztet, és csak ezután következnek büntetések."}]}]}, {"id": "compak", "icon": "grid", "title": "A Compak® Sporting szabályai", "intro": "A Compak® Sporting a Parcours de Chasse – Sporting™ változatosságát egy kis területre sűríti: öt lőállás egy vonalban, hat dobógép és egy kijelölt téglalap, amely fölött a korongoknak át kell repülniük. Sok szabály ugyanolyannak látszik, de a fegyver helyzete, az időkorlátok, a dublék és a büntetések eltérnek. Az a tolmács, aki összekeveri a két versenyszámot, téves információt ad a lövésznek.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Lőpálya, kotta és rotáció", "body": ["A Compak® Sporting lőpálya eleve kompakt. A korongoknak egy kijelölt, 35–40 m széles és 25 m mély téglalap fölött kell átrepülniük, amelynek minden sarkán zászló vagy jelölő áll. Vele szemben öt lőállás van, mindegyik 1 m-es négyzet, egy vonalban, 4–8 m-rel az elülső oldal mögött; a 3-as lőállás középen van.", "Hat dobógép van, balról jobbra A-tól F-ig betűzve, mindegyiken tábla. Minden Compak® pályán kötelező egy balról jobbra keresztező, egy jobbról balra keresztező és egy elmenő korong; a többi röppályát a szervező választja. Minden lőálláson lőszögkorlátozó (firing angle limiter) van: ez egy keret, amely megakadályozza, hogy a fegyver túl messzire lendüljön, és a lövészt a lőálláson belül tartja.", "Egy kör 25 korong, lőállásonként öt: öt szóló korong, három szóló és egy dublé, vagy egy szóló és két dublé. Egy Compak® pályán a dublé típusa minden lőálláson ugyanaz. A kotta, vagyis a korongok sorrendje minden lőálláson ki van függesztve, és minden dublé első korongja az előző lőálláson utoljára lőtt korong.", "Rotáció a legfeljebb hatfős rottében: mindig az 1-es lőállás kezd, a hatodik lövész mögötte vár. Amikor az 5-ös lőálláson álló lövész végzett, az 1-es lőállás mögé megy várakozni, mindenki egy lőállással jobbra lép, a várakozó lövész pedig beáll az 1-esre. A lőállást nyitott, üres fegyverrel kell váltani, anélkül, hogy bárkit zavarnánk, aki még lő.", "Az egyvonalas (in-line) Compak® másként működik: egy csoport minden lövésze az 1-es lőállástól az 5-ösig halad."], "key_points": ["Téglalap 35–40 m × 25 m; öt 1 m-es lőállás; hat dobógép A–F.", "Kötelező: balról jobbra keresztező, jobbról balra keresztező, elmenő korong.", "Kör = 25 korong, lőállásonként 5; Compak® pályánként egyféle dublé.", "Minden dublé az előző lőállás utolsó korongjával kezdődik.", "Az 5-ös lőállás után: várakozás az 1-es mögött; mindenki egy lőállással jobbra lép."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Rotáció, miután az 5-ös lőálláson álló lövész végzett.", "say": "Egy lőállással jobbra."}, {"en": "Gun open when you change stations.", "meaning": "Lőállások között a fegyver nyitva és üresen van.", "say": "Lőállásváltáskor nyitott fegyver."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "A Compak® kotta láncszabálya.", "say": "A dubléd az előző lőállás utolsó korongjával kezdődik."}, {"en": "You're waiting behind one.", "meaning": "A hatodik lövész az 1-es lőállás mögött áll.", "say": "Te az egyes mögött vársz."}], "quiz": [{"q": "Hány dobógép és lőállás van egy Compak® Sporting lőpályán?", "options": ["4 dobógép, 3 lőállás", "6 dobógép, 5 lőállás", "5 dobógép, 5 lőállás", "8 dobógép, 6 lőállás"], "answer": 1, "why": "A Compak® hat dobógépet (A–F) és öt lőállást használ."}, {"q": "Az 5-ös lőálláson álló lövész befejezte a kottáját. Hová megy?", "options": ["Az 1-es lőállásra", "Az 5-ös lőálláson marad", "Az 1-es lőállás mögé, várakozni", "A bíróhoz aláírni a lapot"], "answer": 2, "why": "Ő lesz az 1-es lőállás mögött várakozó lövész, miközben mindenki más egy lőállással jobbra lép."}, {"q": "Compak® pályán minden dublé első korongja…", "options": ["bármelyik korong, amelyet a lövész választ", "mindig az A gép", "csak kérésre bemutatott korong", "az előző lőálláson utoljára lőtt korong"], "answer": 3, "why": "A kotta összeláncolja a lőállásokat: minden dublé azzal a koronggal kezdődik, amelyik az előző lőállást zárta."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "A fegyver helyzete, a korong kérése és az idő", "body": ["Itt tér el a Compak® Sporting a leglátványosabban a Parcours de Chasse – Sporting™ versenyszámtól. A korong kérésekor a fegyver helyzete szabad: a fegyver már vállban lehet, vagy nem. Nincs leengedett fegyveres kezdés, és nincs vonal a mellényen. Minden korongra továbbra is vállból kell lőni.", "Indítás: a dobógépeket kézzel, távirányítóval vagy hangvezérléssel (sonopull) indítják. Kézi indításnál a korongnak a kérés után 0–3 másodpercen belül ki kell repülnie; a hangvezérlésnek fix 0,5 másodperces késleltetése van. A nemzetközi egyvonalas versenyeken csak hangvezérlést használnak. Az a korong, amely a kérés után több mint 3 másodperccel repül ki, vagy amelyet a lövész nem kért, „No bird”.", "Idő: a lövésznek az előző lőállás korongjának lelövése után legfeljebb 10 másodperce van a korong kérésére, kevesebb, mint a Sporting™ versenyszám 15 másodperce. Első alkalommal a bíró figyelmeztetést jegyez fel az eredménylapra; ha ugyanabban a körben megismétlődik, piros lap jár, és a korongokat így értékelik: szóló korong nulla, vadászdublé nulla és „No bird”, szimultán dublé nulla és nulla.", "Bemutatás: rotte-rendszerű lövészetnél a korongokat reggel egyszer mutatják be, az első rottének. Az 1-es lőálláson álló lövész sorban kéri a szóló korongokat A-tól F-ig; aztán a bíró bemutatja a szimultán dublékat, és bemondja: „start” vagy „competition”. Több mint 10 perces megszakítás után a hat szóló korongot újra bemutatják.", "Töltés: csak a saját lőálláson, nyitott fegyverrel, amely a lőtér felé, a lőszögkorlátozón belül mutat; csak akkor zárd be, amikor te következel."], "key_points": ["A korong kérésekor a fegyver helyzete szabad; lövés mindig vállból.", "Kézi indítás a kérés után 0–3 s; hangvezérlés fix 0,5 s; 3 s-nál később = „No bird”.", "Legfeljebb 10 másodperc a korong kérésére: feljegyzett figyelmeztetés, aztán nullák.", "A korongokat reggel egyszer mutatják be az első rottének; 10 percnél hosszabb szünet után újra."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Bíró: a bemutatás véget ért, kezdődik az értékelt lövészet.", "say": "Start! / Verseny!"}, {"en": "Gun up or down, your choice here.", "meaning": "Edző: a Compak® versenyszámban a fegyver helyzete a korong kérésekor szabad.", "say": "Itt fent vagy lent tartott fegyverrel, ahogy akarod."}, {"en": "Ten seconds, call your target.", "meaning": "Emlékeztető a korong kérésére vonatkozó 10 másodperces korlátra.", "say": "Tíz másodperc, kérd a korongot."}, {"en": "Warning: time.", "meaning": "Első alkalom 10 másodperc fölött; feljegyzik az eredménylapra.", "say": "Figyelmeztetés: idő."}], "quiz": [{"q": "Compak® Sporting versenyszámban a lövész már vállban lévő fegyverrel kéri a korongot. Mi a bíró döntése?", "options": ["Sárga lap", "Megengedett: a fegyver helyzete a korong kérésekor szabad", "Nulla", "Csak dubléknál megengedett"], "answer": 1, "why": "A Compak® Sporting versenyszámban nincs leengedett fegyveres kezdés és mellényvonal; csak magát a lövést kell vállból leadni."}, {"q": "Kézi indítás. A korong kb. négy másodperccel a kérés után repül ki, és a lövész hibáz. Döntés?", "options": ["Nulla", "Egy", "Csak a puller kap figyelmeztetést, a nulla marad", "„No bird”"], "answer": 3, "why": "A kérés után több mint 3 másodperccel kirepülő korong „No bird”, és újra dobják."}, {"q": "Ugyanabban a körben másodszor telik el több mint 10 másodperc, mire a lövész kéri a korongot. Szóló korongról van szó. Döntés?", "options": ["Nulla", "Csak újabb figyelmeztetés", "„No bird”", "Kizárás"], "answer": 0, "why": "Az első figyelmeztetés után az ugyanabban a körben történő ismétlést a táblázat szerint büntetik: a szóló korong nulla."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Szóló korongok és dublék a Compak® versenyszámban", "body": ["A Compak® Sporting ugyanazokat a szavakat használja, mint a Parcours de Chasse – Sporting™, de a dublékra más szabályok vonatkoznak. Az a tolmács, aki átviszi ide a Sporting™ szabályait, téves válaszokat fog adni.", "Szóló korongok: minden szóló korongra mind az öt lőállásból két lövést kell lehetővé tenni, így a második cső jogos második esély.", "A Compak® szabálykönyv kétféle dublét határoz meg: vadászdublé (on report – a kérés indítja az első korongot, a lövés a másodikat; egy vagy két dobógéppel) és szimultán dublé (két korong egy kérésre, mindig két különböző dobógépből, tetszőleges sorrendben lőhetők). Rafale nincs.", "A legfontosabb különbség: Compak® dublénál minden korongra csak egy töltényt lehet kilőni. Tilos mindkét lövést az első korongra leadni, és a bírói gyorsútmutató a szándékos dupla lövést egy korongra nulla és nulla értékkel pontozza. A Sporting™ versenyszámban mindkét töltény mehet egy korongra.", "Két korong egy lövéssel: vadászdublénál az első eredmény érvényes, a második „No bird”, és a dublét újra lövik. Szimultán dublénál „No bird”, semmit nem értékelnek, és a dublét megismétlik; másodszor ugyanígy; harmadszor nulla és nulla. A Sporting™ versenyszámban ugyanez a lövés egyszerűen egy és egy.", "Szabálytalan korongok: ha a vadászdublé első korongja vagy a szimultán dublé bármelyik korongja szabálytalan, új dublét dobnak. Ha a vadászdublé második korongja szabálytalan, vagy az első töri el, az első eredmény érvényes, és a dublét megismétlik."], "key_points": ["Csak kétféle dublé: vadászdublé és szimultán dublé; rafale nincs.", "Dublénál korongonként egy töltény; mindkettő egy korongra = nulla és nulla (gyorsútmutató).", "Vadászdublé, kettő egy lövéssel: az első eredmény marad, a második „No bird”, a dublé ismétlődik.", "Szimultán dublé, kettő egy lövéssel: kétszer „No bird”, harmadszor nulla és nulla."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Edző: Compak® versenyszámban a dublé minden korongjára csak egy töltény jut.", "say": "Itt a dubléknál korongonként egy lövés."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Bíró szimultán dublénál: semmit nem értékelnek, ismétlés.", "say": "Mindkettő egy lövéssel. „No bird”, lődd újra a dublét."}, {"en": "Choose your order on the show.", "meaning": "Edző: a bemutatás közben döntsd el, melyik szimultán korongot lövöd először.", "say": "A bemutatáson válaszd ki a sorrendet."}, {"en": "Zero, zero.", "meaning": "Bíró: a dublé egyik korongja sem találat.", "say": "Nulla, nulla."}], "quiz": [{"q": "Szimultán dublé Compak® versenyszámban. Egy lövés mindkét korongot eltöri; most fordul elő először. Döntés?", "options": ["Egy és egy", "„No bird”, semmit nem értékelnek, a dublét megismétlik", "Egy és „No bird”", "Nulla és nulla"], "answer": 1, "why": "Compak® versenyszámban az egy lövéssel eltört szimultán dublé első és második alkalommal „No bird”, harmadszor nulla és nulla."}, {"q": "Vadászdublé Compak® versenyszámban. Egy lövés mindkét korongot eltöri. Döntés?", "options": ["Egy és egy", "Nulla és nulla", "Az első eredmény érvényes, a második „No bird”, és a dublét megismétlik", "„No bird”, semmit nem értékelnek"], "answer": 2, "why": "Vadászdublénál az első korong eredményét feljegyzik, és a dublét újra lövik, hogy a másodikat értékelni lehessen."}, {"q": "Compak® dublénál a lövész elhibázza az első korongot, és szándékosan a második töltényt is arra lövi. Hogyan pontozza a bírói gyorsútmutató?", "options": ["Nulla és nulla", "Megengedett, mint a Sporting™ versenyszámban", "A dublét megismétlik", "Csak a második lövés számít"], "answer": 0, "why": "Compak® dublénál korongonként csak egy töltény megengedett; a szándékos dupla lövés egy korongra nulla és nulla."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Hibás működés a Compak® versenyszámban", "body": ["A Compak® Sporting versenyszámban – akárcsak a Parcours de Chasse – Sporting™ versenyszámban – a fegyver- és lőszerhibákat 25 korongos körönként számolják: az első eset „No bird” és sárga lap; ugyanolyan típusú második esetnél a le nem lőtt korongokat nullának értékelik, piros lappal.", "Mit kell tennie a lövésznek: a helyén marad, a fegyver a lőtér felé mutat, nem nyitja ki, és nem nyúl a biztosítóhoz, amíg a bíró meg nem vizsgálta. Ha előbb kinyitja, elveszíti a korongot vagy korongokat: nulla.", "Első eset, ha a két cső egyszerre sül el (beduplázás), vagy az első töltény nem sül el: a szóló korongot újra dobják, a vadászdublét vagy a szimultán dublét újra dobják, és a sikertelen kísérletből semmit nem értékelnek. Ha a második töltény mond csődöt: szóló korongnál a korongot újra dobják, de csak a második lövés lehet találat, így az elsővel szándékosan mellé kell lőni; vadászdublénál az első eredmény érvényes, és a dublét a második miatt megismétlik; szimultán dublénál új dublé jár.", "Hibás működés után a lövésznek két perce van megjavítani vagy kicserélni a fegyvert. Kivételesen kölcsönkérhet fegyvert egy saját rottéján kívüli lövésztől, a tulajdonos és a bíró beleegyezésével. Működő fegyver nélkül a hátralévő korongok nullák. Egyébként egy körön belül fegyvert, choke-ot (szűkületet) vagy csövet cserélni nem lehet.", "Ugyanez a logika érvényes arra a nyúlra, amelyet az első lövéssel elhibáztak, és a második előtt eltörik: „No bird”, és az ismétlésnél csak a második lövés számít."], "key_points": ["Az első eset a körben: „No bird” + sárga lap; ugyanolyan típusú második: nulla + piros lap.", "A bíró vizsgálata előtt ne nyisd ki a fegyvert, és ne nyúlj a biztosítóhoz.", "A második töltény hibája szóló korongnál: az ismétlésnél csak a második lövés számít.", "Két perc a javításra vagy cserére; kölcsönkérni csak a rottén kívülről lehet, a tulajdonos és a bíró beleegyezésével."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Bíró: hiba után várd meg a vizsgálatot.", "say": "Ne mozdulj, a fegyver maradjon zárva."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Az első ilyen típusú eset a körben; a korongot újra dobják.", "say": "Első hibás működés. Sárga lap, „No bird”."}, {"en": "You have two minutes.", "meaning": "Idő a fegyver megjavítására vagy kicserélésére.", "say": "Két perced van."}, {"en": "Only the second shot counts on this one.", "meaning": "Ismétlés a második töltény hibája után: az első lövéssel szándékosan lőj mellé.", "say": "Ennél csak a második lövés számít."}], "quiz": [{"q": "Az első eset a körben Compak® versenyszámban: szóló korongnál nem sül el az első töltény. A lövész szabályosan vár. Döntés?", "options": ["„No bird” sárga lappal; új korongot dobnak", "Nulla", "Piros lap és nulla", "Egy"], "answer": 0, "why": "Egy körben az első fegyver- vagy lőszerhiba „No bird”, sárga lappal jelzett első figyelmeztetéssel."}, {"q": "Egy lövész fegyvere elromlik. Kölcsön akarja kérni egy rottetársa fegyverét. Megengedett?", "options": ["Igen, a tulajdonos beleegyezésével", "Igen, ha a bíró hozzájárul", "Igen, feltétel nélkül", "Nem: a kölcsönadónak a rottén kívül kell lennie, és a tulajdonosnak és a bírónak is bele kell egyeznie"], "answer": 3, "why": "A Compak® tiltja a fegyver megosztását egy csoporton belül; kivételesen csak azon kívülről lehet kölcsönkérni, mindkét beleegyezéssel."}, {"q": "Ugyanolyan típusú második fegyverhiba ebben a körben, egy szóló korongnál, amelyre a lövész nem tudott lőni. Döntés?", "options": ["Ismét „No bird”", "„No bird” és figyelmeztetés", "Nulla, piros lappal", "A korongot újra bemutatják"], "answer": 2, "why": "Ugyanolyan típusú második esettől a le nem lőtt korongokat nullának értékelik."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Öltözet és magatartás", "body": ["A Compak® Sporting versenyek nyilvánosak, ezért az öltözetnek illőnek és praktikusnak kell lennie. A rövid sort tilos, de a legfeljebb 5 cm-rel térd fölött végződő bermuda megengedett. A felsőnek legalább rövid ujjúnak kell lennie, és a nyakig kell érnie; a póló rendben van, a mellény alatti csupasz felsőtest nem. A szandál edzésen és versenyen is tilos. A rajtszámot a háton kell viselni, teljesen láthatóan; az első szabálysértés figyelmeztetéssel jár, utána szankciók következnek.", "A fül- és szemvédelem kötelező. Ha valaki nélkülük érkezik a lőállásra, az távollétnek számít: nem lőhet.", "Pontosság: időben jelentkezz a bírónál. Rotte-rendszerű lövészetnél, ha valaki azután érkezik, hogy a rotte első lövésze kérte az első korongot, a körre 25 nullát kap; fellebbezni még aznap, írásban lehet a zsűrihez.", "Magatartás: verseny közben az edzői irányítás (coaching) tilos; a versenyző sárga lapot kap, az edzőt pedig eltávolítják a lőterületről. Ha valaki a lövészet folytatása után vitatja a végleges döntést, vagy lövészként vagy nézőként nyíltan bírálja a döntést, az a bíró befolyásolására tett kísérlet, és kizárással járhat. Minden kör végén a lövész aláírja az eredménylapot; aki megtagadja az aláírást, elveszíti a panasztétel jogát.", "A lőállás közelében te is a közönség része vagy: viselj védőeszközt, maradj csendben a korong kérésekor, és soha ne kommentálj döntést. Hogy versenyen továbbíthatod-e az edző szavait, az a FITASC számára nyitott kérdés; a biztonságos gyakorlat az, hogy csak a bírónak, a zsűrinek és a szervezőnek tolmácsolsz."], "key_points": ["Nincs rövid sort, csupasz felsőtest a mellény alatt, szandál (edzésen sem); rajtszám a háton.", "Fül- vagy szemvédő nélkül a lőálláson = távollét, nem lőhet.", "Késés a rotte első korongkérése után: 25 nulla; aznapi írásos fellebbezés lehetséges.", "Nincs edzői irányítás; nincs nyilvános bírálat a döntésekről; írd alá az eredménylapot."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Bíró: a rajtszámnak teljesen láthatónak kell lennie a háton.", "say": "A rajtszámot a hátadra, kérlek."}, {"en": "Ears and eyes on.", "meaning": "A lőállás előtt tedd fel a fülvédőt és a szemüveget.", "say": "Fülvédő, szemüveg fel."}, {"en": "Sign the sheet, please.", "meaning": "A kör vége: a lövész aláírja az eredménylapot.", "say": "Kérlek, írd alá a lapot."}, {"en": "No coaching on the stand.", "meaning": "A bíró figyelmeztetése: versenyen az edzői irányítás tilos.", "say": "A lőállásban nincs edzői irányítás."}], "quiz": [{"q": "Egy lövész szandálban érkezik a lőállásra egy edzéskörre. Megengedett?", "options": ["Igen, csak edzésen", "Nem: a szandál edzésen és versenyen is tilos", "Igen, zoknival", "Csak a bíró engedélyével"], "answer": 1, "why": "A Compak® öltözködési szabályai biztonsági okból edzésen és versenyen is tiltják a szandált."}, {"q": "Rotte-rendszerű lövészet. Egy lövész közvetlenül azután érkezik, hogy a rottéja első lövésze kérte az első korongot. Eredmény?", "options": ["Nincs büntetés", "Csak az első korong nulla", "A rotte végén lő", "25 nulla a körre; aznap írásos fellebbezés nyújtható be a zsűrihez"], "answer": 3, "why": "A határidő a rotte első korongkérése; utána a késő lövész 25 nullát kap, hacsak a zsűri el nem fogad egy alapos indokot."}, {"q": "A kör után egy lövész megtagadja az eredménylap aláírását, mert egy döntéssel nem ért egyet. Mi a következmény?", "options": ["Elveszíti a jogot bármilyen panaszra", "A bírónak meg kell változtatnia az eredményt", "A kört újralövik", "Semmi nem történik"], "answer": 0, "why": "Minden kör végén kötelező aláírni a lapot; az aláírás megtagadása miatt minden panasz elfogadhatatlanná válik."}]}]}, {"id": "referee", "icon": "whistle", "title": "Bíró, pontozás és büntetések", "intro": "Versenyen a bíró az, akinek a szavait a leggyakrabban és a legnagyobb gondossággal fogod fordítani. Ez a küldetés megadja az elhangzó bírói szavakat, az eredménylapot, a lapokat és büntetéseket, az óvási eljárást és a korcsoportokat, hogy minden döntés pontosan úgy jusson el a lövészedhez, ahogy meghozták.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "Mit mond a bíró a lőálláson", "body": ["A lőállásnak saját rövid nyelve van. A lövész akkor kéri a korongot, amikor készen áll, általában így: „Pull!” vagy „Ready!”. A Parcours de Chasse – Sporting™ versenyszámban a bíró ezt a kérést hangjelzéssel továbbítja a pullernek, és a korongnak három másodpercen belül ki kell repülnie; a később érkező korong „No bird”. A Compak® Sporting versenyszámban a kézi indításnak szintén a kérés után három másodpercen belül meg kell történnie, a hangvezérlésnek (sonopull) pedig fix fél másodperces késleltetése van.", "Mielőtt bárki lőne, a bíró irányítja a fegyvereket. Tölteni csak a lőálláson szabad, a fegyverrel a lőtér felé, miután a bíró kimondta, hogy kezdődhet a lövészet. A korongok bemutatása alatt és minden megszakításkor a fegyverek nyitva és üresen vannak, és csak a bíró szavára zárják vissza őket. A Compak® versenyszámban a bíró a „Start” vagy „Competition” szóval indítja a kört.", "Minden korong után a szabályok három eredményt ismernek: „egy” (találat), „nulla” (hiba) és „No bird” (a korong nem számít, és újra dobják). Világszerte hallani fogod a „dead”, „good”, „lost” szavakat is, vagy találatnál egyszerűen csendet. A Compak® versenyszámban a bírónak minden nullát hangosan vagy hangjelzéssel kell bejelentenie, hogy az a lövész, aki nem ért egyet, azonnal óvást tehessen.", "A lövésznek is van egy hivatalos szava: felemelt kézzel „Protest!” vagy „Appeal!” (óvás). Tolmácsoláskor ezeket a szavakat mindig röviden és ugyanúgy mondd. A kör előtt egyezz meg a lövészeddel, milyen szavakat fogsz használni, és a korong kérése és a lövés között soha ne tegyél hozzá semmit magadtól."], "key_points": ["A lövész „Pull!”-t vagy „Ready!”-t mond; a korongnak 3 másodpercen belül jönnie kell", "Tölteni csak a lőálláson és csak a bíró engedélyével; bemutatáskor és megszakításkor nyitott fegyver", "Szabályszavak: egy = találat, nulla = hiba, „No bird” = újra dobják", "Compak®: minden nullát hangosan vagy hangjelzéssel bejelentenek", "Óvás = felemelt kéz + „Protest!” vagy „Appeal!”"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "A bíró engedélyezi a lövészet kezdetét: most tedd be a töltényeket, a fegyverrel a lőtér felé.", "say": "Tölthetsz."}, {"en": "No bird!", "meaning": "Az a korong nem számít; ne lőj rá. Újra dobják.", "say": "No bird!"}, {"en": "Lost.", "meaning": "A bíró a korongot hibának (nullának) értékelte.", "say": "Nulla."}, {"en": "Dead. / Good.", "meaning": "A korong találat (egy).", "say": "Egy. / Talált."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Mindenki kinyitja és kiüríti a fegyverét; a bíró bemutatásra dobja a korongokat.", "say": "Fegyvereket kinyitni, kérem – bemutatjuk a korongokat."}, {"en": "Start. / Competition.", "meaning": "Compak®: a bemutatás véget ért, mostantól számít a kör.", "say": "Start. / Verseny."}], "quiz": [{"q": "A Parcours de Chasse – Sporting™ versenyszámban a korong öt másodperccel a bíró jelzése után repül ki. Mi a döntés?", "options": ["Rendesen számít", "„No bird”", "Nulla, mert a lövész túl korán kérte", "Csak a puller kap figyelmeztetést"], "answer": 1, "why": "A korongnak a bíró jelzése után három másodpercen belül ki kell repülnie; a később érkező „No bird”, és újra dobják."}, {"q": "Mikor töltheti meg a lövész a fegyvert?", "options": ["Amíg a lőálláshoz sétál", "A lőállás mögött, várakozás közben", "A lőálláson, a fegyverrel a lőtér felé, miután a bíró engedélyezte a lövészetet", "Amikor az edző mondja"], "answer": 2, "why": "Tölteni csak a lőálláson, a lőtér felé szabad, és csak miután a bíró engedélyezte a kezdést."}, {"q": "Melyik szó indít hivatalos óvást a lőálláson?", "options": ["„Protest!” vagy „Appeal!” felemelt kézzel", "„Pull!”", "„No bird!”", "„Bíró, nézze!”"], "answer": 0, "why": "Mindkét szabálykönyv a felemelt kézzel mondott „protest” vagy „appeal” szót nevezi meg; a „No bird” kizárólag a bíróé."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Eredménylapok, eredmények és holtversenyek", "body": ["Minden korong az eredménylapra kerül. A Parcours de Chasse – Sporting™ versenyszámban az eredménylapot a bíró vezeti, vagy valaki a bíró felügyelete alatt. A FITASC-minta minden korongnál feltünteti a dobógép betűjelét, a találatot X-szel, a hibát O-val jelöli, és van rajta összeg és aláírási oszlop. Mielőtt a rotte továbbmegy, a bíró lefényképezi a lapot.", "A lövészeknek minden lőállás elhagyásakor ellenőrizniük kell az eredményüket. A nézeteltérés azonnal a bíró elé kerül; a bíró dönt, esetleg másokat is megkérdezve, és ez után nincs fellebbezés. A Compak® Sporting versenyszámban a lövész a kör végén aláírja az eredménylapot, és aki megtagadja az aláírást, elveszíti a panasztétel jogát. A „check your card” mondatot sürgős utasításként fordítsd, ne udvarias megjegyzésként.", "Egy nemzetközi verseny 200 korong, 25-ös körökben. Ha az első három helyen holtverseny alakul ki, a lövészek 25 korongos szétlövést lőnek; ha ezután is egyenlők, hirtelen halál (sudden death) következik, ahol az első nulla kiesést jelent. A harmadik hely alatt nincs szétlövés: a holtversenyben lévő lövészek osztoznak a helyen, és fordított sorrendű összevetéssel (countback) rangsorolják őket, az utolsó (nyolcadik) lőpályától vagy Compak® pályától visszafelé az elsőig. Csapatok soha nem lőnek szétlövést.", "A szétlövések egy újabb tolmácscsapdát rejtenek. Ha nem rögzítettek időpontot, a lövészeknek a szólítástól számított tizenöt percen belül készen kell állniuk. A hiányzó lövész a Sporting™ szabályai szerint „kizárt” (disqualified), a Compak® szabályai szerint „visszalépettnek tekintendő” (considered withdrawn). Annak a versenyszámnak a szavát használd, amelyiken éppen vagy."], "key_points": ["X = találat, O = hiba a FITASC-eredménylapokon", "Sporting™: minden lőállás elhagyásakor ellenőrizd az eredményt; Compak®: írd alá a lapot, vagy elveszíted a panasztétel jogát", "Holtverseny az 1–3. helyen: 25 korongos szétlövés, aztán hirtelen halál", "A 3. hely alatt: fordított sorrendű összevetés a 8. lőpályától vagy Compak® pályától; csapatoknál nincs szétlövés", "A szétlövésre szólítástól számított 15 percen belül készen kell állni"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Most nézd meg a jelöléseidet; a későbbi kifogásokat nem fogadják el.", "say": "Mielőtt elhagyod a lőállást, ellenőrizd a lapodat."}, {"en": "Sign here, please.", "meaning": "Compak®: az aláírás megerősíti az eredményt; a megtagadása a panasztétel jogának elvesztésével jár.", "say": "Itt írja alá, kérem."}, {"en": "Twenty-three — you dropped two.", "meaning": "25-ből 23 az eredmény; két korong hiba volt.", "say": "Huszonhárom – kettőt hibáztál."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Légy a megnevezett lőpályán, és állj készen a lövésre tizenöt percen belül.", "say": "Holtverseny van a harmadik helyen – szétlövés tizenöt perc múlva."}, {"en": "Sudden death: first zero is out.", "meaning": "A 25 korongos szétlövés után az a lövész esik ki, aki (azonos számú lelőtt korong mellett) először hibázik.", "say": "Hirtelen halál: az első nulla kiesik."}], "quiz": [{"q": "Mit jelent az O a FITASC-eredménylapon?", "options": ["Találatot", "„No bird”-öt", "Hibát", "Üres lőállást"], "answer": 2, "why": "A FITASC-minta a találatot X-szel, a hibát O-val jelöli."}, {"q": "Két lövész holtversenyben áll a 7. helyen. Mi történik?", "options": ["25 korongos szétlövés", "Azonnal hirtelen halál", "A zsűri pénzfeldobással dönt", "Osztoznak a helyen, és fordított sorrendű összevetéssel rangsorolják őket"], "answer": 3, "why": "Szétlövés csak az 1–3. helyért van; alatta a holtversenyben lévőket fordított sorrendű összevetéssel rangsorolják a nyolcadik lőpályától vagy Compak® pályától."}, {"q": "A Compak® Sporting versenyszámban a lövészed megtagadja az eredménylap aláírását. Mi a következmény?", "options": ["Elveszíti a jogot bármilyen panaszra", "A kört újralövik", "A bíró aláírja, és semmi nem változik", "Automatikusan 25 nullát kap"], "answer": 0, "why": "A Compak® szabályai szerint az a lövész, aki megtagadja az aláírást, elveszíti a panasztétel jogát."}]}, {"id": "referee-cards", "minutes": 5, "title": "Figyelmeztetések, lapok és büntetések", "body": ["A FITASC büntetései lépcsőzetesen emelkednek. Nevezésével a lövész elfogadja a szabályokat és a szankciókat. Egy szabály első megsértése általában figyelmeztetéssel jár, amelyet sárga lappal jeleznek. A Parcours de Chasse – Sporting™ versenyszámban klasszikus példa a fegyver helyzete: ha a tus a mellényen lévő vonal fölött van, vagy a fegyvert a korong megjelenése előtt vállba veszik, szóbeli figyelmeztetés és sárga lap jár.", "Ugyanazon a lőpályán (vagy ugyanazon a Compak® pályán) történő ismétlés piros lappal jár, a korongot pedig táblázat szerint értékelik: szóló korongnál nulla, vadászdublénál nulla és „No bird”, szimultán vagy rafale dublénál nulla és nulla. Ugyanez a skála vonatkozik a bejelentett „No bird”-re leadott lövésre, és a Sporting™ versenyszámban a korongok közötti tizenöt másodperc túllépésére. A Compak® Sporting versenyszámban a korong kérésére tíz másodperc a korlát.", "A verseny közbeni edzői irányítást is büntetik: a lövész sárga lapot kap, az ismétlés további szankciókhoz vezet, a bíró pedig kiküldi a lőterületről azt, aki irányította. Egy tolmács számára ez a legfontosabb lap az egész szabálykönyvben.", "Ismételt szabálysértésért, az utasítás megtagadásáért vagy a bíró befolyásolására tett kísérletért a zsűri elvehet egy korongot, egy teljes 25-ös kört, vagy kizárhatja a lövészt. A fegyver eldobása, a szidalmazás vagy az erőszak, valamint az élő állatokra leadott szándékos lövés azonnali kizárást vonhat maga után. A kizárást a FITASC öt évig nyilvántartja, és nem jár vele visszatérítés. A „warning”, „yellow card” és „red card” szavakat szó szerint, nyugodtan és azonnal fordítsd: figyelmeztetés, sárga lap, piros lap."], "key_points": ["Első szabálysértés: figyelmeztetés sárga lappal", "Ismétlés ugyanazon a lőpályán vagy Compak® pályán: piros lap + a korong táblázat szerinti értékelése", "Edzői irányítás versenyen: sárga lap a lövésznek, az edzőt eltávolítják", "A zsűri skálája: egy korong, egy kör vagy kizárás", "Kizárás: 5 évig nyilvántartva, visszatérítés nélkül"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: a fegyver túl magasan volt a korong megjelenése előtt; ezen a lőpályán legközelebb a korongba kerül.", "say": "Figyelmeztetés – a tus a vonal fölött volt."}, {"en": "That’s a yellow card.", "meaning": "Hivatalos első figyelmeztetés; feljegyzik.", "say": "Ez sárga lap."}, {"en": "Red card — the target is zero.", "meaning": "Ismételt szabálysértés: a korongot hibának értékelik.", "say": "Piros lap – a korong nulla."}, {"en": "You’re over time.", "meaning": "A lövész a megengedettnél tovább várt (Sporting™: 15 s, Compak®: 10 s a korong kérésére).", "say": "Túllépted az időt."}, {"en": "Sir, please leave the shooting area.", "meaning": "A bíró eltávolít valakit, például egy edzői irányításon kapott személyt.", "say": "Uram, kérem, hagyja el a lőterületet."}], "quiz": [{"q": "Sporting™: a vállba vett fegyverért kapott sárga lap után a lövész ugyanazon a lőpályán, egy szóló korongnál ismét korán veszi vállba a fegyvert. Mi az eredmény?", "options": ["Újabb figyelmeztetés", "Piros lap, és a korong nulla", "„No bird”", "Azonnali kizárás"], "answer": 1, "why": "Az első figyelmeztetés után az ugyanazon a lőpályán elkövetett újabb szabálysértés piros lappal jár; szóló korongnál a korong nulla."}, {"q": "A bíró látja, hogy egy edző verseny közben tanácsot ad egy lövésznek. Mit mondanak a szabályok?", "options": ["Semmit, a lőállások között az edzői irányítás megengedett", "Az edző piros lapot kap", "A lövész sárga lapot kap, az edzőt pedig eltávolítják a lőterületről", "A kört törlik"], "answer": 2, "why": "Mindkét szabálykönyv sárga lapot ad a versenyzőnek, és a bíró kiküldi a lőterületről az irányító személyt."}, {"q": "Melyiket NEM szabhatja ki a zsűri a büntetési skála szerint?", "options": ["Egy korong elvesztése", "Egy 25-ös kör elvesztése", "Kizárás", "A bírónak fizetendő pénzbírság"], "answer": 3, "why": "A zsűri skálája: egy korong elvesztése, egy kör elvesztése vagy kizárás; bírónak fizetendő bírság nincs."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Óvások, letétek és a zsűri", "body": ["Az óvást a helyszínen kell megtenni. A lövész a lőálláson felemeli a kezét, és azt mondja: „Protest!” vagy „Appeal!”, mielőtt a következő korongot kérné (a Compak® Sporting versenyszámban mielőtt a következő lövész kérné). A bíró leállítja a lövészetet, és meghallgatja az indokot. Ha a lövész kéri a következő korongot, ezzel elfogadja az előző döntést, ezért tolmácsként itt gyorsnak kell lenned.", "Ha a bíró biztos a dolgában, megerősíti a döntést, amely ezzel végleges. Ha kétsége van, megkérdezhet egy másik bírót, a pullert vagy a rotte lövészeit, de csak tanácsként, aztán egyedül dönt. A lövészek soha nem mehetnek ki, és nem vehetnek fel korongot, hogy megvizsgálják, a természetes akadály mögött vagy a lőterület határán túl eltört korongról pedig a bíró dönt.", "Bizonyos döntések soha nem kerülhetnek a zsűri elé: hogy a korong egy volt-e vagy nulla, a „No bird”, és hogy a röppálya szabályos volt-e. Más döntések ellen írásban, letét mellett lehet a zsűrihez fellebbezni: a Parcours de Chasse – Sporting™ versenyszámban ez a nevezési díj 40%-a; a Compak® versenyszámban az aznap érvényes összeg, és csak az aznapi eseményekkel kapcsolatban. Ha a fellebbezés sikeres, a letétet visszaadják.", "A végleges döntés után a lövésznek a Sporting™ versenyszámban tizenöt, a Compak® versenyszámban tíz másodpercen belül folytatnia kell; különben az az utasítás megtagadásának számít. A további vitatkozás, a bíró látványos kihívása, vagy ha mások nyíltan bírálják a döntést, a bíró befolyásolására tett kísérletnek számít. A te feladatod az, hogy az óvást és a választ pontosan fordítsd, nem az, hogy érvelj az ügyben."], "key_points": ["Óvás azonnal, a lőálláson, felemelt kézzel: „Protest!” / „Appeal!”", "A következő korong kérése = az előző döntés elfogadása", "Soha nem fellebbezhető: egy/nulla, „No bird”, szabályos röppálya", "Írásos fellebbezés a zsűrihez letéttel (Sporting™: a nevezési díj 40%-a)", "Folytatás 15 s-on (Sporting™) vagy 10 s-on (Compak®) belül; a további vita = a bíró befolyásolása"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "A lövész hivatalosan vitatja a döntést, és megadja az indokot (itt: törött korongot dobtak).", "say": "Óvás! A korong már a lövésem előtt eltört."}, {"en": "I’m certain — the decision stands.", "meaning": "A bíró megerősíti; a döntés végleges.", "say": "Biztos vagyok benne – a döntés érvényes."}, {"en": "Did anyone see a piece come off?", "meaning": "A bírónak kétsége van, és csak tanácsot kér a rottétől; a döntést továbbra is ő hozza.", "say": "Látta valaki, hogy levált egy darab?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Ez a döntés fellebbezhető; írásos fellebbezés és letét kell hozzá.", "say": "Írásban, letéttel a zsűrihez fordulhat."}, {"en": "Please carry on shooting.", "meaning": "A döntés végleges; folytasd most, különben az utasítás megtagadásának számít.", "say": "Kérem, folytassa a lövést."}], "quiz": [{"q": "A lövészed szerint egy nullának értékelt korong találat volt, de már kérte a következő korongot. Óvást tehet még a döntés ellen?", "options": ["Igen, a kör végén", "Igen, írásban a zsűrihez", "Nem: a következő korong kérése az előző döntés elfogadását jelenti", "Igen, ha a rotte egyetért"], "answer": 2, "why": "A következő korong kérésével a lövész elfogadja az előző döntést, az egy/nulla döntések pedig amúgy sem kerülhetnek a zsűri elé."}, {"q": "Melyik döntés ellen LEHET a zsűrihez fellebbezni?", "options": ["Hogy a korong egy volt-e vagy nulla", "„No bird”", "Hogy a röppálya szabályos volt-e", "Egy másik bírói döntés, például késésért kiszabott büntetés"], "answer": 3, "why": "Az egy/nulla, a „No bird” és a röppályára vonatkozó döntés végleges; más bírói döntések írásban, letét mellett a zsűri elé kerülhetnek."}, {"q": "A Parcours de Chasse – Sporting™ versenyszámban mekkora a zsűrihez benyújtott írásos fellebbezés letétje?", "options": ["A nevezési díj 40%-a", "A teljes nevezési díj", "Fix 50 euró", "Nem kell letét"], "answer": 0, "why": "A Sporting™ szabályai a letétet a nevezési díj 40%-ában határozzák meg; ha a zsűri a lövésznek ad igazat, visszaadják."}]}, {"id": "referee-categories", "minutes": 5, "title": "Kategóriák: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Az abszolút rangsor mellett, ahol mindenki együtt versenyez, a FITASC-versenyeken a lövészeket életkor és nem szerinti kategóriákban is rangsorolják. 2027. január 1-jétől a Parcours de Chasse – Sporting™ és a Compak® Sporting nemzetközi táblázata hat kategóriát tartalmaz: Junior (13–20), Lady (hölgy, 13 évtől), Men (férfi, 21–55), Senior (szenior, 56–65), Veteran (veterán, 66–72) és Master (73 évtől, férfiak és nők). Az ennél korábbi versenyeknél nézd meg a FITASC honlapján az akkor érvényes táblázatot.", "A születési év számít, nem a születésnap. A lövész annak az évnek január 1-jén lép új kategóriába, amelyben eléri az adott életkort. A 2027-es szezonban ez azt jelenti: Junior 2007–2014 között születettek, Men 1972–2006, Senior 1962–1971, Veteran 1955–1961, Master 1955 előtt születettek. A határok minden szezonban egy évvel tolódnak.", "A legnagyobb tolmácscsapda a „Senior”. A hétköznapi angolban „felnőttnek” hangozhat, de a FITASC-ban a Senior az 56–65 éves korcsoportot jelenti; a fő felnőtt kategória a Men. Ne fordítsd „felnőttek”-nek. A „Master” is csapda: a 73 év feletti FITASC-korcsoportnak semmi köze az NSCA „Master class”-ához, amely tudásszint.", "A csapatoknak saját szabályaik vannak: általában három lövész, de a Sporting™ Men csapata négyfős. Az a junior, akit a Men csapatba, vagy az a junior lány, akit a Lady csapatba soroltak, egyéniben is köteles abban a kategóriában nevezni. A nemzeti szövetségek és a klubok saját kategóriákat is használhatnak, ezért mindig nézd meg a verseny programját, és a szétlövéseknél ne feledd, hogy a kategóriáknak saját dobogójuk van."], "key_points": ["Hat FITASC-kategória 2027-től: Junior, Lady, Men, Senior, Veteran, Master", "A születési év dönt; az új kategória január 1-jén kezdődik", "Senior = 56–65, nem „felnőttek”; a fő felnőtt kategória a Men", "FITASC Master (73+) ≠ NSCA Master class", "3 fős csapatok; a Sporting™ Men csapata = 4; a nemzeti programok eltérhetnek"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Nevezéskor kérdezik: Junior, Lady, Men, Senior, Veteran vagy Master.", "say": "Melyik kategóriában lősz?"}, {"en": "He’s a Senior now.", "meaning": "Ebben a szezonban az 56–65 évesek csoportjában van.", "say": "Ő már szenior."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Első lett a hölgyek között, és negyedik az abszolút rangsorban.", "say": "Megnyerte a Lady kategóriát, és abszolútban negyedik lett."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Két vagy több veterán holtversenyben áll a harmadik helyen a kategóriájában.", "say": "Szétlövés lesz a veterán bronzéremért."}], "quiz": [{"q": "Egy 1971-ben született lövész 2027-ben FITASC-versenyen indul. Melyik kategóriában?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "2027-ben tölti be az 56. évét, így január 1-jétől Senior, akármikor is van a születésnapja."}, {"q": "Hogyan fordítsd egy ügyfélnek a FITASC „Senior” kategóriát?", "options": ["„Felnőttek”", "„Tapasztalt lövészek”", "„Élvonal”", "„Az 56–65 éves korcsoport”"], "answer": 3, "why": "A FITASC-ban a Senior az 56–65 éves korcsoport; a fő felnőtt kategória a Men."}, {"q": "Hány lövészből áll a Men csapat a Parcours de Chasse – Sporting™ versenyszámban?", "options": ["Négy", "Három", "Hat", "Öt"], "answer": 0, "why": "A csapatok általában háromfősek, de a Sporting™ Men csapata négyfős."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Biztonság és etikett", "intro": "A lőtéren a biztonság minden fordítást megelőz, a jó modor pedig nyugodtan és koncentráltan tartja a rottét. Ez a küldetés megmutatja, hogyan kell bánni a fegyverekkel, hogyan viselkednek az emberek a lőállás körül és a rottében, és mit kell viselnie mindenkinek – neked is.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Fegyverbiztonság: nyitva, üresen, biztonságos csőiránnyal", "body": ["Minden fegyvert veszélyesként kell kezelni, akkor is, ha üres. A lőálláson kívül nyitva kell vinni: a bockot megtörve az alkaron, a félautomatát nyitott zárral, a csövekkel egyenesen felfelé vagy egyenesen lefelé. Fegyverszíj nem megengedett. Amikor senki nem használja, a fegyver függőlegesen áll a fegyvertartóban. Senki nem nyúl más lövész fegyveréhez engedély nélkül.", "Töltény csak a lőálláson kerülhet a fegyverbe, a csövekkel a lőtér felé, és csak akkor, ha a bíró vagy az oktató engedi. A félautomatában legfeljebb kettő lehet. Mielőtt a lövész megfordul a lőálláson, kinyitja a fegyvert, és kivesz minden töltényt, kilőttet és ki nem lőttet egyaránt. A korongok bemutatása alatt és minden megszakításkor a fegyverek nyitva maradnak.", "Ha a fegyver nem sül el, a lövész a helyén marad, a fegyver a lőtér felé mutat, és nem nyitja ki, nem nyúl a biztosítóhoz, amíg a bíró meg nem nézte. Ez egyszerre biztonsági és pontozási szabály: a korai kinyitás a korongba kerül. A lőálláson kívül, vagy amíg más lő, szintén tilos vállba venni a fegyvert és egy elképzelt korongon végiglendíteni; a fegyvert csak a próbalövő helyen szabad kipróbálni, soha nem a versenylőálláson.", "Ha bárki azt kiáltja: „Stop!” vagy „Cease fire!” (tüzet szüntess), mindenki azonnal abbahagyja, és kinyitja a fegyvert. Ezt ne fordítsd le egy egész mondattal: ismételd hangosan, hogy „Stop!” a vendégeid nyelvén, és ellenőrizd, hogy nyitva van-e a fegyverük. Ha egy vendég fegyverrel a kezében fordul feléd, hogy kérdezzen valamit, először egy mozdulattal mutasd, hogy fordítsa lefelé a csöveket, és csak utána fordíts."], "key_points": ["A lőálláson kívül: fegyver nyitva, üresen, csövek fel vagy le, nincs fegyverszíj", "Tölteni csak a lőálláson, a lőtér felé, engedéllyel; félautomatában max. 2", "Megfordulás előtt nyisd ki és ürítsd ki; bemutatáskor és megszakításkor a fegyver nyitva", "Csütörtök után: maradj a helyeden, ne nyisd ki, várd meg a bírót", "A „Stop!”-ot megismételjük, nem magyarázzuk"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "A következő lőállásra menet a fegyver meg van törve, és nincs benne töltény.", "say": "Lőállások között nyitott, üres fegyvert kérek."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Nyisd ki a fegyvert (nem eltörni!), hogy lássam: üresek a tölténykamrák.", "say": "Törd meg a fegyvert, és mutasd, hogy üres."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Séta vagy várakozás közben nincs töltény a fegyverben.", "say": "Ne tölts, amíg nem vagy a lőálláson, és nem szólok."}, {"en": "Muzzles down when you turn round.", "meaning": "A csövek soha ne mutassanak emberekre, nyitott fegyverrel sem.", "say": "Csövet le, amikor megfordulsz."}, {"en": "Stop! Stop! Guns open!", "meaning": "Vészleállítás: hagyd abba a lövést, nyisd ki a fegyvert, várj.", "say": "Stop! Stop! Fegyvereket kinyitni!"}], "quiz": [{"q": "Hogyan kell vinni a félautomatát a lőállások között?", "options": ["Zárva, biztosítva", "Nyitott zárral, a csővel egyenesen felfelé vagy lefelé", "Fegyverszíjon a vállon", "Egy tölténnyel megtöltve"], "answer": 1, "why": "A fegyvereket nyitva kell vinni, a félautomatát nyitott zárral, a csővel egyenesen felfelé vagy lefelé; fegyverszíj nem megengedett."}, {"q": "A fegyver kattan, de nem sül el. Mit kell tennie a lövésznek?", "options": ["Azonnal kinyitni és megnézni", "Megfordulni, hogy megmutassa az edzőnek", "A helyén maradni, a fegyverrel a lőtér felé, nem kinyitni és nem nyúlni a biztosítóhoz, amíg a bíró meg nem nézi", "Biztosítani, és újra kérni a korongot"], "answer": 2, "why": "Mindkét szabálykönyv előírja, hogy a lövész maradjon a helyén, amíg a bíró meg nem vizsgálja; ha előbb kinyitja vagy a biztosítóhoz nyúl, nulla."}, {"q": "Valaki azt kiáltja: „Cease fire!”. Mi a tolmács első feladata?", "options": ["Hangosan megismételni, hogy „Stop!”, és ellenőrizni, hogy a vendégek kinyitják-e a fegyverüket", "Elmagyarázni, miért állt le a lövészet", "Megkérdezni az edzőt, mi történt", "Megvárni, amíg a vendég kérdez"], "answer": 0, "why": "A vészleállítást azonnal meg kell ismételni; magyarázat csak akkor jön, amikor minden fegyver nyitva van."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "A lőállás körül: csend, távolság, mozdulatlanság", "body": ["A lőálláson álló lövésznek teljes koncentrációra van szüksége, a töltéstől egészen addig, amíg az utolsó lövés után ki nem nyitja a fegyvert. A szabályok a várakozóhelyeket a lőállás közelébe teszik, de kimondják, hogy azok nem zavarhatják a lövészt. A gyakorlatban ez azt jelenti: halk beszéd vagy semmi, nincs hirtelen mozdulat a lövész látóterében, a fegyverek nyitva, a telefon lenémítva és zsebben. A szabályok nem említik a telefont, de minden lőtér elvárja ezt az udvariasságot.", "Maradj a lövész mögött, soha ne a lőállás mellett vagy előtt. A Compak® Sporting versenyszámban a lőszögkorlátozó (Firing Angle Limiter) keret korlátozza minden lövész lendítését; a Parcours de Chasse – Sporting™ versenyszámban sok lőtéren ketrec van a lőállásokon. Mindenki más mögötte vár, a csövek bármilyen lehetséges irányán kívül. A Compak® versenyszámban a várakozó lövész az 1-es lőállás mögött áll, és aki végzett, az úgy vár, hogy ne zavarja a következőt.", "A lövész zavarásának szabálybeli következményei vannak. Ha a bíró látja, hogy a lövészt egyértelműen megzavarták, a korong „No bird”, és újra dobják. Tilos a lövés imitálása, amíg egy rottetárs lő. Csak az a lövész lő, aki soron van, és csak a saját korongjára.", "Neked ez a lecke gyakorlati. Hallgass el, amikor a vendéged a lőállásra lép, akár mondat közben is. Ne válaszolj kérdésekre, amíg a fegyver zárva van. Csak akkor szólalj meg újra, amikor a fegyver nyitva van: korongok között, dublék között vagy a lőállás után. Egy elmaradt tanács kevesebbe kerül, mint egy dublé, amelyet a hangod rontott el."], "key_points": ["Csend, mozdulatlanság, nyitott fegyver, néma telefon a lövész mögött", "Állj a lőállás, a ketrec vagy a lőszögkorlátozó mögé, soha ne mellé vagy elé", "Az egyértelműen megzavart lövész „No bird”-öt kap", "Nincs lövésimitálás, amíg más lő", "Tolmács: csak akkor beszélj, amikor a fegyver nyitva van"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "A lövész a lőálláson van; mindenki abbahagyja a beszélgetést.", "say": "Csendet kérek hátul – ő lő."}, {"en": "Wait until he’s opened his gun.", "meaning": "Senki nem beszél és nem mozdul, amíg a lövész be nem fejezte, és ki nem nyitotta a fegyvert.", "say": "Várj, amíg kinyitja a fegyverét."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "Edzésen az edző azt akarja, hogy közvetlenül mögötte állj, a lendítés útján kívül.", "say": "Állj közvetlenül mögém, hogy azt lásd, amit én."}, {"en": "Keep out of his line, please.", "meaning": "A lövész látóterében vagy a csövek útjának közelében vagy; menj hátrébb.", "say": "Ne állj az útjába, kérlek."}], "quiz": [{"q": "Hol áll a tolmács, amíg a vendég lő?", "options": ["A lövész mellett, hogy lássa az arcát", "A lőállás előtt, hogy lássa a korongot", "A lőállás mögött, a csövek bármilyen irányán kívül", "Ahol a bíró nem látja"], "answer": 2, "why": "Mindenki a lőállás vagy a ketrec mögött vár; a lövész mellett a legveszélyesebb."}, {"q": "Egy hangos telefonbeszélgetés a lőállás mögött a lövés pillanatában egyértelműen megzavarja a lövészt. Mit dönthet a bíró?", "options": ["„No bird”: a korongot újra dobják", "Nulla a lövésznek", "Semmit, a telefon nincs benne a szabályokban", "Sárga lap a lövésznek"], "answer": 0, "why": "Ha a bíró látja, hogy a lövészt egyértelműen megzavarták, a korong „No bird”."}, {"q": "Mikor van itt az ideje továbbadni az edző megjegyzését?", "options": ["Amíg a lövész kéri a korongot", "A korong kérése és a lövés között", "Amint az edző befejezi a mondatot", "Amikor a fegyver nyitva van: korongok, dublék között vagy a lőállás után"], "answer": 3, "why": "A lövész rutinját nem szabad megszakítani; csak akkor beszélj, amikor a fegyver már nyitva van."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Jó modor a rottében", "body": ["A rotte (squad) legfeljebb hat, sorsolással összeállított lövész, akik együtt lőnek. A pontosság az első udvariasság, és egyben szabály is. A Parcours de Chasse – Sporting™ versenyszámban a hiányzó lövészt egy percen belül háromszor szólítják, a le nem lőtt korongokat pedig nullának értékelik. A Compak® Sporting versenyszámban az a lövész, aki azután érkezik, hogy a rotte első lövésze kérte a korongot, a körre 25 nullát kap, és kötelező előtte jelentkezni a bírónál.", "A sorrend számít. A Sporting™ versenyszámban a sorrend minden lőállásnál és a dubléknál is forog; a Compak® versenyszámban a lövészek minden sorozat után egy lőállással jobbra lépnek. Senki nem lép a lőállásra, amíg az előző lövész el nem hagyta. Amikor szólítják, a lövész azonnal kész, elegendő tölténnyel az egész körre.", "A bíró egyedül dönt. A rottetársak nem kommentálják, hogy egy korong találat volt-e, hacsak a bíró meg nem kérdezi őket. A döntés nyílt bírálata – lövészek vagy nézők részéről – a bíró befolyásolására tett kísérletnek számít. Az önuralom elvesztése, például a fegyver eldobása vagy bárki szidalmazása, a zsűri elé kerül, és kizárással járhat.", "A szabályokon túl szokások is vannak. A lövészek a kezdéskor általában köszöntik a bírót és a rottét, egy jó lőállás után azt mondják: „good shot” vagy „well shot” (szép lövés), hiba után pedig: „bad luck” (pech), de soha nem kommentálják egy idegen technikáját. Sok lőtéren szokás a végén megköszönni a puller és a bíró munkáját, kezet fogni, és nyugodtnak maradni, amikor kikerülnek az eredmények. Ezeket az udvariassági formákat fordítsd melegen; számítanak."], "key_points": ["Légy pontos, és jelentkezz a bírónál; a késés nullákba kerül", "Kövesd a rotációt; csak akkor lépj fel, ha a lőállás szabad", "Csak a bíró dönt; a találatokat nem kommentáljuk", "Az önuralom elvesztése kizárással járhat", "Szokások: köszönés, „szép lövés”, köszönet a pullernek és a bírónak"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "A bíró egy hiányzó lövészt szólít; ha nem jön, a korongjai nullák lesznek.", "say": "Tizenkettes – utolsó szólítás!"}, {"en": "You’re next — get ready.", "meaning": "Készülj most: szemüveg, fülvédő, töltények, de ne lépj fel, amíg a lőállás nem szabad.", "say": "Te jössz – készülj."}, {"en": "Well shot!", "meaning": "Őszinte dicséret egy jó korong vagy lőállás után.", "say": "Szép lövés!"}, {"en": "Bad luck.", "meaning": "Barátságos együttérzés hiba után, nem bírálat.", "say": "Pech."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Köszönet a bírónak és a pullernek a kör végén.", "say": "Köszönöm, bíró úr – köszönöm a dobást."}], "quiz": [{"q": "Compak® Sporting, rotte-rendszerű lövészet: a vendéged azután érkezik, hogy a rottéja első lövésze kérte az első korongot. Mi történik?", "options": ["A következő lőállásnál csatlakozik", "25 nullát kap arra a körre", "Utolsóként lő, büntetés nélkül", "A kört újraindítják"], "answer": 1, "why": "Compak® rotte-rendszerű lövészetnél a határidő a rotte első korongkérése; utána a késő lövész 25 nullát kap (fellebbezni lehet a zsűrihez)."}, {"q": "Egy rottetárs hangosan közli a bíróval, hogy téved egy találat ügyében. Hogyan tekintenek erre a szabályok?", "options": ["Hasznos információként", "Hivatalos óvásként", "A bíró befolyásolására tett kísérletként", "Semminek"], "answer": 2, "why": "Ha mások a bíró engedélye nélkül nyíltan bírálják a döntést, az befolyásolási kísérletnek számít; óvást csak az érintett lövész tehet."}, {"q": "A Parcours de Chasse – Sporting™ versenyszámban hogyan működik a lövési sorrend a rottében?", "options": ["Minden lőállásnál és a dubléknál is forog", "Egész napra rögzített", "Mindig a legjobb lövész kezd", "A bíró szabadon választja"], "answer": 0, "why": "A hatfős rottékat kisorsolják, és a sorrend minden lőállásnál, valamint a dubléknál is forog."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Fül, szem és öltözet – a tiéd is", "body": ["A hallásvédelem mindenkinek kötelező a lőpályán vagy annak közelében: lövészeknek, bíróknak, személyzetnek és nézőknek. A Parcours de Chasse – Sporting™ versenyszámban a lövészszemüveg kivétel nélkül kötelező a lövészeknek, a bíróknak, a személyzetnek és mindenkinek, aki egy lőállás közelében van. A Compak® Sporting versenyszámban a szemvédelemre vonatkozó szabály a versenyzőket, a bírókat és a személyzetet nevezi meg. Azt a lövészt, aki bármelyik nélkül lép a lőállásra, távollévőnek tekintik.", "Ez rád is vonatkozik. A lőállás mögött állva „a lőpálya közelében” vagy. Az elektronikus fülvédő a tolmács legjobb eszköze: tompítja a lövést, de átengedi a hangokat, így hallod az edzőt és a bírót. A víztiszta vagy színezett lövészszemüveg a lehulló korongdaraboktól is megvéd; egy sapka is segít.", "Az öltözködési szabályok a biztonságról és a tiszteletről szólnak. Rövid sort nem: csak a legfeljebb 5 cm-rel térd fölött végződő, hosszú bermudaszerű nadrág. Az ingnek legalább rövid ujjúnak kell lennie, gallérral vagy kerek, pólószerű nyakkal; csupasz felsőtestre vett mellény nem megengedett. A szandál tilos, és a Compak® versenyszámban ez edzésre és versenyre egyaránt vonatkozik. A rajtszámot a háton kell viselni, a vállak és a derék között, teljesen láthatóan, nem összehajtva vagy levágva.", "Az öltözködési vagy rajtszámszabályok első megsértése figyelmeztetéssel jár; ha nem javítják ki, büntetések következnek, egészen a zsűri általi kizárásig. Az ünnepségeken a csapattagok a nemzeti csapat öltözetét vagy elegáns nadrágot és blézert viselnek, és minden díjazottnak kötelező részt vennie a díjátadáson. Öltözz úgy, mint egy nyugodt profi: zárt cipő, semleges ruha, semmi, ami lobog vagy csillog a lövész szeme előtt."], "key_points": ["Fülvédő mindenkinek a lőpálya közelében, a nézőket és a tolmácsokat is beleértve", "Szemüveg: Sporting™ – mindenki a lőállás közelében; Compak® – versenyzők, bírók, személyzet", "Nélkülük a lövészt távollévőnek tekintik", "Bermuda legfeljebb 5 cm-rel térd fölött, ujjas felső, nincs csupasz felsőtest a mellény alatt, nincs szandál", "Rajtszám a háton, teljesen láthatóan; első szabálysértés = figyelmeztetés"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Mielőtt kimész a lőpályákra, tedd fel a szemüveget és a fülvédőt.", "say": "Szemüveg és fülvédő fel, mielőtt kijössz a klubházból."}, {"en": "Where are your ears?", "meaning": "Az „ears” itt a fülvédőt jelenti, nem magát a fület.", "say": "Hol a fülvédőd?"}, {"en": "You can’t shoot in sandals here.", "meaning": "Biztonsági okból zárt cipő kötelező.", "say": "Itt nem lőhetsz szandálban."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "A háton lévő rajtszámnak épnek és láthatónak kell lennie; különben figyelmeztetés jár.", "say": "Össze van hajtva a rajtszámod – teljesen látszania kell."}], "quiz": [{"q": "A lövészed lövészszemüveg nélkül lép a lőállásra. Hogyan kezelik a szabályok?", "options": ["Figyelmeztetést kap, és lőhet", "Lőhet, ha az edző beleegyezik", "Elveszít egy korongot", "Távollévőnek tekintik"], "answer": 3, "why": "Mindkét versenyszámban távollévőnek tekintik azt a lövészt, aki szem- vagy fülvédő nélkül áll a lőálláson."}, {"q": "Milyen rövidnadrág megengedett?", "options": ["Bármilyen sportnadrág", "Bermudaszerű nadrág, amely legfeljebb 5 cm-rel a térd fölött végződik", "Rövidnadrág csak Compak® versenyszámban", "Semmilyen rövidnadrág"], "answer": 1, "why": "A rövid sort tilos; a legfeljebb 5 cm-rel térd fölött végződő, hosszú bermudaszerű nadrág elfogadott."}, {"q": "Miért jó választás az elektronikus fülvédő egy tolmácsnak?", "options": ["Tompítja a lövést, de átengedi a hangokat", "A tolmácsoknak nem kötelező", "Teljesen elnyel minden hangot", "Felveszi, amit az edző mond"], "answer": 0, "why": "A lőpálya közelében kötelező a hallásvédelem, az elektronikus fülvédővel pedig hallod az edzőt és a bírót."}]}]}, {"id": "interpreter", "icon": "speech", "title": "A tolmács munka közben", "intro": "Itt áll össze minden, amit eddig megtanultál: mit mondhatsz és mit nem, hol állj, mely szavak csapják be még a tapasztalt nyelvészeket is, számok és mértékegységek, brit és amerikai szókincs, végül pedig egy teljes edzés az első „jó reggelt”-től a záró megbeszélésig.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "A szereped: edzés kontra verseny", "body": ["Edzésen te vagy az edző hangja. Minden utasítást teljes egészében add vissza, az edző sorrendjében és hangnemében: határozottan, ha biztonságról van szó, melegen, ha dicséretről. Ne tompítsd a bírálatot, ne tegyél hozzá olyan indokot, amelyet az edző nem mondott, és soha ne adj saját technikai tanácsot, még akkor sem, ha tudod a választ. Ha nem hallottál egy szót, kérdezz vissza, mielőtt fordítasz.", "A verseny más. A versenyző edzői irányítása (coaching) a verseny alatt a Parcours de Chasse – Sporting™ és a Compak® Sporting versenyszámban is tilos: a lövész sárga lapot kap, az ismétlés további szankciókkal jár, a bíró pedig eltávolítja a lőterületről azt, aki irányította. A bíró ráadásul egyedül dönt: a rottéban senki nem kommentálja a találatokat, és a döntés nyílt bírálata a bíró befolyásolására tett kísérletnek számít.", "És most az őszinte rész. A FITASC szabálykönyvei egyáltalán nem említik a tolmácsokat. Hogy az edző tanácsának szó szerinti továbbítása verseny közben edzői irányításnak számít-e, és hol állhat a tolmács, azt a szabályok nem mondják meg. Ez a FITASC számára nyitott kérdés, és semmilyen választ ne tüntess fel hivatalosként.", "Amíg a FITASC nem válaszol, kövesd a biztonságos gyakorlatot. Versenyen csak a bíróval, a zsűrivel és a szervezővel folytatott kommunikációt tolmácsold: szólításokat, döntéseket, figyelmeztetéseket, óvásokat, időpontokat és rottebeosztást. A verseny előtt mutatkozz be a bírónak vagy a szervezőnek, és egyeztesd, hol fogsz állni. Ha egy edző arra kér, hogy verseny közben adj tovább egy tanácsot, udvariasan utasítsd el, és mondd el, miért. Ezzel megóvod a lövészedet a sárga laptól."], "key_points": ["Edzés: az edző hangja – teljesen, ugyanabban a hangnemben, semmi sajátot", "Verseny: az edzői irányítás tilos (sárga lap, az edzőt eltávolítják)", "Nyitott FITASC-kérdés: a szabálykönyvek nem említik a tolmácsokat", "Biztonságos gyakorlat: versenyen csak a bíróval, a zsűrivel és a szervezővel folytatott kommunikációt tolmácsold", "Mutatkozz be a bírónak, és egyeztesd, hol állsz"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Edzés: add tovább teljes egészében, amikor a fegyver nyitva van.", "say": "Mondd meg neki, hogy a második korongnál felemeli a fejét."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Verseny: ez edzői irányítás. Udvariasan utasítsd el; ne add tovább.", "say": "Gyorsan – mondd meg neki, hogy a keresztezőnek adjon többet."}, {"en": "Who are you with?", "meaning": "A bíró azt kérdezi, miért vagy a lőállás közelében; mutatkozz be, és mondd meg, mi a szereped.", "say": "Ön kihez tartozik?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Eljárási kérdés a bírónak: ezt tolmácsolhatod.", "say": "Kérdezd meg a bírót, cserélhetek-e még choke-ot."}], "quiz": [{"q": "Egy versenykör alatt az edző arra kér, mondd meg a lövésznek: „more lead on the crosser”. Mit teszel?", "options": ["Gyorsan odasúgod", "A következő korong után lefordítod", "Udvariasan elutasítod: ez edzői irányítás lenne, ami tilos", "Megkéred a bírót, hogy adja tovább"], "answer": 2, "why": "Verseny alatt az edzői irányítás tilos, és a lövész sárga lapot kapna; a szabályok nem mondják meg, hogy a tanács továbbítása megengedett-e, ezért maradj a biztonságos oldalon."}, {"q": "Mit mondanak a FITASC szabálykönyvei a tolmácsokról?", "options": ["Állhatnak a lőálláson", "Bírói engedély kell nekik", "Edzőnek számítanak", "Semmit: ez nyitott kérdés"], "answer": 3, "why": "A szabálykönyvek nem említik a tolmácsokat, így a pontos helyzetük versenyen nyitott kérdés a FITASC számára."}, {"q": "Edzésen az edző azt mondja: „Not bad, but you stopped the gun.” Hogyan fordítod?", "options": ["Teljesen és ugyanabban a hangnemben, mindkét részt", "Csak a dicséretet, hogy a vendég elégedett legyen", "Csak a hibát, hogy időt spórolj", "Hozzáteszed a saját tippedet a javításra"], "answer": 0, "why": "Se nem tompítasz, se nem nagyítasz: az egész üzenetet, az edző hangnemében, semmi sajátot hozzá nem téve."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Hol állj, és mikor beszélj", "body": ["Edzésen közvetlenül a lövész mögött állj, az edző mellett, a lőállás vagy a ketrec mögött, a csövek bármilyen irányán kívül. Onnan azt látod, amit az edző: egyszerre a korongot és a csőtorkolatot, és az edző halkan szólhat hozzád. A lövész mellett a legveszélyesebb; a lőállás előtt szóba sem jöhet.", "Válaszd a pillanathoz illő módot. A konszekutív tolmácsolás (az edző beszél, szünetet tart, aztán te beszélsz) a biztonsági eligazításhoz, a lőállások közötti sétához és a záró megbeszéléshez illik. A suttogó tolmácsolás, a chuchotage lehetővé teszi, hogy az edző tovább beszéljen, miközben te hátulról a lövész fülébe súgsz; ez fárasztó, ezért váltogasd a kettőt. Egyezzetek meg egy „szünet, fordítok” jelben, például egy felemelt tenyérben.", "Az időzítés minden. A lövész rutinja a fegyver bezárásától a lövésig tart. Csak akkor beszélj, amikor a fegyver nyitva van: korongok között, dublék között, a lőállás után. A dublék között tükrözd az edző rövid jelzéseit – „more in front” (jobban elé), „head down” (fejet le), „same again” (még egyszer ugyanígy) –, a hosszú magyarázatokat pedig hagyd későbbre. Gondolj az órára: a Parcours de Chasse – Sporting™ versenyszámban a lövésznek a korongok vagy dublék között legfeljebb 15 másodperce van, a Compak® Sporting versenyszámban 10 másodperce a korong kérésére. A te szavaid is ebből az időből mennek.", "Versenyen ott várj, ahol a rotte vár, a lőállás közelében, de soha ne zavard a lövészt: az egyértelműen megzavart lövész „No bird”-öt kap, és senki nem akar ennek az oka lenni. Az elején tanuld meg az edző kézjeleit, és egyszer fordítsd le őket a vendégeidnek; utána kevésbé lesz rád szükségük, és ez jó jel."], "key_points": ["Edzés: közvetlenül a lövész mögött, az edző mellett, a csövek irányán kívül", "Konszekutív az eligazításhoz és a záró megbeszéléshez; chuchotage a lőálláson; váltogasd", "Csak akkor beszélj, amikor a fegyver nyitva van", "Rövid jelzések a dublék között; időkorlát 15 s (Sporting™) és 10 s (Compak®)", "Verseny: várj a rottéval, soha ne zavarj"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Az edző és a lövész mögött, a lendítés útján kívül.", "say": "Állj közvetlenül mögém."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Válts chuchotage-ra, és add tovább halkan a jelzést; az edző nem tart szünetet.", "say": "Fej a tuson – csak súgd oda neki, én folytatom."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "Az edző elmagyaráz egy kézjelet; egyszer fordítsd le a csoportnak.", "say": "Ha ezt csinálom – kezek szét –, az azt jelenti: jobban elé."}, {"en": "Wait — let him finish the pair.", "meaning": "Tartsd vissza a tanácsot, amíg a fegyver újra nyitva nincs.", "say": "Várj – hadd fejezze be a dublét."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Kérdezz vissza a két hallott lehetőséggel; gyorsabb, mint a „kérem, ismételje meg”.", "say": "Elnézést – azt mondtad, „alá”, vagy hogy „rá”?"}], "quiz": [{"q": "Hol állj egy edzésen Sporting™ lőálláson?", "options": ["A lövész mellett, hogy lásd a szemét", "A lövész mögött, az edző mellett, a csövek irányán kívül", "A ketrec előtt, a lövéssel szemben", "A dobógép mellett"], "answer": 1, "why": "Hátulról azt látod, amit az edző, és biztonságban maradsz; oldalt vagy elöl veszélyes."}, {"q": "Mi a chuchotage?", "options": ["Tolmácsolás, miután a beszélő szünetet tart", "A szabályok írásos fordítása", "Kézjelek fordítása", "Suttogó szinkrontolmácsolás a hallgató fülébe"], "answer": 3, "why": "A chuchotage suttogó szinkrontolmácsolás; a konszekutív a szünet-és-beszéd mód."}, {"q": "A Compak® Sporting versenyszámban mennyi ideje van a lövésznek a korong kérésére, miután az előző lőállás korongját lelőtték?", "options": ["10 másodperc", "15 másodperc", "30 másodperc", "Nincs korlát"], "answer": 0, "why": "A Compak® legfeljebb 10 másodpercet ad a korong kérésére; a Sporting™ 15 másodpercet enged a korongok vagy dublék között."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Hamis barátok a lőtéren", "body": ["A legnagyobb csapda a füst. Az edző „Smoked it!” kiáltása (vagy „inked it”, „powdered it”) tökéletes találatot jelent: a korong felhőben tűnt el. A szabályokban viszont az a korong, amelyből csak por vagy füst száll, látható darab nélkül, nulla. A „chip”, egy kis látható darab, találat. Ezért az edző „smoked it” mondatát fordítsd úgy, hogy „porrá lőtted”, a bíró „only dust” mondatát pedig úgy, hogy „csak por – nulla”.", "A pontozási szavak nem szó szerint értendők. A „dead” és a „kill” találatot jelent („egy”, „talált”), soha nem „halott”-at vagy „ölés”-t. A „lost” hiba („nulla”), nem valami, ami eltűnt vagy elkeveredett. A „dropped two” azt jelenti, hogy két korongot elhibázott. A „straight” a „25 straight” kifejezésben hibátlan sorozatot jelent, nem „egyenest”.", "Felszerelés- és helyszavak. A „trap” a dobógép, nem „csapda” (a Trap egyben olimpiai versenyszám is). A „stand” egy lőhely (lőállás), nem kiállítási „stand”; a „peg” a kijelölt lőhely, nem cövek; a „broken gun” nyitott (megtört) fegyver. A „Pull!” a korong kérése, a „pull-away” elétartási módszer, a „length of pull” tusméret (tushossz). A „card” lehet eredménylap vagy sárga, illetve piros lap. Az „on report” a lövés hangjára értendő. A „squad” a FITASC legfeljebb hatfős csoportja (rotte); a ClayAway-ben egy túra alcsoportját is így hívják.", "Más nyelvek további csapdákat rejtenek. A francia „chandelle” szinte függőleges korong (angolul teal), nem az angol chandelle. A francia „en battue” és az olasz „in battuta” hajtásos vadat jelent, nem a battue korongot; a portugál „batida” a battue korong, a „de batida” pedig hajtásost jelent. Találatnál a francia bíró azt mondja: „Bon”, az olasz: „Buono”; a puller franciául „pulleur” vagy „puller”. Az olasz szabályok más-más szót használnak a rottéra: a Parcours de Chasse – Sporting™ versenyszámban batteria, a Compak® versenyszámban squadra di tiro."], "key_points": ["Edzői „smoked it” = tökéletes találat; szabálybeli „csak por vagy füst” = nulla", "Dead / kill = találat; lost / dropped = hiba; straight = hibátlan sorozat", "Trap = dobógép; stand = egy lőhely; peg = a kijelölt hely; broken gun = nyitott fegyver", "A pull, a card, a report és a squad szónak egyaránt több jelentése van", "A francia chandelle és „en battue” eltér az angol szavaktól"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Tökéletes találat, a korong porrá vált. Nem a szabályok „csak füst” esete.", "say": "Porrá lőtted!"}, {"en": "Only dust — zero.", "meaning": "Bíró: nem vált le látható darab, tehát hiba.", "say": "Csak por – nulla."}, {"en": "Just a chip, but it’s dead.", "meaning": "Egy kis látható darab vált le: találatnak számít.", "say": "Csak megcsípte, de talált."}, {"en": "Break your gun.", "meaning": "Nyisd ki a fegyvert. Semmi köze a tönkretételhez.", "say": "Törd meg a fegyvert."}, {"en": "Step into the peg.", "meaning": "Állj a kijelölt lőhelyre.", "say": "Lépj be a lőhelyre."}, {"en": "The second one’s on report.", "meaning": "A második korongot az első lövésed hangja indítja.", "say": "A második vadászdubléban jön."}], "quiz": [{"q": "Az edző egy lövés után bekiáltja: „Smoked it!” Mi történt?", "options": ["Csak füst szállt fel: nulla", "A korong megsemmisült: tökéletes találat", "A töltény csütörtököt mondott", "Flash korong volt"], "answer": 1, "why": "Az edzői szlengben a „smoked it” tökéletes találat; a szabályokban a „csak por vagy füst” nulla – ellentétes jelentések."}, {"q": "Mi a legjobb magyar megfelelője a bíró „Lost.” szavának?", "options": ["„Elkeveredett”", "„Elveszett az idő”", "„Hiba (nulla)”", "„Eltűnt a korong”"], "answer": 2, "why": "A „lost” a hiba (nulla) pontozási szava, nem valami elveszett dolog."}, {"q": "Egy francia vendég azt mondja, imád „en battue” lőni. Mire gondol?", "options": ["Hajtásos vadra (a lövészek fölé hajtott madarakra)", "A lapos battue korongra", "Dubléban dobott korongra", "Eltört korongra"], "answer": 0, "why": "A francia „en battue” (olasz „in battuta”) hajtásos vadat jelent; a battue korong egészen más dolog."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Számok és mértékegységek: láb, yard, kaliber, sörétméret", "body": ["A brit és amerikai edzők lábban (feet) mérik az elétartást: „give it three feet” (adj neki három lábat), „a yard in front” (egy yarddal elé), „half a bird” (fél korongnyit), „a barrel's width” (egy csőszélességnyit). Ez kép, nem mérés. A mértékegységet úgy fordítsd, ahogy elhangzott – „három láb” –, és ne váltsd át egy utasítás közepén: a 0,9 m pontosnak hangzik, és megváltoztatja a jelentést. Egyszer, a foglalkozás előtt magyarázd el, hogy az edzők lábai benyomást jelentenek, a „more” (több), „less” (kevesebb), „double it” (duplázd meg) szavakat pedig pontosan úgy add tovább, ahogy elhangzanak.", "A korongok távolsága más kérdés. A „It's about thirty yards” mondható méterben is, „körülbelül” szóval („körülbelül 27 méter”), mert egy yard valamivel kevesebb egy méternél. Az irányokat gyakran számlapként adják meg: az egyenesen előre a 12 óra, így a „pick it up at eleven o'clock” kissé balra van. Tartsd meg az órát; ne alakítsd fokokká.", "A kaliber fordítva működik. A „12-bore” vagy „12 gauge” nem 12 mm; minél kisebb a szám, annál tágabb a cső, így a 20-as kaliber vékonyabb. Mindkét FITASC-szabálykönyv legfeljebb 12-es kalibert enged, legalább 66 cm-es (26 hüvelykes) csövekkel. A Parcours de Chasse – Sporting™ mellényvonala 25 cm, amit a brit lövészek egyszerűen tíz hüvelyknél valamivel kevesebbnek mondhatnak.", "Töltények: a FITASC legfeljebb 28 g ólmot enged, ami közel van a brit lövészek által emlegetett „one-ounce load”-hoz (egyunciás töltethez), 2,0–2,5 mm-es sörétekkel. A sörétszámok nem minden országban azonosak: a 9-es szinte mindenhol kb. 2 mm, de más számok kissé eltérhetnek a brit, az amerikai és a kontinentális rendszerben. Ha számít, kérj millimétert. A szűkületek megadhatók névvel, törttel vagy „thou”-ban (hüvelyk ezredrészében); abban a rendszerben fordíts, amelyet az edző használt."], "key_points": ["A lábban megadott elétartás kép: tartsd meg a mértékegységet, utasítás közben soha ne váltsd át", "Korongtávolság: a yardból lehet „körülbelül … méter”", "Számlap az irányokhoz: 12 = egyenesen előre", "12 gauge ≠ 12 mm; FITASC-maximum a 12-es kaliber, cső ≥ 66 cm (26 hüvelyk)", "28 g ≈ egy uncia; sörét 2,0–2,5 mm; a sörétszámok országonként eltérnek – kérj mm-t"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "Az elétartás képe, amelyet az edző szeretne; érzékelt távolság, nem mért.", "say": "Adj neki három lábat."}, {"en": "Half that.", "meaning": "Az előző elétartás felét használd.", "say": "Annak a felét."}, {"en": "Pick it up at eleven o’clock.", "meaning": "A korongot kissé balra keresd az egyenesen előre iránytól.", "say": "Tizenegy óránál vedd fel."}, {"en": "It’s about forty yards out.", "meaning": "A korong nagyjából 37 méterre van.", "say": "Körülbelül negyven yardra van."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Tégy egy 9-es sörétű (kb. 2 mm-es) töltényt az alsó csőbe, amely általában először sül el.", "say": "Az alsó csőbe kilencest tegyél."}], "quiz": [{"q": "Az edző azt mondja: „Give it four feet.” Mi a legjobb tolmácsolás?", "options": ["„Elétartás – körülbelül 1,22 méter”", "„Elétartás – négy láb”", "„Lőj négy méterrel messzebbre”", "„Négy koronggal előre”"], "answer": 1, "why": "A lábban megadott elétartás kép; ha utasítás közben átváltod, hamis pontosságot adsz hozzá, és megváltoztatod az üzenetet."}, {"q": "Mi a legnagyobb megengedett kaliber a FITASC Sporting™ és Compak® versenyszámban?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Mindkét szabálykönyv legfeljebb 12-es kalibert enged; a kisebb kaliberszám tágabb furatot jelent, így a 10-es nem megengedett."}, {"q": "Egy brit vendég azt kérdezi, szabályosak-e az „one-ounce” töltényei egy FITASC-versenyen. Mit tudsz?", "options": ["A FITASC-korlát 28 g ólom (+2%), ami nagyjából egy uncia", "A FITASC 36 g-ot enged", "Bármilyen töltet megengedett", "Csak 24 g megengedett"], "answer": 0, "why": "A szabályok legfeljebb 28 g ólmot engednek +2% tűréssel; egy uncia kb. 28 g. A sörétméretnek (2,0–2,5 mm) is meg kell felelnie."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Brit és amerikai szavak kontra FITASC", "body": ["Sok edző, akivel dolgozni fogsz, az English Sportingon nőtt fel, amelyet Angliában a CPSA irányít, vagy az amerikai Sporting Claysen az NSCA alatt. A szavak hasonlítanak a FITASC-éira, de a mögöttük álló szabályok nem, és a legnagyobb különbség a fegyver helyzete.", "Az English Sportingban és az NSCA-ban a lövész kezdhet „gun up”, vagyis már vállba vett fegyverrel a korong kérése előtt. A Parcours de Chasse – Sporting™ versenyszámban ez nem megengedett: a tus a mellényen lévő vonal alatt marad, amíg a korong meg nem jelenik, és minden korongra vállból kell lőni. A Compak® Sporting a kettő között van: a korong kérésekor a fegyver helyzete szabad. Így a „pre-mount this one” edzésen gyakorlat, FITASC Sporting™ versenyen viszont sárga lap. Fordítsd le, és ha a vendég versenyezni készül, kérdezd meg az edzőt, megemlítsd-e a szabályt.", "A dubléknak más a nevük. A „true pair” (angol és amerikai) a FITASC szimultán dubléja. A „report pair” vadászdublé. A „following pair” a FITASC rafale-ja. A „show pair” a korongok bemutatása lövés előtt. A „peg” a lőállás, a „station” a lőállás amerikai neve, a „cage” pedig a körülötte lévő keret (ketrec).", "Az eredményekről is másként beszélnek. A „HOA”, High Over All, az összetett győztes. Az AA, A, B vagy C osztály átlagokon alapuló nemzeti tudásszint, nem FITASC-korcsoport, és nem is a FITASC A, B és C nehézségi osztálya, amely a röppályákat sorolja be. Még a FITASC-on belül is eltérnek a dublék: a Sporting™ versenyszámban a dublé egy korongjára mindkét töltény mehet, a Compak® versenyszámban korongonként csak egy töltény. Mindig kérdezd meg magadtól, melyik szabálykönyvre gondol a beszélő."], "key_points": ["Gun up: az English Sportingban és az NSCA-ban megengedett, a FITASC Sporting™ versenyszámban tilos, a Compak® versenyszámban szabad", "True pair = szimultán; report pair = vadászdublé; following pair = rafale", "Peg = lőhely; station = lőállás (USA); cage = védőkeret", "HOA = összetett győztes; az AA/A/B/C osztály nem FITASC-kategória és nem nehézségi osztály", "Sporting™: mindkét lövés mehet egy korongra; Compak®: korongonként egy"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Edzésgyakorlat: vállban lévő fegyverrel kezdj. FITASC Sporting™ versenyen nem megengedett.", "say": "Ezt egyelőre indítsd vállból."}, {"en": "It’s a true pair.", "meaning": "Mindkét korong egyszerre indul (FITASC: szimultán dublé).", "say": "Ez szimultán dublé."}, {"en": "Following pair off the left trap.", "meaning": "Két korong ugyanabból a gépből egymás után (FITASC: rafale).", "say": "Rafale a bal oldali gépből."}, {"en": "Let’s see a show pair.", "meaning": "Dobjátok ki egyszer a dublét, hogy lövés előtt mindenki megnézhesse.", "say": "Nézzük meg a dublé bemutatását."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Magas nemzeti tudásszint, és a verseny összetett győztese.", "say": "AA osztályú, és tavaly ő nyerte az összetettet."}], "quiz": [{"q": "Egy brit edző azt mondja: „It's a true pair.” Mi a FITASC-kifejezés?", "options": ["Vadászdublé", "Rafale dublé", "Szimultán dublé", "Helyes dublé"], "answer": 2, "why": "A „true pair” az együtt induló két korong angol és amerikai neve, vagyis FITASC szimultán dublé."}, {"q": "Melyik versenyszámban NEM megengedett a „gun up” kezdés?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "A FITASC Sporting™ előírja, hogy a tus a mellényvonal alatt legyen, amíg a korong meg nem jelenik; a Compak® szabadon hagyja a fegyver helyzetét."}, {"q": "Egy vendég a brit eredmények között azt olvassa: „Class C”. Mi ez?", "options": ["FITASC-korcsoport", "Átlagokon alapuló nemzeti tudásszint", "A legnehezebb FITASC-röppályaosztály", "Egy tölténytípus"], "answer": 1, "why": "A brit és amerikai eredményekben az osztályok tudásszintek; a FITASC az A/B/C jelölést csak a röppályák nehézségére használja, helyette korcsoportjai vannak."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Egy teljes edzés, lépésről lépésre", "body": ["Az edzés előtt találkozz öt percre az edzővel. Egyezzetek meg egy szünetjelben, kérdezd meg, melyik módszert tanítja, és milyen szavakat használ az elétartásra, és tanuld meg a kézjeleit. Aztán a csoport összegyűlik a biztonsági eligazításra: tolmácsold konszekutívan, mondatról mondatra, határozottan és teljesen.", "Az első lőálláson az edző általában töltények nélkül kezd: szemdominancia-ellenőrzés, aztán beállás és készenléti testhelyzet. A Parcours de Chasse – Sporting™ versenyszámban a fegyver lentről indul, a mellényen lévő vonal alól; a Compak® Sporting versenyszámban a fegyver helyzete a korong kérésekor szabad. Súgd hátulról a javításait, miközben a lábakat és a kezeket igazítja.", "Ezután jön a korong kiolvasása. Az edző megmutatja, megkérdezi, hol látja először tisztán a lövész, és kijelöli a korongfelvételi pontot, a fegyvertartási pontot és a lövési pontot. Ezt a három kifejezést egész nap egységesen használd – „korongfelvételi pont”, „fegyvertartási pont”, „lövési pont” –, hogy a vendég megtanulja őket.", "Most a lövészet. A korongok között az edző két-öt szavas jelzéseket ad; te ugyanolyan hosszan, ugyanabban a sorrendben tükrözöd őket, amíg a fegyver nyitva van. Amikor az edző hibát diagnosztizál – „behind” (mögé), „over the top” (fölé), „you stopped” (megállt a cső) –, a diagnózist és a javítást együtt fordítsd. A dicséretet ugyanakkora energiával fordítsd.", "Aztán a dublék: melyik korong előbb, „eyes first, then the gun” (előbb a szem, aztán a fegyver), a második lövés. Végül a záró megbeszélés, ismét konszekutívan, ahol az edző két-három pontban összegez. Írd le őket mindkét nyelven, és add oda a jegyzetet a vendégnek. Lent egy valós mondatlánc látható abban a sorrendben, ahogyan hallani fogod."], "key_points": ["Előtte: szünetjel, módszer, elétartási szavak, kézjelek", "Biztonsági eligazítás: konszekutívan, határozottan, teljesen", "Egész nap ugyanaz a három kifejezés: felvételi, fegyvertartási, lövési pont", "Jelzések a korongok között: ugyanolyan hosszan, nyitott fegyvernél; diagnózis + javítás együtt", "Záró megbeszélés: írd le a fő pontokat mindkét nyelven"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Az edzés kezdete; az eligazítást konszekutívan és teljesen tolmácsold.", "say": "Jó reggelt mindenkinek. Mielőtt bármit megtöltenénk, egy rövid biztonsági eligazítás."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "A lőálláson kívül nincs zárt fegyver; töltés csak az edző szavára.", "say": "A fegyverek nyitva maradnak, amíg a lőálláson nem vagy, és nem mondom, hogy „tölts”."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Szemdominancia-ellenőrzés: ha az ujj elugrik, a jobb szem nem a vezérszem.", "say": "Mutass az orromra, két nyitott szemmel. Most csukd be a bal szemed."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Beállás: a lábakat oda állítsd, ahol a korongot eltalálod; dőlj kissé előre.", "say": "Az elülső láb a lövési pontra mutat, súly előre."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "Készenléti testhelyzet a Sporting™ versenyszámban: a fegyver csak a korong megjelenése után jön fel; a Compak® Sporting versenyszámban a fegyver helyzete a korong kérésekor szabad.", "say": "Fegyver lent, a tus a vonal alatt. Csak akkor vedd vállba, amikor látod."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "Az edző a korongfelvételi pontot jelöli ki.", "say": "Ezt nézd meg. Hol látod először tisztán?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "A fegyvertartási pont a felvételi és a lövési pont között, kicsivel a korong pályája alatt.", "say": "A csöveket nagyjából félútig hozd vissza, épp a vonal alá."}, {"en": "Behind it. Give it more.", "meaning": "A lövés a korong mögött ment el: több elétartás.", "say": "Mögé. Adj neki többet."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "Az elétartás képe, amelyet a lövéskor látni kell; a láb benyomás, tartsd meg a mértékegységet.", "say": "Mondjuk három láb – ezt a képet akarod látni."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Fölé ment hiba, mert az arc elvált a tustól.", "say": "Fölé. Felemelted a fejed – maradj a fegyverben."}, {"en": "Smoked it! Same again.", "meaning": "Tökéletes találat; ismételd meg pontosan, amit csináltál.", "say": "Porrá lőtted! Még egyszer ugyanígy."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Mögé ment hiba, mert megállt a lendítés; kísérd el.", "say": "Megállt a cső. Tartsd mozgásban a lövésen át."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "A nyulat a keresztezőre leadott lövés hangja indítja.", "say": "Következik egy vadászdublé: előbb a keresztező, aztán a nyúl."}, {"en": "Eyes first, then the gun.", "meaning": "A második korongot előbb a szemeddel találd meg, csak aztán mozdítsd a csöveket.", "say": "Előbb a szem, aztán a fegyver."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Guruló korongnál maradj lent, hogy egy ugrásnál is a sörétbe fusson.", "say": "A csövek maradjanak a nyúl alatt."}, {"en": "Change to quarter and half for this stand.", "meaning": "Tegyél be 1/4-es és 1/2-es szűkületet (nyitottabb, aztán kicsit szűkebb).", "say": "Ehhez a lőálláshoz cserélj negyedesre és felesre."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Az edzés vége; az edző összegez – írd le ezeket a vendégnek.", "say": "Mára ennyi. Három dolog holnapra: lábak, fej, elkísérés."}], "quiz": [{"q": "Mikor és hogyan tolmácsoljuk a biztonsági eligazítást?", "options": ["Röviden, chuchotage-ban, amíg a vendégek töltenek", "Az elején, konszekutívan, mondatról mondatra és teljesen", "Csak ha egy vendég kéri", "Az első lőállás után"], "answer": 1, "why": "A biztonság az első, és nem szabad lerövidíteni; a konszekutív mód lehetővé teszi, hogy minden szabály célba érjen."}, {"q": "Az edző azt mondja: „Behind it. Give it more.” Mi a legjobb rövid tolmácsolás a korongok között?", "options": ["„Kicsit elkéstél, próbáld újra, talán gyorsabban”", "„Mögé. Több elétartás.”", "„Lőj korábban”", "„Jó, ugyanígy”"], "answer": 1, "why": "Tükrözd az edzőt: ugyanolyan hosszan, ugyanabban a sorrendben, diagnózis és javítás, semmi hozzáadás."}, {"q": "Miért kell a „pick-up point”, „hold point” és „break point” kifejezéseket egész nap ugyanazokkal a magyar szavakkal mondani?", "options": ["A szabályok előírják", "Hogy az edző megértse a magyart", "Hogy a vendég három stabil fogalmat tanuljon meg, és ne keverje össze őket", "Nem számít"], "answer": 2, "why": "Az egységes kifejezések felépítik a vendég fejében a lőállás térképét; ha változnak a szavak, három fogalom hatnak tűnik."}]}]}]};
